#[test]
fn borrow_end_keeps_distinct_mir_successors_1869() {
    let rv = run_with_local_backend("borrow_end_same_display_successors_1869");
    let body = fact_body(rv.facts().expect("the plugin gave no facts"), "number");
    let ends: Vec<_> = fact_row(body, 14)["facts"].as_array().unwrap().iter()
        .filter(|e| e["ev"] == "BorrowEnd" && e["holder"] == "r" && e["lender"] == "n")
        .collect();
    assert_eq!(ends.len(), 3, "one end for each real successor of the match switch: {ends:?}");
    assert!(ends.iter().all(|e| e["to_line"] == 15 && e["to_col"] == ends[0]["to_col"]));
}

fn assert_skipped_field_hold(rv: &Rustviz, field: &str, lender: &str, holder: &str, last_use: &str) {
    let (code, tl) = (rv.code_panel_string(), rv.timeline_panel_string());
    let dots = rv_elements(&tl, &format!("{field}@")).into_iter().filter(|d| d.0.contains(":dot:")).collect::<Vec<_>>();
    let split = dots.iter().find(|d| d.0.ends_with(":branch")).unwrap();
    let moved = dots.iter().find(|d| d.0.ends_with(":move")).unwrap();
    let skipped_use = format!("This path has no further use of {field}.");
    let ends: Vec<_> = dots.iter().filter(|d| d.1.contains(&skipped_use)).collect();
    assert_eq!(ends.len(), 1, "one dot on the path that skips the move: {dots:?}");
    assert!(moved.2.0 < split.2.0 && split.2.0 < ends[0].2.0, "the move and own end belong to opposite arms");
    let last_use_y = code_row_y(&code, last_use);
    let branch_end_y = code_rows_y(&code, "}").into_iter().rfind(|&y| split.3.0 < y && y < last_use_y);
    let end_y = ends[0].3.0;
    assert!(split.3.0 <= end_y && end_y < last_use_y && branch_end_y.is_none_or(|close| end_y <= close),
        "the skipped end lies within the branch: {dots:?}");
    assert!(ends[0].1.contains(&format!("The borrow checker keeps {lender} borrowed until the last use of {holder}.")));
    let moved_at_join = format!("{field} was moved in at least one branch above, so it can't be used after the branches");
    let scope_end = dots.iter().find(|d| d.0.contains("ref_go_out_of_scope") && d.3.0 > last_use_y).unwrap();
    assert!(scope_end.1.contains(&moved_at_join), "the scope-end dot carries the post-join restriction: {dots:?}");
    let give_backs: Vec<_> = dot_ys(&tl, &format!("{lender}'s resource is no longer immutably borrowed")).into_iter()
        .filter(|&y| split.3.0 <= y && y <= scope_end.3.0).collect();
    assert_eq!(give_backs, vec![last_use_y]);
}

/// The iterator's borrow ends on break or exhaustion. Continue takes the
/// back edge to next(), which needs the borrow for another iteration.
#[test]
fn loop_exhaustion_end_has_a_live_column_1864() {
    let name = "exit_loop_body_all_exit";
    let rv = run_with_local_backend(name);
    let (code, tl) = (rv.code_panel_string(), rv.timeline_panel_string());
    let end = "xs's immutable borrow ends";
    let dots = rv_elements(&tl, "xs@").into_iter().filter(|d| d.0.contains(":dot:") && d.1.contains(end)).collect::<Vec<_>>();
    assert_eq!(dots.len(), 2, "{dots:?}");
    assert_eq!(dots[0].3.0, code_row_y(&code, "break;"));
    assert!(dots[1].0.starts_with("xs@L15:"), "the separate end on iterator exhaustion: {dots:?}");
    let resumed = rv_elements(&tl, "xs@L14:dot:branch_join");
    assert!(resumed.iter().any(|d| d.1.contains("next() returned None, so the loop exits instead of starting another iteration")),
        "missing exhaustion path: {resumed:?}");
    let violations = common::invariants::check(&common::invariants::parse(&tl), &read_corpus(name));
    assert!(violations.iter().all(|(inv, _)| *inv != "event-on-dead-column"), "{violations:?}");
}

#[test]
fn wildcard_item_has_iterator_exhaustion_end_1864() {
    assert_loop_exhaustion_path(10, 11, &[7]);
}

#[test]
fn sibling_arm_use_keeps_iterator_exhaustion_end_1864() {
    assert_loop_exhaustion_path(24, 25, &[21]);
}

#[test]
fn two_breaks_keep_iterator_exhaustion_end_1864() {
    assert_loop_exhaustion_path(41, 42, &[36, 38]);
}

fn assert_loop_exhaustion_path(body_end: usize, close: usize, break_ends: &[usize]) {
    let name = "loop_exhaustion_paths_1864";
    let tl = run_with_local_backend(name).timeline_panel_string();
    let resumed = rv_elements(&tl, &format!("xs@L{body_end}:dot:branch_join"));
    assert!(!resumed.is_empty(), "missing restart before loop close L{close}");
    assert_eq!(resumed.len(), 1);
    assert!(resumed[0].1.contains("next() returned None"));
    for line in break_ends.iter().copied().chain([close]) {
        let dots = rv_elements(&tl, &format!("xs@L{line}:dot:"));
        assert!(dots.iter().any(|d| d.1.contains("xs's immutable borrow ends")), "missing end at L{line}: {dots:?}");
    }
    let violations = common::invariants::check(&common::invariants::parse(&tl), &read_corpus(name));
    assert!(violations.iter().all(|(inv, _)| *inv != "event-on-dead-column"), "{violations:?}");
}

/// #1866's review, after design Q1 (P1-6B): `let maybe = if choose {
/// v.first() } else { None };` gets a row per arm, and the `if choose`
/// arm's leg reads its own cell after the arm's code: v stays borrowed
/// while maybe is in use there. (#1871's first version said "v's resource
/// is being shared by one or more variables" on that leg, and required it
/// here: on an empty v the arm gives maybe None, so no variable need hold
/// a reference; 2.x's clause stands, with the borrow checker's restriction,
/// Codex review of #1871.) The `if e` arm below (lines 12-14) is on both
/// paths, so v is only maybe borrowed there.
#[test]
fn one_line_arm_cell_and_maybe_shared_leg_1866() {
    let tl = run_with_local_backend("branch_legs_table_review_1866").timeline_panel_string();
    let shared = "v's resource is being shared by one or more variables";
    // The `if choose` arm's column: left of the `else` arm's, below the
    // borrow's dot.
    let dot = rv_elements(&tl, "v@L10:dot:static_lend");
    let (dot_x, dot_y) = (dot[0].2 .0, dot[0].3 .0);
    let legs = rv_elements(&tl, "v@L10:branch_line");
    let arm: Vec<&String> = legs.iter().filter(|e| e.2 .0 <= dot_x + 3.0 && e.3 .0 >= dot_y - 3.0 && !e.0.contains('/')).map(|e| &e.1).collect();
    assert!(!arm.is_empty() && arm.iter().all(|t| t.starts_with("v is the owner of the resource. v stays borrowed while maybe is in use")),
        "the `if choose` arm: v owned, kept borrowed while maybe is in use, got {arm:?}");
    assert!(legs.iter().all(|e| !e.1.contains(shared)), "no leg of line 10 says v is surely shared, got {legs:?}");
    // The `None` arm's diagonal: maybe's value holds no reference there.
    let maybe = rv_elements(&tl, "maybe@L10:branch_line");
    let none_dot = rv_elements(&tl, "maybe@L10:dot:acquire");
    let none_leg: Vec<&String> = maybe.iter().filter(|e| e.3 .0 >= none_dot[0].3 .0 - 3.0 && e.2 .1 > none_dot[0].2 .0 - 3.0 && !e.0.contains('/')).map(|e| &e.1).collect();
    assert!(!none_leg.is_empty() && none_leg.iter().all(|t| t.contains("maybe owns a value that can hold references")),
        "the `else {{ None }}` arm's leg after its dot, got {none_leg:?}");
    let later: Vec<String> = rv_elements(&tl, "v@L12-14:branch_line:partial_privilege").into_iter().map(|e| e.1).collect();
    assert!(!later.is_empty() && later.iter().all(|t| t.starts_with("v's resource may be immutably borrowed here (a branch above borrowed it on some paths only)")),
        "the `if e` arm: v only maybe borrowed, got {later:?}");
}

/// #1871's review (Codex): one-line conditionals whose arms get rows of
/// their own (design Q1), and the dead `else` rows (Q9(b)). Each check
/// failed on #1871's first version.
#[test]
fn one_line_arms_review_1871() {
    let rv = run_with_local_backend("one_line_arms_review_1871");
    let tl = rv.timeline_panel_string();
    let y_of = |id: &str| rv_elements(&tl, id).first().unwrap_or_else(|| panic!("no {id}")).3 .0;
    // `w.push((if flag { r } else { &b }, &c))`: the arms' rows are above
    // c's dot, and c is lent only from its dot on.
    let c_dot = y_of("c@L11:dot:static_lend");
    let above: Vec<(String, String)> = rv_elements(&tl, "c@L").into_iter()
        .filter(|e| e.0.contains(":line:") && e.3 .0 < c_dot - 1.0).map(|e| (e.0, e.1)).collect();
    assert!(!above.is_empty() && above.iter().all(|(id, t)| id.ends_with("full_privilege") && t == "c is the owner of the resource"),
        "c above its `&c` dot, got {above:?}");
    // Two conditionals on line 20: the first's arms lend s or t, so they
    // get rows of their own; the second's agree, a one-row diamond (its
    // split, arm and join rows).
    assert_eq!(y_of("s@L20:dot:branch_join#2") - y_of("s@L20:dot:branch#2"), 60.0, "the second conditional on line 20 is one row");
    assert!(y_of("s@L20:dot:branch_join") - y_of("s@L20:dot:branch") > 60.0, "the first conditional on line 20 has a row per arm");
    // `if choose { v.first() } else { None }`: v stays borrowed while maybe
    // is in use (maybe may be None), and the None arm holds no reference.
    let v: Vec<String> = rv_elements(&tl, "v@L27:branch_line:partial_privilege").into_iter().map(|e| e.1).collect();
    assert!(!v.is_empty() && v.iter().all(|t| t == "v is the owner of the resource. v stays borrowed while maybe is in use"), "got {v:?}");
    let maybe: Vec<String> = rv_elements(&tl, "maybe@L27:branch_line").into_iter().map(|e| e.1).collect();
    assert!(maybe.iter().all(|t| !t.contains("contains a reference")) && maybe.iter().any(|t| t.contains("can hold references")), "got {maybe:?}");
    // The `?` arm's state includes its early return (s dropped there): not
    // a disagreement with the other arm on the way to the join.
    assert_eq!(y_of("s@L37:dot:branch_join") - y_of("s@L37:dot:branch"), 60.0, "the conditional with a `?` in an arm is one row");
    // `if c { q = r; } else { println!("{}", q); }`: s is lent to r on both
    // arms (and to q too on the first), and q holds s's or t's borrow: the
    // arms differ, each gets a row.
    assert!(y_of("q@L66:dot:branch_join") - y_of("q@L66:dot:branch") > 60.0, "q's arms differ: a row per arm");
    // The dead `else` with its `{` on the next line: its rows are marked
    // and value is dashed there, saying why.
    let doc = roxmltree::Document::parse(&tl).expect("timeline svg parses");
    let dead = doc.root_element().attribute("data-rv-dead-rows").unwrap_or("");
    assert_eq!(dead, "53 54", "dead rows");
    let value: Vec<(String, String)> = rv_elements(&tl, "value@L").into_iter().filter(|e| e.0.contains(":line:")).map(|e| (e.0, e.1)).collect();
    assert!(value.iter().any(|(id, t)| id.ends_with("full_privilege_uninit") && t.starts_with("This else never runs")), "got {value:?}");

    // `dead_else_early` (a fn name with `else` in it): the dead rows are
    // its `else` block's (its `}` too: the `if let` arm returns, so the
    // code after it is dead as well), not the `0` after it, which is no
    // else's (#1004).
    let doc995 = run_with_local_backend("edition2024/irrefutable_iflet_inline_995").timeline_panel_string();
    let doc995 = roxmltree::Document::parse(&doc995).expect("timeline svg parses");
    assert_eq!(doc995.root_element().attribute("data-rv-dead-rows"), Some("34 35"), "995's dead rows");
    // A dead else's closing `}`, where the `if let` arm goes on, is where
    // the paths have joined: not a dead row (the drawing oracle checks the
    // point after the `if let`).
    let tl987 = run_with_local_backend("edition2024/dead_else_987").timeline_panel_string();
    let doc987 = roxmltree::Document::parse(&tl987).expect("timeline svg parses");
    assert_eq!(doc987.root_element().attribute("data-rv-dead-rows"), Some("13 23 35 45"), "987's dead rows");

    // One-line arms keep 2.x's leg title where the arm's own cell lends the
    // column the same way: the cell is read where the arm's value isn't in
    // its variable yet, so it can't name the holder unless the facts prove
    // it (the first pin below), and a title read for the row is the join's
    // hedge.
    let tip_of = |fixture: &str, id: &str| -> String {
        let tl = run_with_local_backend(fixture).timeline_panel_string();
        rv_elements(&tl, id).into_iter().find(|e| e.0 == id).unwrap_or_else(|| panic!("{fixture}: no {id}")).1
    };
    // `let r = match n { 0 => &f, _ => &g };` (#1877's arm facts read the
    // arm on its own entry edge, so the cell now proves r took f's loan on
    // the `0` arm: current, direct holder and holder_sources all say r).
    // True, probed with rustc: `let _ = &mut f;` before `println!("{}", r)`
    // is E0502 (r holds f's shared borrow), while the same `&mut f` inside
    // the `_` arm compiles (f isn't borrowed on that path). So the title
    // names r.
    assert_eq!(tip_of("one_line_arm_overlap_1264", "f@L34:branch_line:partial_privilege"), "f's resource is being shared by one or more variables. r holds a shared borrow");
    assert_eq!(tip_of("arm_ref_binding_value_1327", "o2@L19:branch_line:partial_privilege"), "o2's resource is being shared by one or more variables");
    assert_eq!(tip_of("rv3_owner_lines_1852", "x@L44:branch_line:revoked_privilege"), "x's resource is mutably borrowed by r; x can't be used until the borrow ends");
    assert_eq!(tip_of("rv3_owner_lines_1852", "y@L44:branch_line:revoked_privilege"), "y's resource is mutably borrowed by s; y can't be used until the borrow ends");
    // `let it = if c { v1.iter() } else { v2.iter() };`: v1 still owns
    // its vector while the iterator borrows it.
    assert_eq!(tip_of("branch_holder_lenders_1404", "v1@L40:branch_line:partial_privilege"), "v1 is the owner of the resource. v1 stays borrowed while it is in use");
    // A fn on one line, `if c { p.a } else { p.b }`: p's line over the
    // arms' rows is partly moved, not "the owner".
    let p = tip_of("one_line_if_on_header_row_1342", "p@L9:line:full_privilege");
    assert!(p.contains("p.a and p.b may have been moved out"), "got {p}");
}

/// The line on a straight column immediately below a source row.
fn column_line_at(svg: &str, column: &str, row: usize) -> (String, Vec<String>) {
    let doc = roxmltree::Document::parse(svg).expect("well-formed timeline");
    let lines: Vec<_> = doc.descendants()
        .filter(|n| n.attribute("data-rv-kind") == Some("line") && n.attribute("data-rv-var") == Some(column))
        .filter(|n| {
            let line = |key| n.attribute(key).and_then(|n| n.parse::<usize>().ok());
            line("data-rv-line").is_some_and(|start| start <= row)
                && line("data-rv-line-end").is_some_and(|end| row < end)
        })
        .collect();
    assert_eq!(lines.len(), 1, "{column} below row {row}: {lines:?}");
    (lines[0].attribute("data-rv-state").unwrap().to_owned(), timeline_tooltips(&svg[lines[0].range()]))
}

#[test]
fn inline_exits_end_the_runtime_path() {
    // The irrefutable arm returns on real MIR edges. Borrowck still
    // accepts a borrow on its imaginary fallthrough. Return rows, the
    // sibling else arm, and the loop's exhaustion path can all execute.
    for (fixture, dead, live) in [
        ("edition2024/irrefutable_iflet_inline_995", &["11:40:14"][..], &["11:40:13", "21:40:24"][..]),
        ("inline_exit_1004", &["8:40:11"][..], &["8:40:10"][..]),
        ("inline_exit_nested_1013", &["9:50:13", "61:47:65", "61:47:66"][..], &["9:50:16", "61:47:68"][..]),
    ] {
        let svg = run_with_local_backend(fixture).timeline_panel_string();
        let doc = roxmltree::Document::parse(&svg).unwrap();
        let unreachable: BTreeSet<_> = doc.root_element().attribute("data-rv-unreachable-rows")
            .unwrap_or("").split_whitespace().collect();
        for row in dead {
            assert!(unreachable.contains(row), "{fixture}: missing dead row {row}");
        }
        for row in live {
            assert!(!unreachable.contains(row), "{fixture}: runtime-reachable row {row} marked dead");
        }
    }
}

#[test]
fn nested_function_dead_row_does_not_hide_outer_move() {
    let name = "inline_exit_nested_body";
    let rv = run_with_local_backend(name);
    let svg = rv.timeline_panel_string();
    let doc = roxmltree::Document::parse(&svg).unwrap();
    // L9 is the inner function's imaginary tail and the outer function's
    // real drop(s). A rustc borrow probe in outer after L9 gets E0382.
    assert_eq!(doc.root_element().attribute("data-rv-unreachable-rows"), Some("4:33:8 4:33:9"));
    let src = read_corpus(name);
    let code = rv.code_panel_string();
    let (violations, _, stats) = common::oracle::check(&src, &svg, &code);
    assert!(violations.is_empty(), "{violations:?}");

    // Tag the same row in outer as well to simulate the old cross-body
    // suppression. Only then may the oracle skip its missing segment.
    let wrong_body = svg.replacen("4:33:8 4:33:9", "4:33:8 4:33:9 3:32:9", 1);
    let (_, _, wrong) = common::oracle::check(&src, &wrong_body, &code);
    let count = |stats: &common::oracle::Stats, reason| stats.skips.get(reason).copied().unwrap_or(0);
    let no_segment = "no segment on a runtime-unreachable row";
    assert!(count(&wrong, no_segment) > count(&stats, no_segment), "{stats:?} -> {wrong:?}");
    // A rejected probe is inconclusive about whether the column moved
    // on every path. Only the unscoped marker prevents probing s at all.
    let inconclusive = "rustc's verdict doesn't decide the drawn state";
    assert_eq!(count(&stats, inconclusive), count(&wrong, inconclusive) + 1);
}

#[test]
fn drawing_oracle_probes_an_explicit_segment_on_a_tagged_row() {
    let name = "inline_exit_1004";
    let rv = run_with_local_backend(name);
    let src = read_corpus(name);
    let timeline = rv.timeline_panel_string();
    let code = rv.code_panel_string();
    let (violations, _, stats) = common::oracle::check(&src, &timeline, &code);
    assert!(violations.is_empty(), "{violations:?}");
    assert_eq!(stats.skips.get("no segment on a runtime-unreachable row"), Some(&1));

    // Add a visible, false move claim at the same gap. Borrowck accepts
    // &f on its imaginary path, so the oracle must report this marker.
    let doc = roxmltree::Document::parse(&timeline).unwrap();
    let header = doc.descendants().find(|n| n.attribute("data-rv-kind") == Some("header")
        && n.attribute("data-rv-var") == Some("f")).unwrap();
    let hash = header.attribute("data-hash").unwrap();
    let x = header.attribute("x").unwrap();
    let doc = roxmltree::Document::parse(&code).unwrap();
    let y = |row| doc.descendants().find(|n| n.attribute("data-rv-kind") == Some("code_line")
        && n.attribute("data-rv-line") == Some(row)).unwrap().attribute("y").unwrap().parse::<f64>().unwrap();
    let (top, bottom) = (y("11") - 10.0, y("12"));
    let segment = format!(r#"<line data-rv-id="test-move" data-rv-kind="line" data-rv-var="f" data-rv-state="resource_moved" data-hash="{hash}" x1="{x}" x2="{x}" y1="{top}" y2="{bottom}"/>"#);
    let false_claim = timeline.replacen("</svg>", &format!("{segment}</svg>"), 1);
    let (violations, _, _) = common::oracle::check(&src, &false_claim, &code);
    assert!(violations.iter().any(|v| (v.line, v.var.as_str(), v.check) == (11, "f", "oracle-moved")), "{violations:?}");
}

#[test]
fn manually_drop_take_keeps_the_wrapper_initialized() {
    let svg = run_with_local_backend("manually_drop_by_hand").timeline_panel_string();
    // The call's argument in MIR is &mut m2. The unsafe contract removes
    // the String logically while leaving the ManuallyDrop initialized.
    for row in 14..=18 {
        let (state, tips) = column_line_at(&svg, "m2", row);
        assert_eq!(state, "manually_taken", "m2 below row {row}");
        assert_review_title(&tips[0], &[
            "m2 still holds its ManuallyDrop",
            "The String was taken out by the unsafe ManuallyDrop::take call",
            "must not be used or dropped again through the wrapper",
            "compiler does not track",
        ], &["resource is moved", "is the owner of the resource"]);
    }
    // The return value is destroyed by drop(old) on row 24. Only the
    // fresh assignment on row 25 changes the wrapper.
    for row in [23, 24] {
        let (state, tips) = column_line_at(&svg, "slot", row);
        assert_eq!(state, "manually_taken", "slot below row {row}");
        assert_review_title(&tips[0], &["The String was taken out"], &["is the owner of the resource"]);
    }
    let (state, after) = column_line_at(&svg, "slot", 25);
    assert_eq!(state, "full_privilege");
    assert_review_title(&after[0], &[], &["was taken out"]);
}

#[test]
fn manually_drop_take_survives_unrelated_join_and_raw_addresses() {
    let svg = run_with_local_backend("manually_drop_take_paths").timeline_panel_string();
    // The conditional and address formation leave the storage unchanged.
    for row in [11, 12] {
        let (_, tips) = column_line_at(&svg, "slot", row);
        assert_review_title(&tips[0], &["The String was taken out"], &["slot is the owner of the resource"]);
    }
    let (_, tips) = column_line_at(&svg, "raw_slot", 33);
    assert_review_title(&tips[0], &["The String was taken out"], &["raw_slot is the owner of the resource"]);
    // ptr::write installs fresh contents. into_inner consumes them safely.
    let (state, tips) = column_line_at(&svg, "raw_slot", 34);
    assert_eq!(state, "full_privilege");
    assert_review_title(&tips[0], &[], &["was taken out"]);
}

#[test]
fn manually_drop_take_tracks_replacement_on_one_path() {
    let svg = run_with_local_backend("manually_drop_take_paths").timeline_panel_string();
    // Only flag=true executes the first replacement. Dropping old cannot
    // restore the old slot on the flag=false path.
    for row in [24, 25] {
        let (state, tips) = column_line_at(&svg, "maybe_slot", row);
        assert_review_title(&tips[0], &["The String may already have been taken out"],
            &["is the owner of the resource", "The String was taken out"]);
        assert_eq!(state, "manually_taken");
    }
    let (state, tips) = column_line_at(&svg, "maybe_slot", 26);
    assert_eq!(state, "full_privilege");
    assert_review_title(&tips[0], &[], &["taken out"]);
}

