/// #578: on `if let Some(w) = wrap(s) && w.len() > 1` the dot where `w`
/// is initialized by `wrap` also carries the icon of the `w.len()` call.
/// The `f` glyph reaches about 6px right of the dot's centre, and the
/// arrow coming in from `wrap` used to stop at the dot's own edge, 5.25px
/// out, so its head's tip sat on the glyph. It now stops outside the icon.
#[test]
fn arrowhead_stops_before_a_call_icon_on_its_dot() {
    let tl = run_with_local_backend("edition2024/if_let_chain_first_part").timeline_panel_string();
    let arrows = arrow_points(&tl, "Move from wrap to w");
    assert_eq!(arrows.len(), 1, "{:?}", arrows);
    // The shaft is written source first and ends 12.75px short of the
    // head's tip; the arrow runs left, into `w`.
    let &(end_x, y) = arrows[0].last().unwrap();
    let tip_x = end_x - 12.75;
    let icons: Vec<f64> = start_tags(&tl, "use")
        .into_iter()
        .filter(|t| attr(t, "xlink:href") == Some("#functionDot") && num_attr(t, "y") == y)
        .map(|t| num_attr(t, "x"))
        .collect();
    assert_eq!(icons.len(), 1, "one call icon on w's row: {:?}", icons);
    assert!(tip_x - icons[0] >= 7.0,
        "the head's tip is at x={}, {}px from the call icon's centre (the glyph reaches 6px)",
        tip_x, tip_x - icons[0]);
}

/// Level straight gray arrows as (tail x, head tip x, y). A shaft is written
/// source first and stops 12.75px short of the head's tip.
fn level_arrows(svg: &str) -> Vec<(f64, f64, f64)> {
    let mut out = Vec::new();
    for t in start_tags(svg, "polyline") {
        if !is_arrow_shaft(t) {
            continue;
        }
        let pts: Vec<f64> = attr(t, "points")
            .unwrap_or("")
            .split(|c: char| c == ' ' || c == ',')
            .filter_map(|v| v.parse().ok())
            .collect();
        if pts.len() != 4 || pts[1] != pts[3] {
            continue;
        }
        let dir = if pts[2] > pts[0] { 1.0 } else { -1.0 };
        out.push((pts[0], pts[2] + 12.75 * dir, pts[1]));
    }
    out
}

/// Pairs of level arrows that run into each other: one's head lands within
/// 15px of where the next starts, in the same direction on the same row. They
/// read as one long arrow passing through the dot between them (#577).
fn chained_level_arrows(svg: &str) -> Vec<String> {
    let arrows = level_arrows(svg);
    let mut out = Vec::new();
    for (i, &(tail, tip, y)) in arrows.iter().enumerate() {
        for (j, &(tail2, tip2, y2)) in arrows.iter().enumerate() {
            let same_way = (tip - tail) * (tip2 - tail2) > 0.0;
            if i != j && y == y2 && same_way && (tail2 - tip).abs() < 15.0 {
                out.push(format!("an arrow ends at x={} where another starts, both on y={}", tip, y));
            }
        }
    }
    out
}

/// #577: a reborrow's end and its lender's end on one row (`s` gives back
/// to `r`, `r` to `x`, both on `s`'s last use, the `println!`, since #599)
/// used to be drawn level, the second starting where the first ends, so
/// they read as one long arrow through `r`'s dot. The second dips half a
/// row instead.
#[test]
fn chained_return_arrows_are_visibly_separate() {
    for name in [
        "match_local_ref_reborrow",
        "match_ref_param_reborrow",
        "match_mut_ref_param_reborrow",
    ] {
        let tl = run_with_local_backend(name).timeline_panel_string();
        assert_eq!(chained_level_arrows(&tl), Vec::<String>::new(), "{}", name);
    }
    let rv = run_with_local_backend("match_local_ref_reborrow");
    let tl = rv.timeline_panel_string();
    let code = rv.code_panel_string();
    let first = arrow_points(&tl, "Return immutably borrowed resource from s to r");
    let second = arrow_points(&tl, "Return immutably borrowed resource from r to x");
    assert_eq!((first.len(), second.len()), (1, 2), "{:?} {:?}", first, second);
    let y = first[0][0].1;
    // Both returns are on `s`'s last use (#599), so they still chain.
    assert_eq!(y, code_row_y(&code, "println!(\"{}\", s);"), "s's return isn't on its last use: {:?}", first);
    // The arm's return from `r` to `x` (the other one is the `None` arm's, a
    // row lower) starts on `s`'s row and goes below it, not along it.
    let arm = second
        .iter()
        .find(|p| p[0].1 - y < 20.0 && p[0].1 >= y - 1.0)
        .expect("r's return in the arm");
    assert!(arm.len() > 2 && arm.iter().any(|&(_, py)| py > y + 5.0),
        "r's return should leave the row s's return ends on: {:?}", arm);
    // The dip is the only change: half a row at most below the line (not a
    // full row), no row is added to the code panel for it, and a later
    // line's arrow (the `None` arm's return) is still on its own line.
    let lowest = arm.iter().map(|&(_, py)| py).fold(f64::MIN, f64::max);
    assert!(lowest <= y + 15.0 + 0.5, "r's return dips to y={}, more than half a row below y={}", lowest, y);
    let none_arm = second.iter().find(|p| p[0].1 > y + 20.0).expect("r's return in the None arm");
    assert_eq!(none_arm[0].1, code_row_y(&code, "None => {}"), "the None arm's line moved: {:?}", none_arm);
    assert_eq!(unnumbered_code_rows(&code), 0, "a blank row was added for the dip");
}

/// A `ref` / `ref mut` binding in a match arm returns its borrow at its
/// last use, where the borrow checker ends it, not at the end of the arm
/// (#599). The lender is used again later in the same arm (which only
/// compiles because the borrow has ended); the borrow must end on a row
/// above that use, and the lender's "being shared" segment must not
/// reach it.
#[test]
fn match_ref_binding_borrow_ends_at_last_use() {
    // (fixture, lender, who it lends to, the pattern binding,
    // mutability, the lender's later use)
    for (name, lender, borrower, binding, m, later) in [
        ("match_ref_binding_last_use", "t.0", "x", "x", "immutabl",
         "t.0's resource is mutably borrowed by push_str; t.0 can't be used while the borrow is live"),
        ("match_ref_binding_last_use_arms", "o", "s", "s", "immutabl",
         "o's resource is mutably borrowed by take; o can't be used while the borrow is live"),
        ("match_ref_mut_guard_last_use", "o", "s", "s", "mutabl",
         "o's resource is immutably borrowed by println!; o is read-only while the borrow is live"),
        // `x` reborrows through `o` (`o: &(String, String)`).
        ("match_shared_ref_binding_last_use", "t", "o", "x", "immutabl",
         "t.0's resource is mutably borrowed by push_str; t.0 can't be used while the borrow is live"),
    ] {
        let rv = run_with_local_backend(name);
        let tl = rv.timeline_panel_string();
        let y = |text: &str| -> f64 {
            dots_listing_tooltip(&tl, text).into_iter().map(|d| d.1).reduce(f64::min)
                .unwrap_or_else(|| panic!("{}: no dot {:?}", name, text))
        };
        let only = if m == "mutabl" { "can't be used" } else { "is read-only" };
        let lent = y(&format!("{0}'s resource is {1}y borrowed by {2}; {0} {3} while the borrow is live", lender, m, borrower, only));
        let back = y(&format!("{}'s resource is no longer {}y borrowed", lender, m));
        let used = y(later);
        assert!(lent < back && back < used,
            "{}: {} is lent at y={}, gets it back at y={}, is used again at y={}",
            name, lender, lent, back, used);
        // The binding's own column says so on the same row, before it
        // goes out of scope at the arm's end.
        let ends = y(&format!("{}'s {}e borrow ends", binding, m));
        let gone = y(&format!("{} goes out of scope", binding));
        assert!(ends == back && ends < gone,
            "{}: {}'s borrow ends at y={} (the lender gets it back at y={}), it goes out of scope at y={}",
            name, binding, ends, back, gone);
        let lent_state = format!("{}'s resource is being shared", lender);
        let reach = start_tags(&tl, "line")
            .into_iter()
            .filter(|t| timeline_tooltips(t).iter().any(|x| x.starts_with(&lent_state)))
            .map(|t| num_attr(t, "y2"))
            .fold(0.0, f64::max);
        assert!(reach <= back,
            "{}: {}'s \"being shared\" segment runs to y={}, past the borrow's end at y={}",
            name, lender, reach, back);
    }
}

/// Dots in a timeline panel whose tooltip lines satisfy `want` and that
/// no `<line>` reaches: none ends within a few pixels of the dot's centre
/// or runs through it.
fn lone_dots(svg: &str, want: impl Fn(&[String]) -> bool) -> Vec<(f64, f64, Vec<String>)> {
    let lines = svg_lines(svg);
    let reached = |cx: f64, cy: f64| lines.iter().any(|&(x1, y1, x2, y2)| {
        let end = |x: f64, y: f64| (x - cx).abs() <= 6.0 && (y - cy).abs() <= 6.0;
        let through = (x1 - x2).abs() < 0.01
            && (x1 - cx).abs() <= 3.0
            && y1.min(y2) - 1.0 <= cy
            && cy <= y1.max(y2) + 1.0;
        end(x1, y1) || end(x2, y2) || through
    });
    let mut out = Vec::new();
    for tips in tooltip_lines(svg) {
        if !want(&tips) {
            continue;
        }
        for (x, y) in dots_where(svg, |l| l == tips.as_slice()) {
            if !reached(x, y) {
                out.push((x, y, tips.clone()));
            }
        }
    }
    out.sort_by(|a, b| a.partial_cmp(b).unwrap());
    out.dedup();
    out
}

/// #700, #722: a reference column's line runs to the reference's last
/// use. Main stopped it early, so the use (or the next event) was a dot
/// no line reached, and the reference looked dead where it is read:
/// - after `y = &x;` (and `hold = H { r: &t };`, `r = s;`, `m = n;`,
///   `t = first(&y, &x);`), whose end of the old borrow was recorded
///   after the new one and ended the column;
/// - after `hold = other;` (moving a struct over one that holds a
///   reference) and `(r1, r2) = (r2, r1);`, whose end of the old borrow
///   is drawn on a row below the assignment;
/// - after `q = &mut s;` gives a moved-out `&mut` a new reference;
/// - after a `return &s[..]` inside an `if` in a loop (Book ch. 4), on
///   a path that goes on to use s.
#[test]
fn reference_column_reaches_its_last_use() {
    // A scope end stands alone after the column ended, as does a
    // temporary's drop.
    let skip = |tips: &[String]| tips.iter().any(|t| {
        t.split_once(" goes out of scope").is_some_and(|(who, _)| !who.contains(' '))
            || t.contains("temporary")
    });
    for name in [
        "basic_if7",
        "basic_if12",
        "basic_while",
        "borrow_field_overwrite_direct",
        "borrow_struct_overwrite_call",
        "borrow_struct_overwrite_whole",
        "borrow_struct_moved_over",
        "fn_ret_ref_reassign",
        "moved_ref_state",
        "mutref_moved_on",
        "ref_swap_keeps_borrow",
        "book/c4_09_first_word_str",
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        assert_eq!(lone_dots(&timeline, |t| !skip(t)), Vec::new(), "{}: dots no line reaches", name);
    }
    // advanced_deref, aliasing2 and ref_reassign_wording also have dots
    // of a reference while it is itself mutably reborrowed (`m = n;`
    // lends n to m); its column is dotted then (#722), and those dots
    // are checked with the other lent-out columns in
    // `no_dot_of_a_lent_out_column_floats`.
}

/// The faint dotted lines of columns that are mutably lent out
/// (`class="lent"`, #722), as `(x1, y1, x2, y2)`.
fn lent_lines(svg: &str) -> Vec<(f64, f64, f64, f64)> {
    start_tags(svg, "line")
        .into_iter()
        .filter(|t| attr(t, "class").is_some_and(|c| c.split(' ').any(|c| c == "lent")))
        .map(|t| (num_attr(t, "x1"), num_attr(t, "y1"), num_attr(t, "x2"), num_attr(t, "y2")))
        .collect()
}

/// Where the dotted lent-out lines of a timeline panel start and stop:
/// the ends of `lent_lines` that no other dotted line continues from.
fn lent_line_ends(svg: &str) -> Vec<(f64, f64)> {
    let lines = lent_lines(svg);
    let ends: Vec<(f64, f64)> = lines.iter().flat_map(|&(x1, y1, x2, y2)| [(x1, y1), (x2, y2)]).collect();
    let same = |a: (f64, f64), b: (f64, f64)| (a.0 - b.0).abs() < 0.01 && (a.1 - b.1).abs() < 0.01;
    let mut out: Vec<(f64, f64)> = ends.iter()
        .filter(|&&p| ends.iter().filter(|&&q| same(p, q)).count() == 1)
        .copied()
        .collect();
    out.sort_by(|a, b| a.partial_cmp(b).unwrap());
    out
}

/// #722: while a column is mutably lent out (an owner `&mut`-borrowed, a
/// `&mut` reference mutably reborrowed) it can't be used, and main drew
/// no line for it: the events of the lend (a borrow through it, a
/// sub-borrow ending, the end of the lend) floated off their column. It
/// now draws a faint dotted line exactly over the lend, borrow-checker
/// view: from the lender's dot where the borrow starts to the dot where
/// it ends, in each arm of a conditional to that arm's end of it. Each
/// case lists every end of the dotted lines in the snippet as the dot
/// (one of its texts, and its source line, the nth time that line
/// appears) it must sit on.
#[test]
fn a_column_lent_out_mutably_is_dotted_until_the_borrow_ends() {
    for (name, ends) in [
        ("deref_write_ends_borrow", &[
            ("v's resource is mutably borrowed by x; v can't be used while the borrow is live", "let x = &mut v[0];", 0),
            ("v's resource is no longer mutably borrowed", "*x += 1;", 0),
            ("v's resource is mutably borrowed by it; v can't be used while the borrow is live", "let mut it = v.iter_mut();", 0),
            // `while let` holds `it`'s borrow until the loop ends.
            ("v's resource is no longer mutably borrowed", "}", 0),
        ][..]),
        ("reborrow_kinds", &[
            ("a's resource is mutably borrowed by ra; a can't be used while the borrow is live", "let ra = &mut a;", 0),
            ("a's resource is no longer mutably borrowed", "ra.push_str(\"?\");", 0),
            ("the resource ra points to is mutably borrowed by ra2 through ra; ra can't be used while the borrow is live",
             "let ra2 = &mut *ra; // mutable reborrow: ra unusable while ra2 is live", 0),
            ("ra2 no longer borrows the resource ra points to", "ra2.push_str(\"!\");", 0),
            ("b's resource is mutably borrowed by rb; b can't be used while the borrow is live", "let mut rb = &mut b;", 0),
            ("b's resource is no longer mutably borrowed", "rb2.push_str(\"!\");", 0),
            // rb2 = &mut rb borrows rb itself (#914).
            ("rb is mutably borrowed by rb2; rb can't be used while the borrow is live",
             "let rb2 = &mut rb; // fresh mutable borrow of rb: &mut &mut String", 0),
            ("rb is no longer mutably borrowed", "rb2.push_str(\"!\");", 0),
        ][..]),
        ("closure_capture_through_ref", &[
            ("s's resource is mutably borrowed by r; s can't be used while the borrow is live", "let r = &mut s;", 0),
            ("s's resource is no longer mutably borrowed", "println!(\"{}\", len());", 0),
            ("the resource r points to is captured by closure f (a mutable reborrow through r); r can't be used while the borrow is live",
             "let mut f = || r.push('b');", 0),
            ("f no longer borrows the resource r points to", "f();", 0),
            ("n's value is mutably borrowed by p; n can't be used while the borrow is live", "let p = &mut n;", 0),
            ("n's value is no longer mutably borrowed", "g();", 0),
            ("the value p points to is captured by closure g (a mutable reborrow through p); p can't be used while the borrow is live",
             "let mut g = || *p += 1;", 0),
            ("g no longer borrows the value p points to", "g();", 0),
            ("t's resource is captured (mutably borrowed) by closure h", "let mut h = || t.push('x');", 0),
            ("t's resource is no longer mutably borrowed", "h();", 0),
        ][..]),
        // In a conditional: each arm's dotted line ends where the borrow
        // ends on that arm's path (at r's last use in the `if`, as the
        // `else` starts on the other).
        ("outer_mut_ref_end_in_if_arm", &[
            ("s's resource is mutably borrowed by r; s can't be used while the borrow is live", "let r = &mut s;", 0),
            ("s's resource is no longer mutably borrowed", "r.push('x');", 0),
            ("s's resource is no longer mutably borrowed", "} else {", 0),
        ][..]),
        // A `&mut` parameter reborrowed by a `match` arm's binding.
        ("match_mut_ref_param_reborrow", &[
            ("the resource o points to is mutably borrowed by s through o; o can't be used while the borrow is live", "Some(s) => {", 0),
            ("s no longer borrows the resource o points to", "s.push('!');", 0),
        ][..]),
    ] {
        let rv = run_with_local_backend(name);
        let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let mut want: Vec<(f64, f64)> = ends.iter().map(|&(text, src, nth)| {
            let row = code_rows_y(&code, src)[nth];
            let dots: Vec<(f64, f64)> = dots_listing_tooltip(&tl, text).into_iter().filter(|d| d.1 == row).collect();
            assert_eq!(dots.len(), 1, "{}: one dot {:?} on the row of `{}`", name, text, src);
            dots[0]
        }).collect();
        want.sort_by(|a, b| a.partial_cmp(b).unwrap());
        assert_eq!(lent_line_ends(&tl), want, "{}: where the dotted lent-out lines end", name);
    }
}

/// #722: no dot of a column floats off it while the column is mutably
/// lent out. Main drew no line then, and left these dots alone:
/// - a lender's events during the lend (another `&mut` taken from the
///   holder: "v's resource is mutably borrowed by y", "v's resource is
///   no longer borrowed by y, but is still mutably borrowed by it");
/// - a mutably reborrowed reference getting access back on the row its
///   own borrow ends.
#[test]
fn no_dot_of_a_lent_out_column_floats() {
    // A scope end stands alone after the column ended, as does a
    // temporary's drop.
    let skip = |tips: &[String]| tips.iter().any(|t| {
        t.split_once(" goes out of scope").is_some_and(|(who, _)| !who.contains(' '))
            || t.contains("temporary")
    });
    for name in [
        "deref_write_ends_borrow",
        "holder_ref_ends_first",
        "holder_iter_mut",
        "holder_ref_param_iter_mut",
        "call_reborrow_kinds",
        "ref_move_copy_wording",
        "advanced_deref",
        "ref_reassign_wording",
        "field_mut_borrow_through_ref",
        "aliasing2",
        "reborrow_kinds",
        "closure_capture_through_ref",
        "match_mut_ref_param_reborrow",
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        assert!(!lent_lines(&timeline).is_empty(), "{}: no dotted lent-out line", name);
        assert_eq!(lone_dots(&timeline, |t| !skip(t)), Vec::new(), "{}: dots no line reaches", name);
    }
}

/// #700: when a reference gets a new reference on a row where its old
/// borrow ends, the row's dot lists the end first: "w's immutable borrow
/// ends • w immutably borrows a value". Main listed the new borrow first,
/// which reads as if the new borrow ended at once.
///
/// #745: the old borrow only ends on the write's row when the old
/// reference is live up to the write (`w = pick(w, &q);` reads it there;
/// a whole struct overwritten, #538). A reference that isn't read again
/// before it is given a new one is dead until then, so rustc ends its old
/// loan at its last use, and the write's row has only the new borrow.
/// (#700 listed advanced_deref, advanced_deref2, basic_if12's `c = &z;`
/// and `c = &s;`, and ref_reassign_wording's `r = s;` and `m = n;` here;
/// rustc ends each of those old loans before the write, as the second
/// list below checks.)
#[test]
fn reassigned_reference_ends_its_old_borrow_first() {
    for (name, end, start) in [
        ("borrow_struct_overwrite_whole", "hold.r's immutable borrow ends", "hold.r immutably borrows a resource"),
        ("borrow_struct_overwrite_whole", "p.a's immutable borrow ends", "p.a immutably borrows a resource"),
        ("borrow_end_nll_loop", "w's immutable borrow ends", "w immutably borrows a value"),
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        let at = |l: &[String], t: &str| l.iter().position(|x| x == t);
        let in_order = dots_where(&timeline, |l| matches!((at(l, end), at(l, start)), (Some(e), Some(s)) if e < s));
        let reversed = dots_where(&timeline, |l| matches!((at(l, end), at(l, start)), (Some(e), Some(s)) if s < e));
        assert!(!in_order.is_empty() && reversed.is_empty(),
            "{}: want a dot listing \"{}\" before \"{}\" (got {:?} in that order, {:?} reversed)",
            name, end, start, in_order, reversed);
    }
    // The old loan's last use comes before the write (rustc accepts a
    // write to the old lender in between, e.g. `c += 1;` after
    // advanced_deref's `println!("c value {}", **z);`): the old borrow
    // ends on a row from that last use (`nth` occurrence of `used`) to
    // above the write, and the write's dot has only the new borrow.
    for (name, used, nth, write, end, start) in [
        ("advanced_deref", "println!(\"c value {}\", **z);", 0, "y = &x;", "y's immutable borrow ends", "y immutably borrows a value"),
        ("advanced_deref2", "let mut y = & mut x;", 0, "y = &mut c;", "y's mutable borrow ends", "y mutably borrows a value"),
        ("basic_if12", "c = &y; // c -> y {x} // (returns x)", 0, "c = &z; // c -> z {y, x} (returns y)", "c's immutable borrow ends", "c immutably borrows a value"),
        ("basic_if12", "c = &z; // c -> z {y, x} (returns y)", 0, "c = &s; // c -> s (returns y)", "c's immutable borrow ends", "c immutably borrows a value"),
        ("ref_reassign_wording", "println!(\"{}\", r);", 1, "r = s;", "r's immutable borrow ends", "r is assigned a copy of s's reference"),
        ("ref_reassign_wording", "m.push('1');", 0, "m = n;", "m's mutable borrow ends", "m mutably borrows a resource"),
    ] {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let (used_y, write_y) = (code_rows_y(&code, used)[nth], code_row_y(&code, write));
        // (basic_if12's `c = &y;` is not among them: x's loan lives on
        // the path that skips the `if`, so it ends after the join, #778.)
        let combined: Vec<f64> = dots_where(&timeline, |l| l == [end, start]).into_iter().map(|d| d.1).collect();
        assert!(!combined.contains(&write_y),
            "{}: `{}` has a dot \"{} • {}\", but the old borrow ended earlier", name, write, end, start);
        let starts: Vec<f64> = dots_listing_tooltip(&timeline, start).into_iter().map(|d| d.1).collect();
        assert!(starts.contains(&write_y), "{}: no dot on `{}` lists {:?}: {:?}", name, write, start, starts);
        let ends: Vec<f64> = dots_listing_tooltip(&timeline, end).into_iter().map(|d| d.1).collect();
        assert!(!ends.contains(&write_y), "{}: the dot on `{}` lists {:?}", name, write, end);
        assert!(ends.iter().any(|&y| used_y <= y && y < write_y),
            "{}: no {:?} from `{}` (y={}) to above `{}` (y={}): {:?}", name, end, used, used_y, write, write_y, ends);
    }
}

/// #770: the old loan of a reassigned reference ends where rustc ends it
/// on the path that reaches the write, not at the write. (1) The loan is
/// dead on the way to `c = &y;` but lives on the path that skips the `if`;
/// (2) a reference that borrows from either of two lenders ends both.
/// Each lender is writable between the end and the write: rustc accepts
/// `x += 1;` there, and rejects it on the row the end is drawn on when
/// the write is made part of the previous row's expression (checked:
/// `if { x += 1; true } { c = &y; }`, `println!("{}", { a += 1; r })`).
/// On main the lenders were drawn borrowed until the reassignment, with
/// their writes inside the borrowed span.
#[test]
fn old_loan_ends_on_the_path_that_reaches_the_write() {
    for (name, end, used, nth, write, back) in [
        ("borrow_end_two_lenders", "a's value is no longer immutably borrowed", "println!(\"{}\", r);", 0, "a += 1;", "println!(\"{} {} {}\", r, a, b);"),
        ("borrow_end_two_lenders", "b's value is no longer immutably borrowed", "println!(\"{}\", r);", 0, "b += 1;", "println!(\"{} {} {}\", r, a, b);"),
    ] {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let (used_y, write_y, back_y) = (code_rows_y(&code, used)[nth], code_row_y(&code, write), code_row_y(&code, back));
        let ends: Vec<f64> = dots_listing_tooltip(&timeline, end).into_iter().map(|d| d.1).collect();
        assert!(ends.iter().any(|&y| used_y <= y && y < write_y),
            "{}: no {:?} from `{}` (y={}) to above `{}` (y={}): {:?}", name, end, used, used_y, write, write_y, ends);
        assert!(!ends.iter().any(|&y| write_y <= y && y < back_y),
            "{}: {:?} is drawn from `{}` (y={}) on, inside the write's span (to y={}): {:?}", name, end, write, write_y, back_y, ends);
    }
    // The reassignment's dot only starts the new borrow: the old end is
    // above it.
    for (name, end, start) in [
        ("borrow_end_other_path", "c's immutable borrow ends", "c immutably borrows a value"),
        ("borrow_end_two_lenders", "r's immutable borrow ends", "r immutably borrows a value"),
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        let combined = dots_where(&timeline, |l| l.iter().any(|t| t == end) && l.iter().any(|t| t == start));
        let rows_end: Vec<f64> = dots_listing_tooltip(&timeline, end).into_iter().map(|d| d.1).collect();
        let rows_start: Vec<f64> = dots_listing_tooltip(&timeline, start).into_iter().map(|d| d.1).collect();
        assert!(combined.is_empty(), "{}: a dot lists both {:?} and {:?}: {:?}", name, end, start, combined);
        assert!(!rows_end.is_empty() && !rows_start.is_empty(), "{}: no dot with {:?} / {:?}", name, end, start);
    }
}

/// #778: a reference reassigned on one branch only (`borrow_end_join_else`, where the other arm reads it, is
/// `old_lender_ends_on_each_arm_where_it_is_borrowed_no_longer`). The old lender stays
/// borrowed until the latest end over the paths that meet after the `if`:
/// rustc rejects a write to it before that row (`x += 1;` above the
/// `println!` is E0506, checked), and accepts it right below. The end is
/// not drawn where the reference stops pointing on the path through the
/// reassignment.
#[test]
fn old_lender_stays_borrowed_until_the_latest_end_over_the_paths() {
    for (name, end, used, write) in [
        ("borrow_end_join_one_branch", "x's value is no longer immutably borrowed", "println!(\"{}\", c);", "x += 1;"),
        ("borrow_end_other_path", "x's value is no longer immutably borrowed", "println!(\"{}\", c);", "x += 1;"),
        ("basic_if12", "x's value is no longer immutably borrowed", "println!(\"c {}\", *c);", "y += 9;"),
    ] {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let used_y = *code_rows_y(&code, used).last().unwrap();
        let ends: Vec<f64> = dots_listing_tooltip(&timeline, end).into_iter().map(|d| d.1).collect();
        assert!(!ends.is_empty(), "{}: no {:?}", name, end);
        assert!(ends.iter().all(|&y| y >= used_y),
            "{}: {:?} is drawn above `{}` (y={}), though the path that skips the reassignment still borrows: {:?}", name, end, used, used_y, ends);
        if name == "borrow_end_join_one_branch" {
            let write_y = *code_rows_y(&code, write).last().unwrap();
            assert!(ends.iter().all(|&y| y < write_y),
                "{}: {:?} is drawn on or below `{}` (y={}): {:?}", name, end, write, write_y, ends);
        }
    }
}

/// #778: with the read in the `else` arm, each end is drawn on the arm and
/// row where it is true. On the path through the `then` arm `c` is
/// overwritten, so `x`'s borrow ends at `c = &y;` there; on the `else`
/// path `c` is read at the `println!`, so it ends there, on the `else`
/// sub-column, and `c`'s `then` column doesn't end a borrow again on that
/// row (the old head drew `x`'s only end on the `then` sub-column at the
/// `println!` row, and a second "c's immutable borrow ends" there).
#[test]
fn old_lender_ends_on_each_arm_where_it_is_borrowed_no_longer() {
    let rv = run_with_local_backend("borrow_end_join_else");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let write_y = code_row_y(&code, "c = &y;");
    let read_y = code_row_y(&code, "println!(\"{}\", c);");
    let mut ends = dots_listing_tooltip(&timeline, "x's value is no longer immutably borrowed");
    ends.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    assert_eq!(ends.len(), 2, "x's borrow should end once per arm: {:?}", ends);
    let (then_end, else_end) = (ends[0], ends[1]);
    assert!((then_end.1 - write_y).abs() < 10.0,
        "x's borrow on the `then` arm ends at `c = &y;` (y={}), not at {:?}", write_y, then_end);
    assert!((else_end.1 - read_y).abs() < 10.0,
        "x's borrow on the `else` arm ends at the `println!` (y={}), not at {:?}", read_y, else_end);
    // `c`'s `then` column (left of c's own column, whose dot is the
    // first "c immutably borrows a value") doesn't end a borrow on the
    // `println!` row.
    let c_col = dots_listing_tooltip(&timeline, "c immutably borrows a value")[0].0;
    let c_ends = dots_where(&timeline, |l| l.iter().any(|t| t == "c's immutable borrow ends"));
    assert!(c_ends.iter().all(|d| (d.1 - read_y).abs() >= 10.0 || d.0 >= c_col),
        "a second \"c's immutable borrow ends\" on the `println!` row of the `then` arm: {:?}", c_ends);
}

/// #803: `c = &y;` ends c's loan of `x` and its unused new loan of `y` on
/// one dot, with the new borrow's own line between them. The dot listed
/// "c's immutable borrow ends" twice (the same sentence for two different
/// loans, which reads as a glitch); each end now names its lender, in
/// order: the old loan's end, the new borrow, the new loan's end. The
/// `else` arm's lone end keeps the plain wording.
#[test]
fn a_dot_ending_two_loans_names_each_lender() {
    for (name, kind, new_borrow, lenders) in [
        ("borrow_end_join_else", "immutable", "c immutably borrows a value", ("x", "y")),
        ("borrow_end_two_loans_mut", "mutable", "c mutably borrows a value", ("a", "b")),
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        let plain = format!("c's {} borrow ends", kind);
        let dots = tooltip_lines(&timeline);
        let twice: Vec<_> = dots.iter().filter(|l| l.iter().filter(|t| **t == plain).count() > 1).collect();
        assert!(twice.is_empty(), "{}: a dot says {:?} twice: {:?}", name, plain, twice);
        let want = vec![
            format!("c's {} borrow of {} ends", kind, lenders.0),
            new_borrow.to_string(),
            format!("c's {} borrow of {} ends", kind, lenders.1),
        ];
        assert!(dots.iter().any(|l| *l == want), "{}: no dot lists {:?}; dots: {:?}", name, want, dots);
        assert!(dots.iter().any(|l| l.contains(&plain)), "{}: the other arm's lone end lost its plain wording", name);
    }
}

/// #801: `c = &x` before an `if` that reads `c` in the `if` arm and
/// re-points it in the `else` arm. `x` stays borrowed in the `if` arm
/// until `c`'s last use there (the `println!`), and in the `else` arm
/// until `c` is overwritten (`c = &y;`). The old head drew the `else`
/// arm's end at the `println!` row (a line of the other arm) and gave the
/// `if` arm no end, so `x`'s column was drawn twice over those rows
/// (`corpus_expected_ok_produce_well_formed_svg` flags that too).
#[test]
fn old_lender_ends_in_each_arm_when_read_in_if_and_repointed_in_else() {
    let rv = run_with_local_backend("borrow_read_in_arm_repoint_else");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let read_y = code_row_y(&code, "println!(\"{}\", c);");
    let write_y = code_row_y(&code, "c = &y;");
    let mut ends = dots_listing_tooltip(&timeline, "x's value is no longer immutably borrowed");
    ends.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    assert_eq!(ends.len(), 2, "x's borrow should end once per arm: {:?}", ends);
    assert!((ends[0].1 - read_y).abs() < 10.0,
        "x's borrow in the `if` arm ends at c's last use there, the `println!` (y={}), not at {:?}", read_y, ends[0]);
    assert!((ends[1].1 - write_y).abs() < 10.0,
        "x's borrow in the `else` arm ends at `c = &y;` (y={}), not at {:?}", write_y, ends[1]);
}

/// #771: `r = if *r > 0 { &b } else { &c };` reads `*r` first, so the
/// dot lists "*r's value is copied" before the end of r's old borrow and
/// the new borrow. #751: in a swap `(r1, r2) = (r2, r1);` both
/// references' ends are on the swap's row (r2's end used to sit alone on
/// a row below it, although r2 holds `&x` after the swap).
#[test]
fn reads_of_the_old_reference_come_before_its_end_and_the_swap_ends_on_its_row() {
    let timeline = run_with_local_backend("ref_reassign_reads_rhs_first").timeline_panel_string();
    let at = |l: &[String], t: &str| l.iter().position(|x| x == t);
    let (read, end, start) = ("*r's value is copied", "r's immutable borrow ends", "r immutably borrows a value");
    let ordered = dots_where(&timeline, |l| matches!((at(l, read), at(l, end)), (Some(a), Some(b)) if a < b));
    let listed = dots_where(&timeline, |l| at(l, read).is_some());
    assert!(!ordered.is_empty() && ordered == listed,
        "want one dot listing {:?}, {:?} in that order (got {:?}, dots listing the read: {:?})", read, end, ordered, listed);
    // The new borrow is made in each branch (`r = if *r > 0 { &b } else
    // { &c };`, #1393), after that dot.
    let starts: Vec<(f64, f64)> = dots_listing_tooltip(&timeline, start).into_iter().filter(|d| d.1 > ordered[0].1).collect();
    assert!(starts.len() == 2,
        "want {:?} in each branch, after the read and the end at {:?} (got {:?})", start, ordered[0], starts);

    let rv = run_with_local_backend("ref_swap_keeps_borrow");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let swap_y = code_row_y(&code, "(r1, r2) = (r2, r1);");
    let println_y = code_row_y(&code, "println!(\"{} {}\", r1, r2);");
    for (r, other) in [("r1", "r2"), ("r2", "r1")] {
        let end = format!("{}'s immutable borrow ends", r);
        let assigned = format!("{} is assigned a copy of {}'s reference", r, other);
        let both = dots_where(&timeline, |l| l.contains(&end) && l.contains(&assigned));
        assert!(both.iter().any(|d| d.1 == swap_y), "{}: no dot on the swap row (y={}) lists {:?} and {:?}: {:?}", r, swap_y, end, assigned, both);
        let ends: Vec<f64> = dots_listing_tooltip(&timeline, &end).into_iter().map(|d| d.1).collect();
        assert!(!ends.iter().any(|&y| swap_y < y && y < println_y), "{}: {:?} is drawn below the swap, above its next use: {:?}", r, end, ends);
    }
}

/// #693: the borrow a scrutinee's call makes (`x.as_mut()`) is held by the
/// pattern's binding, and ends at its last use, in its arm. In an arm whose
/// pattern binds nothing of it (the `else`, `None =>`), nothing held it: it
/// ends as that arm starts, between the binding arm's last use and the
/// other arm's code. Without that end the variable reached the join still
/// borrowed, and its scope end said it dropped nothing.
#[test]
fn scrutinee_call_borrow_ends_in_an_arm_that_binds_nothing() {
    for (name, lender, m, used, other) in [
        ("iflet_call_borrow_else", "x", "mutabl", "a.push('!');", "println!(\"no x\");"),
        ("iflet_call_borrow_else", "v", "mutabl", "b.push('!');", "println!(\"no v\");"),
        ("iflet_call_borrow_else", "w", "mutabl", "c.push('!');", "println!(\"no w\");"),
        ("match_call_borrow_arms", "x", "mutabl", "Some(a) => a.push('!'),", "None => println!(\"no x\"),"),
        ("match_call_borrow_arms", "v", "mutabl", "Some(b) => b.push('!'),", "None => println!(\"no v\"),"),
        ("match_call_borrow_arms", "w", "mutabl", "Some(c) => c.push('!'),", "None => println!(\"no w\"),"),
        ("match_call_borrow_arms", "t", "immutabl", "Some(d) => println!(\"{d}\"),", "None => println!(\"no t\"),"),
    ] {
        let rv = run_with_local_backend(name);
        let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let (used_y, other_y) = (code_row_y(&code, used), code_row_y(&code, other));
        let back = format!("{}'s resource is no longer {}y borrowed", lender, m);
        let ys: Vec<f64> = dots_listing_tooltip(&tl, &back).into_iter().map(|d| d.1).collect();
        assert!(ys.iter().any(|&y| y == used_y),
            "{}: {}'s borrow doesn't end at the binding's last use (y={}): {:?}", name, lender, used_y, ys);
        assert!(ys.iter().any(|&y| y > used_y && y <= other_y),
            "{}: {}'s borrow doesn't end in the arm that binds nothing (by y={}): {:?}", name, lender, other_y, ys);
    }
}

/// The `(temporary)` columns whose drop dot says the temporary is
/// dropped before an `if let`'s `else` block runs (#469, #604): each
/// column's `data-hash` and the drop dot's y.
fn else_path_temporary_drops(timeline: &str) -> Vec<(String, f64)> {
    let mut out = Vec::new();
    for tag in start_tags(timeline, "g") {
        let Some(hash) = attr(tag, "data-hash") else { continue };
        let lines = timeline_tooltips(&format!("{}>", tag));
        if !lines.iter().any(|l| l.starts_with("This temporary") && l.contains("before the `else` block")) {
            continue;
        }
        let at = timeline.find(tag).unwrap() + tag.len();
        let body = &timeline[at..at + timeline[at..].find("</g>").unwrap()];
        let Some(cy) = start_tags(body, "circle").first().and_then(|c| attr(c, "cy")?.parse::<f64>().ok()) else { continue };
        out.push((hash.to_owned(), cy));
    }
    out
}

/// The lowest y that an element of the column `hash` (segment line,
/// hover polygon or dot) reaches.
fn column_bottom(timeline: &str, hash: &str) -> f64 {
    let mut bottom = f64::MIN;
    for kind in ["line", "polygon", "circle"] {
        for tag in start_tags(timeline, kind) {
            if attr(tag, "data-hash") != Some(hash) {
                continue;
            }
            let ys: Vec<f64> = match kind {
                "line" => ["y1", "y2"].iter().filter_map(|k| attr(tag, k)?.parse().ok()).collect(),
                "circle" => attr(tag, "cy").and_then(|v| v.parse().ok()).into_iter().collect(),
                _ => attr(tag, "points").unwrap_or("").split_whitespace()
                    .filter_map(|p| p.split(',').nth(1)?.parse().ok()).collect(),
            };
            for y in ys {
                bottom = bottom.max(y);
            }
        }
    }
    bottom
}

/// #571 follow-up: an `if let`'s scrutinee temporary is dropped before
/// the `else` block runs (edition 2024), so it isn't alive in the else
/// branch. Its column used to run on from that drop into the else
/// branch and down to a join dot ("(temporary) isn't moved in any of
/// the branches above"), its segments saying "(temporary) is the owner
/// of the resource" there. Now nothing of the column is drawn below the
/// drop, and it gets no join. (A conditional nested in the matched block
/// that exits joins above that drop: the temporary forks there, #1360.)
#[test]
fn if_let_scrutinee_temporary_ends_at_its_else_drop() {
    for name in ["if_let_scrutinee_move", "temporary_drop_early_exit"] {
        let rv = run_with_local_backend(name);
        let timeline = rv.timeline_panel_string();
        let drops = else_path_temporary_drops(&timeline);
        assert!(!drops.is_empty(), "{}: no drop dot before an `else` block", name);
        for (hash, y) in drops {
            let bottom = column_bottom(&timeline, &hash);
            assert!(bottom <= y + 6.0,
                "{}: the temporary column {} runs to y={}, below its drop before the `else` block at y={}",
                name, hash, bottom, y);
            let joins: Vec<String> = start_tags(&timeline, "circle").into_iter()
                .filter(|t| attr(t, "data-hash") == Some(hash.as_str()))
                .filter(|t| attr(t, "cy").and_then(|v| v.parse::<f64>().ok()).is_some_and(|cy| cy >= y))
                .flat_map(|t| timeline_tooltips(&format!("{}>", t)))
                .filter(|t| t.contains("branches above"))
                .collect();
            assert!(joins.is_empty(), "{}: the temporary column {} has a join dot: {:?}", name, hash, joins);
        }
    }
}

/// Same-named variables in separate scopes that are different kinds of
/// value (here a reference and a `String`) get a column each (#598), both
/// labelled with the plain name: the later one shadows nothing, so it
/// has no subscript (#308). Told apart by their hash. Same-kind ones
/// (an `i32` and a `u8`) still share one.
#[test]
fn same_name_kinds_get_separate_columns() {
    for (name, label, columns) in [
        ("ref_binding_name_reused", "x", 2),
        ("ref_binding_name_reused_mut", "x", 2),
        ("let_ref_then_owner_same_name", "x", 2),
        ("for_over_iterator_var", "s", 2),
        ("same_name_copy_kinds_share", "x", 1),
        ("same_name_drop_kinds_split", "x", 2),
        ("same_name_plain_owners_share", "x", 1),
        ("match_macro_arm_name_reused", "x", 1),
    ] {
        let t = run_with_local_backend(name).timeline_panel_string();
        let mut hashes: Vec<&str> = t.split("<text ").skip(1)
            .filter_map(|x| x.split_once('>'))
            .filter(|(tag, rest)| tag.contains("class=\"label") && rest.split('<').next() == Some(label))
            .map(|(tag, _)| attr(tag, "data-hash").expect("a label has a data-hash"))
            .collect();
        hashes.sort();
        hashes.dedup();
        assert_eq!(hashes.len(), columns, "{}: columns labelled {:?}: {:?}", name, label, hashes);
        let labels = header_labels(&t);
        assert!(!labels.iter().any(|l| l.2.starts_with(label) && l.2[label.len()..].starts_with(|c: char| "₀₁₂₃₄₅₆₇₈₉".contains(c))),
            "{}: a subscripted {:?} column: {:?}", name, label, labels);
    }
}

/// #431: a `break` in a branch (`if n == 3 { break s; }`) carries its
/// value out of the loop. As for any move out of a loop (#350), the move
/// is drawn where the loop ends (`rows` rows below the `break`), so
/// inside the loop the value is still owned after the `if`. This holds whatever receives the value: a `let`, an assignment
/// or a call argument.
///
/// This test fails on the plugin before the fix (no move at all on main;
/// the move on the `break` row for `r = loop` and `take(loop …)` on the
/// first rework).
#[test]
fn a_break_value_in_a_branch_moves_where_the_loop_ends() {
    for (name, brk, moved, rows) in [
        ("loop_break_value_outer_var", "break s;", "s's resource is moved", 2.0),
        ("loop_break_value_in_branch", "break b;", "b's resource is moved", 4.0),
        ("loop_break_value_cond_receivers", "break s;", "s's resource is moved", 2.0),
        ("loop_break_value_cond_receivers", "break z;", "z's resource is moved", 2.0),
    ] {
        let rv = run_with_local_backend(name);
        let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let row = code_row_y(&code, brk);
        let want = row + rows * 30.0;
        let dots = dots_listing_tooltip(&tl, moved);
        assert!(
            dots.len() == 1 && dots[0].1 == want,
            "{}: `{}` is at y={}; the move out of the loop should be at y={} (where the loop ends), found {:?}",
            name, brk, row, want, dots
        );
    }
}

/// #731: in `let k = { let t = m * 2; t };` the block's `let` and the copy
/// of its tail into `k` share a line. `t` is bound first, then copied
/// into `k`, then goes out of scope. Before, the copy was drawn on the
/// line's row and `t`'s binding and scope end on a row below it: `t` was
/// copied before it had a value.
///
/// Since `*` is no longer an actor (#908), that line draws one arrow, so
/// its dots share one row: `t`'s scope end is listed after the copy in
/// the same dot, as for `let j = { let u = 2; u };`. The next line,
/// `let (k2, q) = ({ let u = m * 2; u }, m);`, draws two arrows, which are
/// stacked: `u`'s scope end goes on a row below its binding.
#[test]
fn a_block_tail_is_bound_before_it_is_copied() {
    let rv = run_with_local_backend("block_tail_copy_order");
    let timeline = rv.timeline_panel_string();
    let tips = tooltip_lines(&timeline);
    for (v, stacked) in [("t", false), ("u", true)] {
        let bound = format!("{} is bound to a copyable value", v);
        let copied = format!("{}'s value is copied", v);
        let gone = format!("{} goes out of scope", v);
        let dots: Vec<&Vec<String>> = tips.iter().filter(|t| t.iter().any(|l| *l == copied)).collect();
        assert_eq!(dots.len(), 1, "dots copying {} out: {:?}", v, dots);
        let want = [bound.clone(), copied.clone()];
        assert!(
            dots[0].starts_with(&want),
            "the dot where {} is copied reads {:?}; {} must be bound before it is copied",
            v, dots[0], v
        );
        let bound_at = dots_listing(&timeline, &bound);
        let copied_at = dots_listing(&timeline, &copied);
        let gone_at = dots_listing(&timeline, &gone);
        assert_eq!(bound_at.len(), 1, "{}'s binding dots: {:?}", v, bound_at);
        assert_eq!(bound_at, copied_at, "{} is bound and copied at the same row", v);
        assert_eq!(gone_at.len(), 1, "{}'s scope-end dots: {:?}", v, gone_at);
        if stacked {
            assert!(gone_at[0].1 > bound_at[0].1, "{}'s scope end {:?} must be below its binding {:?}", v, gone_at, bound_at);
        } else {
            assert_eq!(gone_at, bound_at, "{}'s scope end shares the row of its binding", v);
            assert!(
                dots[0].ends_with(&[copied.clone(), gone.clone()]),
                "the dot where {} is copied reads {:?}; {} must go out of scope after it is copied",
                v, dots[0], v
            );
        }
    }
}

/// The row numbers (1-based) of the code panel's lines whose row lies in
/// the `data-underline-y` range `ys`, as the hover script matches them.
fn rows_in_underline_range(code_svg: &str, ys: (f64, f64)) -> Vec<usize> {
    code_svg
        .split("<text class=\"code\"")
        .skip(1)
        .filter_map(|chunk| attr(&chunk[..chunk.find('>').unwrap_or(chunk.len())], "y"))
        .filter_map(|y| y.parse::<f64>().ok())
        .enumerate()
        .filter(|(_, y)| y - 5.0 >= ys.0 - 2.0 && y - 5.0 <= ys.1 + 2.0)
        .map(|(i, _)| i + 1)
        .collect()
}

/// #626: hovering an arm's column underlines separate code. The dashed
/// stretch underlines the other arms' lines it runs beside (which this
/// path skips); the solid stretch underlines the arm's own lines, and
/// neither underlines the other's. Pinned on `dashed_arm_hover`: the
/// `else` arm of `if c` (lines 12-14; the `if` arm is lines 10-11) and
/// the `_` arm of `match n` (lines 23-26; the `0` arm is lines 19-22).
#[test]
fn dashed_and_solid_arm_stretches_underline_separate_lines() {
    let rv = run_with_local_backend("dashed_arm_hover");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let mut seen: Vec<((usize, usize), Vec<usize>, Vec<usize>)> = Vec::new();
    let mut implicit_else: Vec<Vec<usize>> = Vec::new();
    for group in timeline.split("<g class=\"branch-group\"").skip(1) {
        let group = &group[..group.find("</g>").unwrap_or(group.len())];
        let head = &group[..group.find('>').unwrap_or(group.len())];
        let rows: Vec<usize> = attr(head, "data-arm-rows")
            .map(|r| r.split(' ').filter_map(|n| n.parse().ok()).collect())
            .unwrap_or_default();
        let [first, last] = rows[..] else {
            // The implicit `else` of `if let Some(x) = opt { .. }`: its
            // dashed column underlines the `if` arm's line 30, not the
            // `if let` line it forks from.
            let mut skipped = Vec::new();
            for seg in group.split("<polygon ").skip(1) {
                let tag = &seg[..seg.find('>').unwrap_or(seg.len())];
                let Some(r) = attr(tag, "data-underline-y") else { continue };
                let ys: Vec<f64> = r.split(' ').filter_map(|v| v.parse().ok()).collect();
                skipped.extend(rows_in_underline_range(&code, (ys[0], ys[1])));
            }
            implicit_else.push(skipped);
            continue;
        };
        let (mut on_own, mut off_own) = (Vec::new(), Vec::new());
        for seg in group.split("<polygon ").skip(1) {
            let tag = &seg[..seg.find('>').unwrap_or(seg.len())];
            let Some(r) = attr(tag, "data-underline-y") else { continue };
            let ys: Vec<f64> = r.split(' ').filter_map(|v| v.parse().ok()).collect();
            for row in rows_in_underline_range(&code, (ys[0], ys[1])) {
                let own = first <= row && row <= last;
                let v = if own { &mut on_own } else { &mut off_own };
                if !v.contains(&row) { v.push(row); }
            }
        }
        // An arm's dashed and solid stretches are separate hover groups
        // with the same `data-arm-rows`; merge them per arm.
        match seen.iter_mut().find(|s| s.0 == (first, last)) {
            Some(entry) => {
                for r in on_own { if !entry.1.contains(&r) { entry.1.push(r); } }
                for r in off_own { if !entry.2.contains(&r) { entry.2.push(r); } }
            }
            None => seen.push(((first, last), on_own, off_own)),
        }
    }
    let find = |arm: (usize, usize)| seen.iter().find(|s| s.0 == arm)
        .unwrap_or_else(|| panic!("no arm on rows {:?} in {:?}", arm, seen));
    // `else` of `if c`: own lines 12-14, skipped lines are the `if` arm's.
    assert_eq!(find((12, 14)).1, vec![12, 13, 14], "else arm's solid stretch: {:?}", seen);
    assert_eq!(find((12, 14)).2, vec![10, 11], "else arm's dashed stretch: {:?}", seen);
    // `_` arm of the match: own lines 23-26, skipped lines are the `0` arm's.
    assert_eq!(find((23, 26)).1, vec![23, 24, 25, 26], "_ arm's solid stretch: {:?}", seen);
    assert_eq!(find((23, 26)).2, vec![19, 20, 21, 22], "_ arm's dashed stretch: {:?}", seen);
    assert!(implicit_else.contains(&vec![30]), "implicit else's dashed stretch: {:?}", implicit_else);
}

/// #843: a hover that underlines nothing (`data-underline="none"`: the
/// diagonals into and out of an arm, a dashed stretch with no other arm's
/// code beside it) must not say "the underlined code is not part of that
/// branch". The diagonals say where they lead; the arm's own and the
/// dashed stretches keep their texts.
#[test]
fn arm_hovers_that_underline_nothing_do_not_mention_underlined_code() {
    for name in ["arm_no_events_own_rows_843", "else_no_events_own_rows_843", "dashed_arm_hover"] {
        let rv = run_with_local_backend(name);
        let timeline = rv.timeline_panel_string();
        let mut leads = 0;
        for tag in timeline.split('<').skip(1) {
            let tag = &tag[..tag.find('>').unwrap_or(tag.len())];
            if attr(tag, "data-underline") != Some("none") { continue; }
            let Some(text) = attr(tag, "data-tooltip-text") else { continue };
            assert!(
                !text.contains("underlined code"),
                "{name}: a hover that underlines nothing mentions underlined code: <{tag}"
            );
            leads += (text.contains("leads into the") || text.contains("to where the branches join")) as usize;
        }
        assert!(leads > 0, "{name}: no diagonal says where it leads");
    }
}

/// #845: a match arm of one row with no events for the variable is solid
/// over its own row (half a row either side, clipped at the split), and
/// hovering that stretch underlines exactly that line. The rest of its
/// column stays dashed beside the other arms' rows, and the join diagonal
/// starts below the solid stretch.
#[test]
fn one_row_arm_without_events_is_solid_over_its_own_row() {
    // (fixture, first/last row of the arms that must have a solid stretch)
    for (name, rows) in [
        ("match_one_row_arms_845", vec![8usize, 9, 10]),
        ("arm_no_events_own_rows_843", vec![9]),
        // #1373: an arm with an event on its row (`1 => show(&s),`) too,
        // above and below its dot; one that moves s (`1 => consume(s),`)
        // above it. main drew them dashed straight through their dots.
        ("one_row_arm_event_solid_1373", vec![13, 14, 22, 23, 24, 25, 34, 35]),
        ("match_three_arms", vec![11, 12]),
    ] {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let mut solid_rows: Vec<usize> = Vec::new();
        for group in timeline.split("<g class=\"branch-group\"").skip(1) {
            let group = &group[..group.find("</g>").unwrap_or(group.len())];
            let head = &group[..group.find('>').unwrap_or(group.len())];
            let arm: Vec<usize> = attr(head, "data-arm-rows")
                .map(|r| r.split(' ').filter_map(|n| n.parse().ok()).collect())
                .unwrap_or_default();
            let [first, last] = arm[..] else { continue };
            if first != last { continue; }
            // A solid (not dashed) vertical line with a hover polygon that
            // underlines the arm's own row.
            let solid = group.contains("stroke-dasharray: none")
                && group.split("<polygon ").skip(1).any(|poly| {
                    let tag = &poly[..poly.find('>').unwrap_or(poly.len())];
                    let Some(r) = attr(tag, "data-underline-y") else { return false };
                    let ys: Vec<f64> = r.split(' ').filter_map(|v| v.parse().ok()).collect();
                    let text = attr(tag, "data-tooltip-text").unwrap_or_default();
                    rows_in_underline_range(&code, (ys[0], ys[1])) == vec![first]
                        && text.contains("is the owner of the resource")
                        && !text.contains("not part of that branch")
                });
            if solid { solid_rows.push(first); }
        }
        for row in rows {
            assert!(solid_rows.contains(&row), "{name}: the one-row arm at line {row} has no solid stretch underlining it (solid: {solid_rows:?})");
        }
    }
}

/// #626: the hover glow covers one stretch at a time. A `branch-group`
/// is what `.branch-group:hover .tooltip-trigger` glows, so no group may
/// hold both a dashed segment ("The underlined code is not part of that branch") and a
/// solid one ("is the owner of the resource"); before, an arm's dashed
/// and solid stretches glowed together as one piece.
#[test]
fn dashed_and_solid_arm_stretches_glow_separately() {
    let rv = run_with_local_backend("dashed_arm_hover");
    let timeline = rv.timeline_panel_string();
    let (mut dashed_groups, mut solid_groups) = (0, 0);
    for group in timeline.split("<g class=\"branch-group\"").skip(1) {
        let group = &group[..group.find("</g>").unwrap_or(group.len())];
        let dashed = group.contains("The underlined code is not part of that branch");
        let solid = group.contains("is the owner of the resource");
        assert!(
            !(dashed && solid),
            "a dashed and a solid stretch share one hover group:\n{group}"
        );
        dashed_groups += dashed as usize;
        solid_groups += solid as usize;
    }
    assert!(dashed_groups >= 3, "expected dashed stretches for else, _ and the implicit else");
    assert!(solid_groups >= 3, "expected solid stretches too");
}

/// #710: in a one-line match arm, a pattern binding's borrow (`v` to `x`)
/// and its return (`x` to `v`) were drawn on the same row, one shaft under
/// the other, so only one could be hovered. The return dips half a row
/// below the borrow instead (no row is added to the code panel).
#[test]
fn one_line_arm_borrow_and_return_arrows_are_separate() {
    let rv = run_with_local_backend("arm_one_line_borrow_return_710");
    let tl = rv.timeline_panel_string();
    let code = rv.code_panel_string();
    let borrow = arrow_points(&tl, "Immutable borrow from v to x: x is a reference copied out of the value get returned");
    let ret = arrow_points(&tl, "Return immutably borrowed resource from x to v");
    assert_eq!((borrow.len(), ret.len()), (1, 1), "{:?} {:?}", borrow, ret);
    let row = code_row_y(&code, "Some(x) => println!(\"{}\", x),");
    let ys = |p: &Vec<(f64, f64)>| p.iter().map(|&(_, y)| y).collect::<Vec<_>>();
    let (bmin, bmax) = ys(&borrow[0]).into_iter().fold((f64::MAX, f64::MIN), |(a, b), y| (a.min(y), b.max(y)));
    assert!((bmin - row).abs() < 1.0 && (bmax - row).abs() < 1.0, "the borrow isn't level on its row: {:?}", borrow);
    // The return leaves the borrow's row: some of its shaft is below it,
    // by half a row at most.
    let lowest = ys(&ret[0]).into_iter().fold(f64::MIN, f64::max);
    assert!(lowest > row + 5.0, "the return shares the borrow's row: {:?}", ret);
    assert!(lowest <= row + 15.0 + 0.5, "the return dips more than half a row: {:?}", ret);
    assert_eq!(unnumbered_code_rows(&code), 0, "a blank row was added for the dip");
}

/// #712: `o`'s borrow end (a holder moved out of by `if let`) used to be
/// listed in the arm right after the move, ahead of line 5, so line 5's
/// events were drawn on line 6's row and `x`'s borrow ended on `push`'s
/// call dot. `x.push('a')` stays on its own row, `println!` on the next.
#[test]
fn early_holder_borrow_end_keeps_arm_rows() {
    let rv = run_with_local_backend("if_let_holder_end_row_712");
    let tl = rv.timeline_panel_string();
    let code = rv.code_panel_string();
    let push = code_row_y(&code, "x.push('a');");
    let print = code_row_y(&code, "println!(\"{}\", x);");
    let at = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    assert_eq!(at("the resource x points to is mutably borrowed by push through x; x can't be used while the borrow is live"), vec![push]);
    assert_eq!(at("the resource x points to is immutably borrowed by println! through x"), vec![print]);
    // x's borrow ends on its last use, the println!, not on push's row.
    assert_eq!(at("x's mutable borrow ends"), vec![print]);
}

/// A borrow a call leaves in a variable lasts until that variable's last
/// use, where rustc ends the loan (#686, #682): the closure `keep` hands
/// back holds its capture's borrow, and `extend` stores `&s` in `refs`.
/// The lender is lent on the call's row and gets the borrow back on the
/// holder's last use, not at the call.
#[test]
fn borrow_kept_after_call_ends_at_holders_last_use() {
    // (fixture, lend dot, the call's line, the lender's "no longer
    // borrowed" dot, the holder's last use)
    for (name, lent, lent_at, back, back_at) in [
        ("closure_kept_by_callee",
         "s's resource is immutably borrowed by g; s is read-only while the borrow is live",
         "let g = keep(|| s.len());",
         "s's resource is no longer immutably borrowed",
         "println!(\"{}\", g());"),
        ("closure_kept_by_callee",
         "t's resource is mutably borrowed by h; t can't be used while the borrow is live",
         "let mut h = keep_mut(|| t.push('!'));",
         "t's resource is no longer mutably borrowed",
         "h();"),
        ("extend_stores_borrow",
         "s's resource is immutably borrowed by refs; s is read-only while the borrow is live",
         "refs.extend([&s]);",
         "s's resource is no longer immutably borrowed",
         "println!(\"{}\", refs.len());"),
    ] {
        let rv = run_with_local_backend(name);
        let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|d| d.1).collect() };
        let (call, last) = (code_row_y(&code, lent_at), code_row_y(&code, back_at));
        assert_eq!(ys(lent), vec![call], "{}: {:?} isn't on the row of {:?}", name, lent, lent_at);
        // The first time the lender gets a borrow back after the call
        // (a later `println!` of it lends and returns again).
        let first_back = ys(back).into_iter().filter(|&y| y > call).reduce(f64::min);
        assert_eq!(first_back, Some(last), "{}: {:?} isn't on the row of {:?}", name, back, back_at);
    }
}

/// Dots in a timeline panel that no column line reaches: no `<line>`
/// ends within a few pixels of the dot's centre or runs through it.
/// A scope-end dot after a move legitimately stands alone, as does a
/// drop stated on an arm whose column has no line there (a temporary
/// tuple's, #399), so `skip` filters those out by their tooltip.
fn unconnected_dots(svg: &str, skip: impl Fn(&str) -> bool) -> Vec<String> {
    let lines = svg_lines(svg);
    let touches = |cx: f64, cy: f64| {
        lines.iter().any(|&(x1, y1, x2, y2)| {
            let end = |x: f64, y: f64| (x - cx).abs() <= 6.0 && (y - cy).abs() <= 6.0;
            let through = (x1 - x2).abs() < 0.01
                && (x1 - cx).abs() <= 3.0
                && y1.min(y2) - 1.0 <= cy
                && cy <= y1.max(y2) + 1.0;
            end(x1, y1) || end(x2, y2) || through
        })
    };
    let mut out = Vec::new();
    for tips in tooltip_lines(svg) {
        if tips.iter().any(|t| skip(t)) {
            continue;
        }
        for (x, y) in dots_where(svg, |l| l == tips.as_slice()) {
            if !touches(x, y) {
                out.push(format!("({}, {}) {:?}", x, y, tips));
            }
        }
    }
    out.sort();
    out.dedup();
    out
}

/// #694: when every branch of a conditional moved or dropped a
/// variable, a join dot ("s was moved or dropped in every branch
/// above") was drawn on its column at the end of the conditional,
/// with no arm's line running into it: it floated between the arms
/// (beside them when they end on that row, as the temporary tuple's
/// drops do). The column now ends with the arms, like a column after
/// a plain move, and the scope-end dot says why nothing is dropped.
#[test]
fn no_join_dot_floats_after_every_branch_moves() {
    let skip = |t: &str| t.contains("goes out of scope") || t.contains(" is dropped");
    // Every snippet main drew such a dot in. tuple_scrutinee_exit_drops
    // also had the split of an `if` nested in an arm on x's column after
    // x was moved into the tuple: x isn't live there and no line leaves
    // that split either.
    for name in [
        "if_else_move_both",
        "cond_with_move_closure",
        "if_no_else_nested_move",
        "reassign_after_maybe_move_match",
        "partial_move_if_branches",
        "basic_match2",
        "diverging_branch_stops",
        "exit_path_dependent_drops",
        "match_diverging_arm",
        "else_if_chain_diverges",
        "iflet_tuple_pattern",
        "match_tuple_literal_moves",
        "tuple_scrutinee_ref",
        "tuple_scrutinee_drops",
        "tuple_scrutinee_exit_drops",
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        assert_eq!(unconnected_dots(&timeline, skip), Vec::<String>::new(), "{}: dots no line reaches", name);
    }
}

/// #585: `r` borrows what the reference a `break` carries borrowed, and
/// (borrow-checker view) the lender stays borrowed until `r`'s last use,
/// the `println!` below the loop. The old plugin never gave the borrow
/// back (no such dot at all).
#[test]
fn a_reference_out_of_a_loop_is_returned_at_the_receivers_last_use() {
    let rv = run_with_local_backend("loop_break_ref_lender");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (lender, last_use) in [
        ("a", "println!(\"{}\", r);"),
        ("c", "println!(\"in branch: {}\", r);"),
        ("d", "println!(\"in loop: {}\", r);"),
    ] {
        let want = code_row_y(&code, last_use);
        let dots = dots_listing_tooltip(&tl, &format!("{}'s resource is no longer mutably borrowed", lender));
        assert!(
            dots.len() == 1 && dots[0].1 == want,
            "{}'s borrow should end at y={} (`{}`), found {:?}",
            lender, want, last_use, dots
        );
    }
}

/// #586: in `r = loop { … }` the loop runs first; the old value is
/// dropped when the loop's value is assigned, with the new value's
/// arrival (`rows` below `r = loop {`): where the loop ends for a
/// `break` in a branch, on the `break a;` row for `s`'s unconditional
/// `break`. The old plugin drew the drop on the `r = loop {` row.
#[test]
fn reassign_from_a_loop_drops_where_the_loop_ends() {
    let rv = run_with_local_backend("loop_break_reassign_drop");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (assign, drop, rows) in [
        ("r = loop {", "r acquires ownership of a new resource; its previous resource is dropped", 3.0),
        ("s = loop {", "s acquires ownership of a new resource; its previous resource is dropped", 4.0),
        ("t = loop {", "t acquires ownership of a new resource (from whichever break ended the loop); its previous resource is dropped", 2.0),
    ] {
        let want = code_row_y(&code, assign) + rows * 30.0;
        let dots = dots_listing_tooltip(&tl, drop);
        assert!(
            dots.len() == 1 && dots[0].1 == want,
            "`{}`: the old value's drop should be at y={} (where the loop ends), found {:?}",
            assign, want, dots
        );
    }
}

/// #702: a dot sits on a line of its column. Where no line reaches a
/// split or a join, it isn't drawn, and its text goes on the column's
/// next dot (the scope end, or the next event). Three kinds floated:
/// - the join of an outer `if` whose first arm is a nested `if` that
///   moved s on one path: the arm that kept s ends at the inner join,
///   and no line runs from there to the outer one ("s was moved in at
///   least one branch above ...");
/// - the split of a lender while `r = &mut s` is live across the
///   conditional: its column draws no line there (only the dotted
///   lent-out line since #722, which no split dot goes on), and the arms
///   start from nothing ("s is live in a conditional expression");
/// - the join in a loop body after arms that `break` / `return`, where
///   the reference's borrow ended in every arm ("v's borrow ended in
///   each branch above", and an empty join dot on x's column).
#[test]
fn no_split_or_join_dot_floats_off_its_column() {
    // Scope-end dots stand alone after a move, and a temporary's drop
    // has a column of no lines.
    let skip = |t: &str| {
        t.split_once(" goes out of scope").is_some_and(|(who, _)| !who.contains(' '))
            || t.contains("temporary")
    };
    for name in [
        "reassign_after_nested_maybe_move",
        "nested_if_move_join",
        "deep_nested_if",
        "else_if_chain",
        "outer_mut_ref_end_in_if_arm",
        "reassign_through_ref_in_branch",
        "join_after_early_exit",
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        assert_eq!(unconnected_dots(&timeline, skip), Vec::<String>::new(), "{}: dots no line reaches", name);
    }
    // Each text that lost its dot is on the column's next one, before
    // that dot's own events, as many times as there are such dots.
    const MAYBE_MOVED: &str = "s was moved in at least one branch above, so it can't be used after the \
        branches. If the branch that ran didn't move it, its resource is \
        dropped when s goes out of scope.";
    const DROP_FLAG: &str = "s goes out of scope. Its resource is dropped here only if no branch above \
        moved it (Rust tracks this with a runtime drop flag).";
    for (name, moved, onto, n) in [
        (
            "reassign_after_nested_maybe_move",
            "s was moved in at least one branch above, so it can't be used after the branches until \
             it's assigned again. If the branch that ran didn't move it, its resource is dropped when \
             s is assigned again.",
            "s acquires ownership of a new resource. Its previous resource is dropped here only if \
             no branch above moved it (Rust tracks this with a runtime drop flag).",
            1,
        ),
        ("nested_if_move_join", MAYBE_MOVED, DROP_FLAG, 1),
        ("deep_nested_if", MAYBE_MOVED, DROP_FLAG, 1),
        ("else_if_chain", MAYBE_MOVED, DROP_FLAG, 1),
        // (outer_mut_ref_end_in_if_arm's and reassign_through_ref_in_branch's
        // "s / t is live in a conditional expression" were here, on each
        // arm's first dot: the dotted legs of a column mutably lent across
        // the conditional now start at a split dot of its own, #1371.)
        // (join_after_early_exit's `mixed` was here: v's borrow ended in
        // each arm of `match *x`. Its `_` arm goes round the loop again,
        // which keeps the loop's loan of v to the loop's end (#872), so
        // lines now reach that join.)
    ] {
        let timeline = run_with_local_backend(name).timeline_panel_string();
        let at = dots_where(&timeline, |lines| {
            let pos = |t: &str| lines.iter().position(|l| l == t);
            matches!((pos(moved), pos(onto)), (Some(a), Some(b)) if a < b)
        });
        assert_eq!(at.len(), n, "{}: {:?} is not on the dot of {:?} next on its column: {:?}",
            name, moved, onto, tooltip_lines(&timeline));
    }
}

/// #747: a `ref` binding of a by-value parameter (#691) borrows a
/// `(parameter)` column that the caller's value arrives in. The borrow
/// arrow used to sit on the signature's row, on top of the arrow bringing
/// the caller's value in, so the two read as one double-headed arrow; and
/// with two such parameters the second borrow, and the second return, each
/// took a row of their own (U-shaped arrows, rows 5-7 double height). The
/// borrows now run half a row below the signature's row, all at one level,
/// and the returns share their row: two `ref` parameters take the same
/// rows as two plain ones.
#[test]
fn two_ref_params_borrow_arrows_are_apart_and_share_rows() {
    let rv = run_with_local_backend("param_ref_value_column");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let sig = code_row_y(&code, "fn two(ref a: String, ref b: Vec<i32>) -> usize {");
    let body = code_row_y(&code, "a.len() + b.len()");
    assert_eq!(body - sig, 30.0, "the body is one row below the signature");
    for text in ["Immutable borrow from (parameter) to a", "Immutable borrow from (parameter 2) to b"] {
        let arrows = arrow_points(&timeline, text);
        assert_eq!(arrows.len(), 1, "{}", text);
        let level = arrows[0].iter().map(|p| p.1).fold(f64::MIN, f64::max);
        assert_eq!(level, sig + 15.0, "{}: runs half a row below the signature's row, clear of the caller's value arrow: {:?}", text, arrows[0]);
    }
}

/// #722(a): `let it = v.iter_mut(); for x in it { .. }` moves `it` into
/// the loop, which owns the iterator until it ends, so `v` is borrowed
/// through the whole body (`v.len()` in it is E0502) and rustc ends the
/// loan at the loop's end. (On main it was drawn at the last use of `x`,
/// inside the body.)
#[test]
fn a_holder_moved_into_a_for_loop_ends_its_loan_at_the_loop_end() {
    let rv = run_with_local_backend("for_holder_borrow_end_722");
    let (svg, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (text, line) in [
        ("v's resource is no longer mutably borrowed", "} // end of the for"),
        ("w's resource is no longer immutably borrowed", "} // end of the second for"),
    ] {
        // (`v.push(3)` after the loop ends its own borrow with the same
        // text: the loop's is the first.)
        let mut ends = dots_listing_tooltip(&svg, text);
        ends.sort_by(|a, b| a.1.total_cmp(&b.1));
        assert!(!ends.is_empty(), "{}: no such dot", text);
        assert_eq!(ends[0].1, code_row_y(&code, line), "{:?} should be on the row of `{}`: {:?}", text, line, ends);
    }
}

/// #767: `loop { if c { break; } else { let x = ra; break; } }` ends
/// `ra`'s borrow of `a` in each branch. The join, on the loop's `}` row
/// below, ended it a third time ("ra's immutable borrow ends", "a's
/// resource is no longer immutably borrowed"), reading as the borrow
/// ending twice. Each of the two branches ends it once; none after.
#[test]
fn a_borrow_every_branch_ended_is_not_ended_again_at_the_join() {
    let rv = run_with_local_backend("loop_break_borrow_scope_end");
    let (svg, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let branch_row = code_row_y(&code, "if c { break; } else { let x = ra; break; }");
    for text in ["a's resource is no longer immutably borrowed", "ra's immutable borrow ends"] {
        let ends = dots_listing_tooltip(&svg, text);
        // (`a.len()` above the loop ends its own implicit borrow too.)
        let after: Vec<_> = ends.iter().filter(|(_, y)| *y >= branch_row).collect();
        assert_eq!(after.len(), 2, "{:?}: one end per branch, none at the join: {:?}", text, ends);
        // The `else` arm is on a row of its own below the `if` arm's: the
        // two arms' `ra -> a` arrows would share a stretch of one row
        // (#1264).
        let mut ys: Vec<f64> = after.iter().map(|(_, y)| *y).collect();
        ys.sort_by(f64::total_cmp);
        assert_eq!(ys, vec![branch_row, branch_row + 30.0],
            "{:?} should only be on the branches' rows: {:?}", text, ends);
    }
}

/// #767: `for x in it` moves `it` into the loop. The loop gives `v` its
/// borrow back at its closing brace, but `it`'s column holds nothing
/// after the move, so it draws no "it's mutable borrow ends" there:
/// only its move and its scope end.
#[test]
fn a_holder_moved_into_a_for_loop_draws_no_borrow_end_on_its_column() {
    let rv = run_with_local_backend("for_holder_borrow_end_722");
    let (svg, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (holder, end) in [("it", "it's mutable borrow ends"), ("it2", "it2's immutable borrow ends")] {
        assert!(dots_listing_tooltip(&svg, end).is_empty(), "{}: no end on a moved-out column", end);
        let moved = dots_listing_tooltip(&svg, &format!("{}'s value is moved", holder));
        let scope = dots_listing_tooltip(&svg, &format!("{} goes out of scope", holder));
        assert_eq!((moved.len(), scope.len()), (1, 1), "{}: moved and scope-end dots", holder);
        // No dot on the holder's column between the move and its scope end.
        let between = dots_where(&svg, |_| true).into_iter()
            .filter(|(x, y)| *x == moved[0].0 && *y > moved[0].1 && *y < scope[0].1)
            .count();
        assert_eq!(between, 0, "{}: a dot on its column after it was moved into the loop", holder);
    }
    // The lenders' ends stay on the loops' closing braces (#722).
    let end = code_row_y(&code, "} // end of the for");
    assert!(dots_listing_tooltip(&svg, "v's resource is no longer mutably borrowed").iter().any(|(_, y)| *y == end));
}

/// #662: with a `loop` as a call argument, the call runs once the loop
/// has ended, on the loop's last line (`});`), where it is drawn. The
/// lenders stay borrowed until then: the old plugin gave each one back
/// on the `break` row, a row above the call that uses what it lent.
#[test]
fn loop_call_arg_borrows_end_at_the_call() {
    let rv = run_with_local_backend("loop_break_call_arg");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (lender, kind, brk, call) in [
        ("a", "mutably", "if c { break ra; } else { break rb; }", "take reads and writes through ra"),
        ("b", "mutably", "if c { break ra; } else { break rb; }", "take reads and writes through rb"),
        ("e", "immutably", "if c { break re; } else { break rf; }", "look reads from re"),
        ("f", "immutably", "if c { break re; } else { break rf; }", "look reads from rf"),
        ("g", "mutably", "if c { break rg; }", "take reads and writes through rg"),
    ] {
        let brk_row = code_row_y(&code, brk);
        // The last such dot: `e.len()` before the loop also lends `e`.
        let back = dots_listing_tooltip(&tl, &format!("{lender}'s resource is no longer {kind} borrowed"))
            .into_iter().map(|d| d.1).fold(f64::MIN, f64::max);
        let calls = dots_where(&tl, |lines| lines.iter().any(|l| l.starts_with(call)));
        assert!(
            calls.len() == 1 && back == calls[0].1 && back > brk_row,
            "{lender}'s borrow should end on the call's row (call dots {:?}), below `{brk}` (y={brk_row}), found y={}",
            calls, back
        );
    }
}

/// #662, the `break` row: in `take(loop { if c { break ra; } else { break rb;
/// } })` the `break ra` branch carries `ra`'s borrow of `a` to the call, so
/// `a` is still borrowed there; only the `break rb` branch, where `ra` is
/// dead, gives `a` back. Each lender gets its dot and its return arrow once
/// on the `break` row (in the branch that doesn't carry its reference), and
/// once on the call's row. The old plugin returned both lenders in both
/// branches.
#[test]
fn loop_break_row_returns_only_the_lenders_the_break_doesnt_carry() {
    let rv = run_with_local_backend("loop_break_call_arg");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (brk, kind, borrow, [(l1, r1), (l2, r2)]) in [
        ("if c { break ra; } else { break rb; }", "mutably", "mutable", [("a", "ra"), ("b", "rb")]),
        ("if c { break re; } else { break rf; }", "immutably", "immutable", [("e", "re"), ("f", "rf")]),
    ] {
        // The `break` arms' rows: the line's, and the `else` arm's own row
        // below it (the two arms' return arrows would share a stretch of
        // one row, #1264).
        let row = code_row_y(&code, brk);
        let on_row = |text: String| dots_listing_tooltip(&tl, &text).into_iter()
            .filter(|d| d.1 == row || d.1 == row + 30.0).map(|d| d.0).collect::<Vec<f64>>();
        let [lender1, lender2] = [l1, l2].map(|l| on_row(format!("{l}'s resource is no longer {kind} borrowed")));
        let [ref1, ref2] = [r1, r2].map(|r| on_row(format!("{r}'s {borrow} borrow ends")));
        // The first branch breaks with r1: it gives l2 back (r2 is dead
        // there) and keeps l1 lent. The second is the other way round.
        // That is one dot each for l1 and l2 (one per branch would be two).
        for (what, xs) in [("lender", [&lender1, &lender2]), ("reference", [&ref1, &ref2])] {
            assert!(xs[0].len() == 1 && xs[1].len() == 1,
                "{what} dots on the `{brk}` row: {} for {l1}/{r1}, {} for {l2}/{r2}; want one each",
                xs[0].len(), xs[1].len());
        }
        for (l, r) in [(l1, r1), (l2, r2)] {
            let arrow = format!("Return {kind} borrowed resource from {r} to {l}");
            assert_eq!(timeline_tooltips(&tl).iter().filter(|t| **t == arrow).count(), 2,
                "one return arrow {r} -> {l} on the `{brk}` row and one on the call's row");
        }
    }
}

/// #677: with a single, unbranched `break` in a `loop` that is a call's
/// argument, the call and the end of the borrow it uses are on the same
/// row, the loop's last line (`});`). The call used to be drawn up on the
/// `break` row, a row above where the lender's borrow ends.
#[test]
fn loop_call_arg_unbranched_call_and_borrow_end_share_a_row() {
    let rv = run_with_local_backend("loop_break_call_arg_unbranched");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (lender, kind, brk, call) in [
        ("a", "mutably", "break r;", "take reads and writes through r"),
        ("e", "immutably", "break re;", "look reads from re"),
    ] {
        let brk_row = code_row_y(&code, brk);
        let back = dots_listing_tooltip(&tl, &format!("{lender}'s resource is no longer {kind} borrowed"))
            .into_iter().map(|d| d.1).fold(f64::MIN, f64::max);
        let calls = dots_where(&tl, |lines| lines.iter().any(|l| l.starts_with(call)));
        assert!(
            calls.len() == 1 && back == calls[0].1 && back > brk_row,
            "{lender}'s borrow should end on the call's row (call dots {:?}), below `{brk}` (y={brk_row}), found y={}",
            calls, back
        );
    }
}

/// #739, #745: a borrow ends on the row where rustc's borrow checker
/// ends it. (On main, the for loops' loans ended at the binding's last
/// use, inside the body, and the old loans of `r` and `*z = &c` at the
/// write that replaced them: one row early / one row late.)
#[test]
fn borrow_ends_at_rustcs_end_for_loops_and_reassigned_refs() {
    let rv = run_with_local_backend("borrow_end_nll_loop");
    let (svg, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (text, line) in [
        // The iterator holds the loan until the loop ends.
        ("m's resource is no longer mutably borrowed", "} // end of mut_loop's for"),
        ("pairs's resource is no longer immutably borrowed", "} // end of shared_loop's for"),
        // `r` is overwritten before it is used again: a is free after
        // the println!.
        ("a's value is no longer immutably borrowed", "println!(\"{}\", r);"),
        // c's loan, made through `*z`, ends after the println!.
        ("c's value is no longer immutably borrowed", "println!(\"c value {}\", **z);"),
    ] {
        let ends = dots_with_tooltip(&svg, text);
        assert_eq!(ends.len(), 1, "{}: {:?}", text, ends);
        assert_eq!(ends[0].1, code_row_y(&code, line), "{:?} should be on the row of `{}`: {:?}", text, line, ends);
    }
}

/// #781: `match (g, (h, k)) { (r, z) => println!("{} {}", r, z.0) }`
/// moves `h` and `k` into `z` on the arm's line, and `z.0` / `z.1` take
/// their parts with it. Their acquire dots sat on the last row the
/// line's stacked arrows add, with every other event of the column, so
/// each column was a single dot with no lifeline. Each must have a state
/// line, from the row `z` is bound on down to where `z.0` / `z.1` are
/// dropped.
#[test]
fn nested_tuple_binding_member_columns_have_lifelines() {
    let t = run_with_local_backend("tuple_scrutinee_nested").timeline_panel_string();
    let mut checked = Vec::new();
    for x in t.split("<text ").skip(1) {
        let Some((tag, rest)) = x.split_once('>') else { continue };
        let label = rest.split('<').next().unwrap_or("");
        if !tag.contains("class=\"label") || !matches!(label, "z" | "z.0" | "z.1") {
            continue;
        }
        let hash = attr(tag, "data-hash").expect("a label has a data-hash");
        let bars: Vec<(f64, f64)> = start_tags(&t, "line")
            .into_iter()
            .filter(|l| attr(l, "data-hash") == Some(hash) && attr(l, "class").is_some_and(|c| c.starts_with("hollow") || c.starts_with("solid")))
            .filter_map(|l| Some((attr(l, "y1")?.parse().ok()?, attr(l, "y2")?.parse().ok()?)))
            .collect();
        assert!(bars.iter().any(|(a, b)| b > a), "{}'s column has no lifeline: {:?}", label, bars);
        checked.push(label);
    }
    assert_eq!(checked, ["z", "z.0", "z.1"]);
}

#[test]
fn borrow_made_in_one_arm_ends_only_on_that_arm() {
    // `c` points at `x` before the conditional; one arm re-points it at
    // `y` (`c = &y;`), another reads it. `y` is borrowed only on the arm
    // that made the borrow, so exactly one dot says its borrow ended and
    // exactly one arrow gives it back from `c`. Main drew a second pair
    // on the arm that reads `c` (where `c` still points at `x`), a false
    // "y is no longer borrowed" on a path where it never was (#800). The
    // `match` has two arms that each borrow a different variable.
    for (name, lenders) in [
        ("borrow_made_in_arm_if", &["y"][..]),
        ("borrow_made_in_arm_else", &["y"][..]),
        ("borrow_made_in_arm_match", &["y", "z"][..]),
    ] {
        let rv = run_with_local_backend(name);
        let tips = timeline_tooltips(&rv.timeline_panel_string());
        for l in lenders {
            for want in [
                format!("{}'s value is no longer immutably borrowed", l),
                format!("Return immutably borrowed value from c to {}", l),
            ] {
                let n = tips.iter().filter(|t| **t == want).count();
                assert_eq!(n, 1, "{}: {:?} appears {} times (want 1, on the arm that borrowed {})", name, want, n, l);
            }
        }
    }
}

/// #806: `c = &x;` before a conditional whose arms re-point `c` (`c = &y;`,
/// `c = &z;`) or read it. The borrow checker ends `x`'s loan on each path:
/// at the re-pointing write on an arm that re-points `c`, at `c`'s last use
/// on an arm that reads it. Main ended it on the first arm only (the later
/// arms saw `c` already pointing at `y`), so `x` was drawn as lent on the
/// other paths and `c`'s column ran on to the join with a dot with no
/// tooltip.
#[test]
fn old_lender_ends_once_per_arm_when_repointed_in_several_arms() {
    // (fixture, the source line each arm's end of x's loan is on)
    let cases: [(&str, &[&str]); 5] = [
        ("borrow_made_in_arm_match", &["0 => c = &y,", "1 => c = &z,", "_ => println!(\"{}\", c),"]),
        ("repoint_match_arms_806", &["0 => c = &y,", "1 => c = &z,", "2 => c = &w,", "_ => println!(\"{}\", c),"]),
        ("repoint_match_read_first_806", &["0 => println!(\"{}\", c),", "1 => c = &y,", "_ => c = &z,"]),
        ("repoint_if_chain_806", &["c = &y;", "c = &z;", "println!(\"{}\", c);"]),
        ("repoint_if_chain_read_middle_806", &["c = &y;", "println!(\"{}\", c);", "c = &z;"]),
    ];
    for (name, lines) in cases {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let mut ends = dots_listing_tooltip(&timeline, "x's value is no longer immutably borrowed");
        ends.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap());
        assert_eq!(ends.len(), lines.len(), "{}: x's borrow should end once per arm: {:?}", name, ends);
        for (end, src) in ends.iter().zip(lines.iter()) {
            let want = code_row_y(&code, src);
            assert!((end.1 - want).abs() < 10.0,
                "{}: x's loan ends at {:?} (y={}), not at the row of `{}` (y={})", name, end, end.1, src, want);
        }
        let empty: Vec<_> = tooltip_lines(&timeline).into_iter().filter(|l| l.iter().all(|t| t.trim().is_empty())).collect();
        assert!(empty.is_empty(), "{}: {} dot(s) with an empty tooltip", name, empty.len());
    }
}

/// #814: `// rustviz: hide` on a struct, enum, impl or `use` line (and on a
/// `#[derive]` line above an item) removes the whole item from the code
/// panel, like a hidden fn. Main stripped the marker text and hid nothing.
/// The rest of the program still renders: the struct's instance `g` and its
/// `s` field keep their tooltips.
#[test]
fn hide_marker_hides_struct_enum_impl_use() {
    let rv = run_with_local_backend("hide_items_814");
    let (code, timeline) = (rv.code_panel_string(), rv.timeline_panel_string());
    for gone in ["struct Greeter", "enum Mood", "impl Greeter", "use std::fmt::Write", "derive", "Sad", "rustviz"] {
        assert!(!code.contains(gone), "`{}` should be hidden from the code panel:\n{}", gone, code);
    }
    assert!(code.contains("fn") && code.contains("main") && code.contains("Ferris"), "main must stay:\n{}", code);
    assert!(timeline.contains("g.s"), "g.s's column must survive:\n{}", timeline);
}

/// #814: a `hide` marker that hides nothing (here on a `let`) is not an
