/// #817: the variables inside the arguments of `assert!` and its
/// relatives are highlighted in the code panel (a `data-hash` span, which
/// is also their hover target), like the arguments of a plain call. The
/// macro's own name and the generated panic code are not.
#[test]
fn assert_macro_arguments_are_coloured_in_the_code_panel() {
    let rv = run_with_local_backend("assert_macro_args_817");
    let code = rv.code_panel_string();
    let rows: Vec<&str> = code.split("</text>").collect();
    let row_of = |src: &str| -> &str {
        let hits: Vec<&&str> = rows.iter().filter(|r| r.contains(src)).collect();
        assert_eq!(hits.len(), 1, "code rows containing {:?}: {}", src, hits.len());
        hits[0]
    };
    let coloured = |row: &str, var: &str| {
        let needle = format!(">{var}</tspan>");
        row.match_indices(&needle).any(|(i, _)| row[..i].rfind("<tspan").is_some_and(|t| row[t..i].contains("data-hash=")))
    };
    for (line, vars) in [
        ("    assert!(", &["r1", "r2"][..]),
        ("    assert_eq!(", &["r1", "r2"]),
        ("    assert_ne!(", &["r1"]),
        ("    debug_assert!(", &["r1", "r2"]),
        ("    debug_assert_eq!(", &["r1", "r2"]),
        ("    debug_assert_ne!(", &["r2"]),
    ] {
        let row = row_of(line);
        for v in vars {
            assert!(coloured(row, v), "{v} in `{line}...` has no code-panel colouring: {row}");
        }
    }
    // The macro name is plain text, not a highlighted function.
    assert!(!row_of("    assert!(").contains(">assert!</tspan>"));
}

/// #824: the variables inside the arguments of `println!`, `format!`,
/// `write!` and the other formatting macros are highlighted in the code
/// panel (and so are hover targets), like the arguments of a plain call.
/// The macro's own name is plain text.
#[test]
fn format_macro_arguments_are_coloured_in_the_code_panel() {
    let rv = run_with_local_backend("fmt_macro_args_824");
    let code = rv.code_panel_string();
    let rows: Vec<&str> = code.split("</text>").collect();
    let row_of = |src: &str| -> &str {
        // `println!("{t}")` (an implicit capture) is not a row under test.
        let hits: Vec<&&str> = rows.iter().filter(|r| r.contains(src) && !r.contains("{t}")).collect();
        assert_eq!(hits.len(), 1, "code rows containing {:?}: {}", src, hits.len());
        hits[0]
    };
    let coloured = |row: &str, var: &str| {
        let needle = format!(">{var}</tspan>");
        row.match_indices(&needle).any(|(i, _)| row[..i].rfind("<tspan").is_some_and(|t| row[t..i].contains("data-hash=")))
    };
    for (line, vars) in [
        ("    println!(", &["r1"][..]),
        ("    print!(", &["r1", "r2"]),
        ("    eprintln!(", &["r2"]),
        ("    eprint!(", &["r1"]),
        ("= format!(", &["r1", "r2"]),
        ("    write!(", &["out", "r1"]),
        ("    writeln!(", &["out", "r2"]),
        ("        panic!(", &["r1"]),
    ] {
        let row = row_of(line);
        for v in vars {
            assert!(coloured(row, v), "{v} in `{line}...` has no code-panel colouring: {row}");
        }
    }
    // The implicit capture `{t}` is inside the format string: no
    // highlight is nested in the string's span (the markup stays
    // well-formed), and the explicit arguments elsewhere are unaffected.
    for r in &rows {
        assert_eq!(r.matches("<tspan").count(), r.matches("</tspan>").count(), "unbalanced markup: {r}");
    }
    // The macro name is plain text, not a highlighted function.
    assert!(!row_of("    print!(").contains(">print!</tspan>"));
    assert!(!row_of("= format!(").contains(">format!</tspan>"));
}

/// #960: `keep(&mut v, &x)` with x a reference variable and a signature
/// that lets keep store `&x` in v: x stays borrowed until v's last use
/// (`v.len()`), as the borrow checker keeps it, not until keep returns.
/// Likewise m with `keep_mut(&mut w, &mut m)`.
#[test]
fn stored_borrow_of_a_reference_variable_ends_at_the_holders_last_use() {
    let svg = run_with_local_backend("stored_ref_var_arg_960").timeline_panel_string();
    for (var, holder, kind) in [("x", "v", "immutably"), ("m", "w", "mutably")] {
        let end = dots_listing_tooltip(&svg, &format!("{var} is no longer {kind} borrowed"));
        let last_use = dots_listing_tooltip(&svg, &format!("{holder}'s resource is immutably borrowed by len; {holder} is read-only while the borrow is live"));
        assert_eq!(last_use.len(), 1, "{holder}.len(): {:?}", last_use);
        assert!(end.iter().any(|(_, y)| *y == last_use[0].1),
            "{var}'s borrow should end on {holder}.len()'s row ({:?}), got {:?}", last_use, end);
    }
    // The storing call's dot doesn't end the borrow.
    for lines in tooltip_lines(&svg) {
        if lines.iter().any(|l| l.contains("'s signature lets it store this reference")) {
            assert!(!lines.iter().any(|l| l.contains("no longer")), "a stored borrow ends at the call: {:?}", lines);
        }
    }
}

/// #861: a write through the `&mut` a `get_mut` call (or `&mut v[1]`,
/// `v.iter_mut()`) gives is drawn on the collection's column, on the
/// write's row, and before the end of the borrow it was done through.
#[test]
fn get_mut_writes_are_drawn_on_the_collection() {
    let rv = run_with_local_backend("get_mut_write_861");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (column, line, write, then) in [
        ("v", "*v.get_mut(0).unwrap() += 1;", "v's resource is modified through v.get_mut(0).unwrap()", Some("v's resource is no longer mutably borrowed")),
        ("v", "*x += 10;", "v's resource is modified through x", Some("v's resource is no longer mutably borrowed")),
        ("v", "*y = 7;", "*y is assigned a new value", Some("v's resource is no longer mutably borrowed")),
        ("m", "*m.get_mut(\"k\").unwrap() = 5;", "*m.get_mut(…).unwrap() is assigned a new value", Some("m's resource is no longer mutably borrowed")),
        ("names", "*names.get_mut(0).unwrap() = String::from(\"c\");",
            "*names.get_mut(0).unwrap() acquires ownership of a new resource; its previous resource is dropped",
            Some("names's resource is no longer mutably borrowed")),
        ("names", "*n = String::from(\"d\");", "*n acquires ownership of a new resource; its previous resource is dropped",
            Some("names's resource is no longer mutably borrowed")),
        ("b.items", "*it = String::from(\"f\");", "*it acquires ownership of a new resource; its previous resource is dropped",
            Some("b.items's resource is no longer mutably borrowed")),
        ("v", "*e *= 2;", "v's resource is modified through e", None),
    ] {
        let at = (label_x(&tl, column), code_row_y(&code, line));
        let dots = dots_where(&tl, |lines| {
            let w = lines.iter().position(|l| l == write);
            match then {
                Some(t) => w.is_some_and(|w| lines.iter().position(|l| l == t).is_some_and(|e| w < e)),
                None => w.is_some(),
            }
        });
        assert!(dots.contains(&at), "`{}`: expected {:?} (then {:?}) on {}'s column at {:?}, found {:?}", line, write, then, column, at, dots);
    }
}

/// #967: a write through a reference into part of what a `&mut Vec`
