/// #913: a reference copied into a variable that outlives it (`x = w;`,
/// `*r = w;`, `v.push(w);`): its own borrow ends at its last use, the
/// copy (Q7, P2-1b: the copy holds the loan on and gives it back), on a
/// dot above its scope end and nowhere below it: the old plugin drew
/// "w's immutable borrow ends" (with a return arrow) a row after "w goes
/// out of scope", on the copy's last-use row; main drew it in the
/// scope-end dot.
#[test]
fn copied_reference_ends_with_its_scope() {
    let rv = run_with_local_backend("ref_copy_outlives_scope_913");
    let svg = rv.timeline_panel_string();
    let groups = tooltip_lines(&svg);
    for w in ["w", "w2", "w3", "w4"] {
        let (end, scope) = (format!("{w}'s immutable borrow ends"), format!("{w} goes out of scope"));
        let dot: Vec<&Vec<String>> = groups.iter().filter(|g| g.contains(&scope)).collect();
        assert_eq!(dot, vec![&vec![scope.clone()]], "{w}'s scope-end dot");
        let ends = dots_listing_tooltip(&svg, &end);
        let scopes = dots_listing_tooltip(&svg, &scope);
        assert_eq!(ends.len(), 1, "{w}: one end: {ends:?}");
        assert!(ends[0].1 < scopes[0].1, "{w}'s borrow end above its scope end: {ends:?} {scopes:?}");
    }
    // Each end on the row of the copy (its last use), not anywhere above
    // the scope end: before the copy w still holds the loan.
    for id in ["w@L11:dot:duplicate+static_die", "w2@L24:dot:static_die", "w3@L36:dot:static_die", "w4@L47:dot:"] {
        assert!(svg.contains(&format!("data-rv-id=\"{id}")), "no {id}");
    }
    let w4_end = dots_listing_tooltip(&svg, "w4's immutable borrow ends");
    assert!(!w4_end.is_empty() && w4_end == dots_listing_tooltip(&svg, "push reads from w4"), "w4's end on its push dot");
}

/// #904: a `&mut` reference that `*r = &t` writes through has one line
/// (bracket), from its borrow to its last use. Main drew a second one
/// from the write to r's scope end ("r ... can only read it", or, for
/// `*k = &mut h`, "k holds a mutable reference; it can read and write").
#[test]
fn write_through_mut_ref_to_ref_ends_its_line_at_the_last_use() {
    let rv = run_with_local_backend("mut_ref_to_ref_write_end_904");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (name, borrow, last_use) in [
        ("r", "let r = &mut x;", "*r = &t;"),
        ("w", "let w = &mut y;", "println!(\"{}\", w);"),
        ("q", "let q = &mut z;", "*q = &v;"),
        ("k", "let k = &mut m;", "*k = &mut h;"),
        ("p", "let p = &mut o;", "*p = &e;"),
        ("el", "let el = &mut refs[0];", "*el = &t1;"),
    ] {
        let label = format!("&gt;{name}&lt;/span&gt; holds a");
        // `d="M x y l 15 dy v dy l -15 dy"` (numbers: x y 15 dy dy -15
        // dy): from y to y plus the three dys.
        let spans: Vec<(f64, f64)> = start_tags(&timeline, "path")
            .into_iter()
            .filter(|t| attr(t, "data-tooltip-text").is_some_and(|tt| tt.contains(&label)))
            .filter_map(|t| {
                let d: Vec<f64> = attr(t, "d")?.split(' ').filter_map(|n| n.parse().ok()).collect();
                (d.len() == 7).then(|| (d[1], d[1] + d[3] + d[4] + d[6]))
            })
            .collect();
        let want = (code_row_y(&code, borrow), code_row_y(&code, last_use));
        assert_eq!(spans, vec![want], "{}: one line from `{}` to `{}`", name, borrow, last_use);
    }
}

/// #973, #974: a borrow a call stored in a holder (`refs.push(&x)`,
/// `keep(&mut v, &s)`) keeps its lender borrowed until the holder's last
/// use, so a shorter borrow that ends before it (a call's, a reference's)
/// doesn't end the lender's borrow: rustc rejects moving s anywhere
/// above the holder's last use (and `x = &b;`, were x `mut`). Main ended s's borrow
/// at `look(&s)`, at r's last use and (for t) at u's last use while q
/// still borrowed t; x's at `look(&x)` / `look_ref(&x)`; and y's at
/// `look_ref(&y)` while `ry = &y` still borrowed it. Each
/// lender is now unborrowed exactly once, on the row of the last
/// borrower's last use, and drawn as shared down to there.
#[test]
fn a_stored_borrow_keeps_its_lender_shared_until_the_holders_last_use() {
    let cases: [(&str, &str, &str, &str, &[&str], &str); 6] = [
        ("stored_ref_var_push_973", "x is no longer immutably borrowed", "", "refs.push(&x);",
         &["let n = look(&x);"], "println!(\"{} {}\", refs.len(), n);"),
        ("stored_ref_var_push_973", "m is no longer mutably borrowed", "", "muts.push(&mut m);",
         &[], "println!(\"{}\", muts.len());"),
        ("stored_borrow_sharers_974", "s's resource is no longer immutably borrowed", "s is the owner of the resource", "keep(&mut v, &s);",
         &["let n = look(&s);", "println!(\"{} {}\", r, n);"], "println!(\"{}\", v.len());"),
        ("stored_borrow_sharers_974", "t's resource is no longer immutably borrowed", "t is the owner of the resource", "keep(&mut u, &t);",
         &["println!(\"{}\", u.len());"], "println!(\"{}\", q);"),
        ("stored_borrow_sharers_974", "x is no longer immutably borrowed", "", "keep_ref(&mut w, &x);",
         &["let k = look_ref(&x);"], "println!(\"{} {}\", w.len(), k);"),
        ("stored_borrow_sharers_974", "y is no longer immutably borrowed", "", "let ry = &y;",
         &["let j = look_ref(&y);"], "println!(\"{} {}\", ry.len(), j);"),
    ];
    let mut failures = Vec::new();
    for (name, back_text, owner_text, store_src, early_srcs, end_src) in cases {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let (store_row, end_row) = (code_row_y(&code, store_src), code_row_y(&code, end_src));
        // The calls / references that end their part of the borrow
        // early sit between the store and the end.
        for src in early_srcs {
            let row = code_row_y(&code, src);
            assert!(row > store_row && row < end_row, "{name}: `{src}` isn't between the store and the end");
        }
        let back = dots_listing_tooltip(&timeline, back_text);
        if !(back.len() == 1 && (back[0].1 - end_row).abs() < 1.0) {
            failures.push(format!("{name}: \"{back_text}\" should be on the last use's row only (y={end_row}), got {back:?}"));
        }
        if !owner_text.is_empty() {
            let owner = state_lines_with_tooltip(&timeline, owner_text);
            let free: Vec<_> = owner.iter().filter(|(a, b)| b.min(end_row) - a.max(store_row) > 0.5).collect();
            if !free.is_empty() {
                failures.push(format!("{name}: drawn as \"{owner_text}\" at {free:?}, between the store (y={store_row}) and the end (y={end_row})"));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// #990: after `keep(&mut v, &s)` may store `&s` in v, moving v's value
/// on (`let w = v;`, twice, into a struct field `H { v: vb }`, or
/// through `pass(vc)`, whose signature gives its result the argument's
/// lifetime) moves the borrow with it, so the lender stays borrowed
/// until the last holder's last use: rustc rejects moving s (t, a, b,
/// c) anywhere above it. Main ended the borrow at `look(&s)` (and at r's
/// last use for t) and drew the lender as its owner from there. Each
/// lender is now unborrowed exactly once, on the row of the last
/// holder's last use, and drawn as shared down to there.
#[test]
fn a_stored_borrow_moves_on_with_its_holders_value() {
    let name = "stored_borrow_holder_moved_990";
    let cases: [(&str, &str, &str, &[&str], &str); 5] = [
        ("s's resource is no longer immutably borrowed", "s is the owner of the resource", "keep(&mut v, &s);",
         &["let w = v;", "let n = look(&s);"], "println!(\"{} {}\", w.len(), n);"),
        ("t's resource is no longer immutably borrowed", "t is the owner of the resource", "keep(&mut v2, &t);",
         &["let w2 = v2;", "println!(\"{}\", r);"], "println!(\"{}\", w2.len());"),
        ("a's resource is no longer immutably borrowed", "a is the owner of the resource", "keep(&mut va, &a);",
         &["let wa = va;", "let xa = wa;", "let na = look(&a);"], "println!(\"{} {}\", xa.len(), na);"),
        ("b's resource is no longer immutably borrowed", "b is the owner of the resource", "keep(&mut vb, &b);",
         &["let h = H { v: vb };", "let nb = look(&b);"], "println!(\"{} {}\", h.v.len(), nb);"),
        ("c's resource is no longer immutably borrowed", "c is the owner of the resource", "keep(&mut vc, &c);",
         &["let wc = pass(vc);", "let nc = look(&c);"], "println!(\"{} {}\", wc.len(), nc);"),
    ];
    let rv = run_with_local_backend(name);
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let mut failures = Vec::new();
    for (back_text, owner_text, store_src, early_srcs, end_src) in cases {
        let (store_row, end_row) = (code_row_y(&code, store_src), code_row_y(&code, end_src));
        for src in early_srcs {
            let row = code_row_y(&code, src);
            assert!(row > store_row && row < end_row, "{name}: `{src}` isn't between the store and the end");
        }
        let back = dots_listing_tooltip(&timeline, back_text);
        if !(back.len() == 1 && (back[0].1 - end_row).abs() < 1.0) {
            failures.push(format!("{name}: \"{back_text}\" should be on the last use's row only (y={end_row}), got {back:?}"));
        }
        let owner = state_lines_with_tooltip(&timeline, owner_text);
        let free: Vec<_> = owner.iter().filter(|(a, b)| b.min(end_row) - a.max(store_row) > 0.5).collect();
        if !free.is_empty() {
            failures.push(format!("{name}: drawn as \"{owner_text}\" at {free:?}, between the store (y={store_row}) and the end (y={end_row})"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// #997: after `keep(&mut v, &s)` may store `&s` in v, the borrow is
/// held by whatever holds v's value while it is in use, path by path
/// (rustc's loan liveness): both v and a copy of it (`let w = v;` with
/// `v: Option<&String>`) until their own last uses; after a move in one
/// arm, the new owner on that arm's path and v on the others; and on an
/// arm where v isn't used again, nothing. rustc rejects moving the
/// lender right after each `look` below that names a holder, and
/// accepts it after f's in the if arm (and t's / a's in the last arm of
/// `stored_borrow_end_in_arms_997`). Main named v after the copy (s,
/// b), only v (a), and in the arms said the lender was free (t, d) or
/// held by a holder that's dead there (e, f). A loan that ends inside
/// an arm now ends in every arm, after that path's last holder's last
/// use (x.len(), u.len(), y.len(), w.len(), va.len()); main drew one end
/// outside the arms, mid-conditional.
#[test]
fn a_stored_borrow_is_held_by_its_live_holders_on_each_path() {
    let (copy_or_arm, in_arms) = ("stored_borrow_holder_copy_or_arm_997", "stored_borrow_end_in_arms_997");
    let still = |l: &str, h: &str| format!("{l}'s resource is no longer borrowed by look, but is still immutably borrowed by {h}");
    let ended = |l: &str, kind: &str| format!("{l}'s resource is no longer {kind} borrowed");
    // (fixture, the text, its row's source, which of the rows showing it)
    let cases: Vec<(&str, String, &str, usize)> = vec![
        (copy_or_arm, still("s", "w"), "let n = look(&s);", 0),
        (copy_or_arm, still("a", "va and wa"), "let na = look(&a);", 0),
        (copy_or_arm, still("a", "va"), "let ma = look(&a);", 0),
        (copy_or_arm, still("b", "xb"), "let nb = look(&b);", 0),
        (copy_or_arm, still("t", "x"), "let n = look(&t);", 0),
        (copy_or_arm, still("t", "u"), "let n = look(&t);", 1),
        (copy_or_arm, still("d", "wd"), "let n0 = look(&d);", 0),
        (copy_or_arm, still("d", "xd"), "let n1 = look(&d);", 0),
        (copy_or_arm, still("d", "vd"), "let n2 = look(&d);", 0),
        (copy_or_arm, still("e", "we"), "let ne = look(&e);", 0),
        (copy_or_arm, still("e", "ve"), "let ne = look(&e);", 1),
        (copy_or_arm, ended("f", "immutably"), "let nf = look(&f);", 0),
        (copy_or_arm, still("f", "vf"), "let nf = look(&f);", 1),
        (copy_or_arm, ended("t", "immutably"), "println!(\"{} {}\", x.len(), n);", 0),
        (copy_or_arm, ended("t", "immutably"), "println!(\"{} {}\", u.len(), n);", 0),
        (in_arms, ended("t", "immutably"), "println!(\"{}\", x.len());", 0),
        (in_arms, still("t", "u"), "let n = look(&t);", 0),
        (in_arms, ended("t", "immutably"), "println!(\"{} {}\", u.len(), n);", 0),
        (in_arms, ended("t", "immutably"), "let n = look(&t);", 1),
        (in_arms, ended("m", "mutably"), "println!(\"{}\", y.len());", 0),
        (in_arms, ended("m", "mutably"), "println!(\"{}\", w.len());", 0),
        (in_arms, ended("a", "immutably"), "println!(\"{} {}\", va.len(), n);", 0),
    ];
    let mut failures = Vec::new();
    for name in [copy_or_arm, in_arms] {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let mine: Vec<&(&str, String, &str, usize)> = cases.iter().filter(|c| c.0 == name).collect();
        for (_, text, src, nth) in &mine {
            let row = code_rows_y(&code, src)[*nth];
            let ys: Vec<f64> = dots_listing_tooltip(&timeline, text).iter().map(|d| d.1).collect();
            if !ys.iter().any(|y| (y - row).abs() < 1.0) {
                failures.push(format!("{name}: \"{text}\" should be on `{src}` (#{nth}, y={row}), got {ys:?}"));
            }
            // A holder named on a row it doesn't hold the borrow on. (A
            // borrow's end is checked only where it's listed: it is also
            // at the start of an arm no holder reaches.)
            let rows: Vec<f64> = mine.iter().filter(|c| c.1 == *text).map(|c| code_rows_y(&code, c.2)[c.3]).collect();
            let extra: Vec<&f64> = ys.iter().filter(|y| !rows.iter().any(|r| (*y - r).abs() < 1.0)).collect();
            if text.contains("but is still") && !extra.is_empty() {
                failures.push(format!("{name}: \"{text}\" also at {extra:?}"));
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// #1003: a clone of a stored borrow's holder (`let w = v.clone();`,
/// `Clone::clone(&v)`, `v.to_vec()`, with v: Vec<&String>) holds copies
/// of the references in v, so it keeps the lender borrowed as v does,
/// each until its own last use (a Vec's drop doesn't use them); one of a
/// type with its own Drop (D) until it is dropped. rustc rejects moving
/// the lender right after each look below; the borrow ends where the
/// last holder is last used. Main named the original holder at each
/// look (v, va, vb, vc, h.v, vm, d).
#[test]
fn a_stored_borrow_is_held_by_clones_of_its_holder() {
    let name = "stored_borrow_holder_clone_1003";
    let still = |l: &str, h: &str| format!("{l}'s resource is no longer borrowed by look, but is still immutably borrowed by {h}");
    let ended = |l: &str| format!("{l}'s resource is no longer immutably borrowed");
    let cases: Vec<(String, &str)> = vec![
        (still("s", "w"), "let n = look(&s);"),
        (ended("s"), "println!(\"{} {}\", w.len(), n);"),
        (still("a", "va and wa"), "let na = look(&a);"),
        (ended("a"), "println!(\"{} {} {}\", va.len(), wa.len(), na);"),
        (still("b", "wb"), "let nb = look(&b);"),
        (ended("b"), "println!(\"{} {}\", wb.len(), nb);"),
        (still("c", "wc"), "let nc = look(&c);"),
        (ended("c"), "println!(\"{} {}\", wc.len(), nc);"),
        (still("t", "h2.v"), "let nt = look(&t);"),
        (ended("t"), "println!(\"{} {}\", h2.v.len(), nt);"),
        (still("m", "xm"), "let nm = look(&m);"),
        (ended("m"), "println!(\"{} {}\", xm.len(), nm);"),
        (still("g", "d and e"), "let ng = look(&g);"),
    ];
    let rv = run_with_local_backend(name);
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let mut failures = Vec::new();
    for (text, src) in &cases {
        let row = code_rows_y(&code, src)[0];
        let ys: Vec<f64> = dots_listing_tooltip(&timeline, text).iter().map(|d| d.1).collect();
        if ys.len() != 1 || (ys[0] - row).abs() >= 1.0 {
            failures.push(format!("\"{text}\" should be on `{src}` only (y={row}), got {ys:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// #1015: a value made from a stored borrow's holder whose type rustc
/// ties to the stored reference (`let w: Vec<&String> =
/// v.iter().copied().collect();`, an iterator over v, `v.first().copied()`,
/// `v[0]`, `firsts(&v)`) holds it too, until its own last use (dg, whose
/// type has its own Drop, until it is dropped at the end of the fn).
/// rustc rejects moving the lender right after each look below; the
/// borrow ends where the last holder is last used. Main named the
/// holder (v, va, vb, vc, vd, ve, vg) at each look, and drew f free at
/// its look.
#[test]
fn a_stored_borrow_is_held_by_values_made_from_its_holder() {
    let name = "stored_borrow_derived_holder_1015";
    let still = |l: &str, h: &str| format!("{l}'s resource is no longer borrowed by look, but is still immutably borrowed by {h}");
    let ended = |l: &str| format!("{l}'s resource is no longer immutably borrowed");
    let cases: Vec<(String, &str)> = vec![
        (still("s", "w"), "let n = look(&s);"),
        (ended("s"), "println!(\"{} {}\", w.len(), n);"),
        (still("a", "it"), "let na = look(&a);"),
        (ended("a"), "println!(\"{} {}\", it.count(), na);"),
        (still("b", "fb"), "let nb = look(&b);"),
        (ended("b"), "println!(\"{:?} {}\", fb, nb);"),
        (still("c", "rc"), "let nc = look(&c);"),
        (ended("c"), "println!(\"{} {}\", rc, nc);"),
        (still("d", "wd"), "let nd = look(&d);"),
        (ended("d"), "println!(\"{} {}\", wd.len(), nd);"),
        (still("e", "ve and we"), "let ne = look(&e);"),
        (ended("e"), "println!(\"{} {} {}\", ve.len(), we.len(), ne);"),
        (still("f", "xf"), "let nf = look(&f);"),
        (ended("f"), "println!(\"{} {}\", xf.len(), nf);"),
        (still("g", "dg.v"), "let ng = look(&g);"),
    ];
    let rv = run_with_local_backend(name);
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let mut failures = Vec::new();
    for (text, src) in &cases {
        let row = code_rows_y(&code, src)[0];
        let ys: Vec<f64> = dots_listing_tooltip(&timeline, text).iter().map(|d| d.1).collect();
        if ys.len() != 1 || (ys[0] - row).abs() >= 1.0 {
            failures.push(format!("\"{text}\" should be on `{src}` only (y={row}), got {ys:?}"));
        }
    }
    // dg's drop at the end of into_drop may use the reference: g stays
    // borrowed past dg's last use, until then.
    let after = code_rows_y(&code, "println!(\"{}\", ng);")[0];
    let ends: Vec<f64> = dots_listing_tooltip(&timeline, &ended("g")).iter().map(|d| d.1).collect();
    if ends.len() != 1 || ends[0] <= after {
        failures.push(format!("g's borrow should end after `println!(\"{{}}\", ng);` (y={after}), got {ends:?}"));
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// #1046 / #1047 / #1048 (`param_writes_1046`): where each text sits.
/// `for e in v.iter_mut()` with v a `&mut Vec` keeps v borrowed until
/// the loop's `}`, not just the `for` line, and draws `*e += 1` on v's
/// row; one dot lists a reborrow's end before the parameter's own; a
/// write to all of what u / n point to through a reborrow is on u's / n's
/// column on the write's row.
#[test]
fn param_writes_are_drawn_on_the_parameter() {
    let rv = run_with_local_backend("param_writes_1046");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    // Fixture order: bump_all's loop `}` is the first `}`, double_then_push's
    // the third, through_local_ref's the fifth.
    let rows = [
        ("v", code_rows_y(&code, "*e += 1;")[0], "the resource v points to is modified through e", None),
        ("v", closes[0], "the `for` loop's iterator no longer borrows the resource v points to", Some("v's mutable borrow ends")),
        ("w", code_row_y(&code, "*e *= 2;"), "the resource w points to is modified through e", None),
        ("w", closes[2], "the `for` loop's iterator no longer borrows the resource w points to", None),
        ("r", closes[4], "the `for` loop's iterator no longer borrows the resource r points to", Some("r's mutable borrow ends")),
        ("s", closes[4], "s's resource is no longer mutably borrowed", None),
        ("t", code_row_y(&code, "*y = 7;"), "y no longer borrows the resource t points to", Some("t's mutable borrow ends")),
        ("u", code_row_y(&code, "*q = vec![9];"), "*u acquires ownership of a new resource; its previous resource is dropped",
            Some("q no longer borrows the resource u points to")),
        ("n", code_row_y(&code, "*x += 1;"), "the value n points to is modified through x", Some("x no longer borrows the value n points to")),
    ];
    for (column, y, text, then) in rows {
        let at = (label_x(&tl, column), y);
        let dots = dots_where(&tl, |lines| {
            let w = lines.iter().position(|l| l == text);
            w.is_some_and(|w| then.is_none_or(|t| lines.iter().position(|l| l == t).is_some_and(|e| w < e)))
        });
        assert!(dots.contains(&at), "expected {:?} (then {:?}) on {}'s column at {:?}, found {:?}", text, then, column, at, dots);
    }
    // The `for` line no longer ends v's borrow.
    let for_line = (label_x(&tl, "v"), code_row_y(&code, "for e in v.iter_mut() {"));
    let ends_there = dots_where(&tl, |lines| lines.iter().any(|l| l == "v's mutable borrow ends"));
    assert!(!ends_there.contains(&for_line), "v's borrow still ends on the `for` line: {:?}", ends_there);
}

/// #1032: a loop inside another, after a branch that may have moved s,
/// may end before assigning s (`if c { drop(s); } for … { while n < i {
/// s = …; } s = …"c"; }`): on the outer loop's first time round s may
/// hold nothing from the inner loop's end to the next assignment. The
/// column used to keep its owner line ("s is the owner of the
/// resource") through that stretch. Now the inner loop's closing row
/// has a dot saying s may have no value, and no owner line runs from
/// it to the next assignment (as after any maybe-moved dot), while one
/// still runs inside the inner loop and after the assignment.
#[test]
fn a_loop_inside_another_that_may_not_assign_draws_no_owner_line() {
    for (name, var, inner_src, after_src) in [
        ("loop_struct_line_1031", "s", "s = String::from(\"b\");", "s = String::from(\"c\");"),
        ("loop_struct_line_1031", "p", "p = P { name: String::from(\"b\") };", "p = P { name: String::from(\"c\") };"),
        ("loop_struct_line_1031", "p.name", "p = P { name: String::from(\"b\") };", "p = P { name: String::from(\"c\") };"),
        ("loop_drop_flags_1026", "s", "s = String::from(\"b\");", "s = String::from(\"c\");"),
        ("loop_drop_flags_1026", "p", "p = P { name: String::from(\"b\") };", "p = P { name: String::from(\"c\") };"),
    ] {
        let rv = run_with_local_backend(name);
        let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let inner_row = code_rows_y(&code, inner_src)[0];
        let close_row = code_rows_y(&code, "}").into_iter().find(|y| *y > inner_row).expect("the inner loop's closing brace");
        let after_row = code_rows_y(&code, after_src).into_iter().find(|y| *y > close_row).expect("the assignment after the inner loop");
        let text = format!(
            "{var} may have no value after the loop: it may have none where the loop starts, and the loop may end \
             before assigning it, so it can't be used after the loop (until it's assigned again). If it has one, its \
             resource is dropped when {var} is assigned again (or, if {var} is never assigned again, when {var} goes out of scope)."
        );
        let owner = column_lines_with_tooltip(&timeline, &format!("{var} is the owner of the resource"));
        let through: Vec<_> = owner.iter().filter(|(a, b)| b.min(after_row) - a.max(close_row) > 0.5).collect();
        assert!(
            through.is_empty(),
            "{name}: {var} drawn as the owner at {through:?}, between the inner loop's end (y={close_row}) and `{after_src}` (y={after_row})",
        );
        let dots = dots_with_tooltip(&timeline, &text);
        let near: Vec<_> = dots.iter().filter(|d| d.1 > inner_row && d.1 < after_row).collect();
        assert!(
            near.len() == 1 && (near[0].1 - close_row).abs() < 1.0,
            "{name}: {var} should have one maybe-no-value dot on the inner loop's closing row (y={close_row}): {dots:?}",
        );
        assert!(
            owner.iter().any(|(a, b)| *a <= inner_row + 0.5 && *b >= close_row - 0.5),
            "{name}: {var} has no owner line from `{inner_src}` (y={inner_row}) to the inner loop's end (y={close_row}): {owner:?}",
        );
        assert!(
            owner.iter().any(|(a, b)| *a <= after_row + 0.5 && *b > after_row + 0.5),
            "{name}: {var} has no owner line after `{after_src}` (y={after_row}): {owner:?}",
        );
    }
}

/// The y ranges of the vertical column lines (`<line>`s of their own,
/// not in a group) whose tooltip is exactly `text`.
fn column_lines_with_tooltip(svg: &str, text: &str) -> Vec<(f64, f64)> {
    start_tags(svg, "line")
        .into_iter()
        .filter(|l| attr(l, "x1").is_some() && attr(l, "x1") == attr(l, "x2") && timeline_tooltips(l) == [text])
        .filter_map(|l| Some((attr(l, "y1")?.parse::<f64>().ok()?, attr(l, "y2")?.parse::<f64>().ok()?)))
        .map(|(a, b)| (a.min(b), a.max(b)))
        .collect()
}

/// #1034: a conditional that gives a new value, in only some of its
/// branches, to a variable that may hold none where it starts (`if c {
/// drop(s); } if x { s = …; }`). An `if` with no `else` there was drawn
/// inline, and the column kept its owner line ("s is the owner of the
/// resource") past the `if`'s closing brace, where s may hold nothing.
/// Now the `if` is drawn as a branch, its join on the closing brace's
/// row has a dot saying s may have no value, and no owner line runs
/// from there to the row that ends the check (the scope end, or the
/// next assignment).
#[test]
fn a_conditional_that_may_leave_a_variable_empty_draws_no_owner_line_after_it() {
    let rv = run_with_local_backend("maybe_held_if_1034");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (var, assign_src, until_src, when) in [
        ("s", "s = String::from(\"c\");", "}", "goes out of scope"),
        ("t", "t = String::from(\"c\");", "}", "goes out of scope"),
        ("u", "u = String::from(\"c\");", "u = String::from(\"d\");", "is assigned again"),
        ("v", "v = String::from(\"c\");", "}", "is assigned again (or, if v is never assigned again, when v goes out of scope)"),
        ("w", "w = String::from(\"c\");", "}", "goes out of scope"),
        ("q", "q = String::from(\"c\");", "}", "is assigned again (or, if q is never assigned again, when q goes out of scope)"),
    ] {
        let assign_row = code_rows_y(&code, assign_src)[0];
        // (with_else's `} else {` row isn't a "}" one: its `if` ends at
        // the `else` block's closing brace.)
        let close_row = code_rows_y(&code, "}").into_iter().find(|y| *y > assign_row).expect("the conditional's closing brace");
        let until_row = code_rows_y(&code, until_src).into_iter().find(|y| *y > close_row).expect("the row after it");
        let text = format!(
            "{var} may have no value after the branches: it may have had none where they start, and only some of \
             them assign it, so it can't be used after the branches (until it's assigned again). If it has one, its \
             resource is dropped when {var} {when}."
        );
        let dots = dots_listing_tooltip(&timeline, &text);
        assert!(
            dots.len() == 1 && (dots[0].1 - close_row).abs() < 1.0,
            "{var}: one maybe-no-value dot on the conditional's closing row (y={close_row}) expected: {dots:?}",
        );
        let owner = column_lines_with_tooltip(&timeline, &format!("{var} is the owner of the resource"));
        let through: Vec<_> = owner.iter().filter(|(a, b)| b.min(until_row) - a.max(close_row) > 0.5).collect();
        assert!(
            through.is_empty(),
            "{var} drawn as the owner at {through:?}, between the conditional's end (y={close_row}) and `{until_src}` (y={until_row})",
        );
    }
}

/// #1059 / #1060 (`iter_on_mut_ref_1059`): where each text sits. A `for`
/// loop over `v.iter()` with v a `&mut Vec`, or over `self.items.iter_mut()`
/// / `self.items.iter()` with `self: &mut Self`, keeps the borrow until the
/// loop's `}`, not just the `for` line; `*e += 1` is drawn on self's row.
#[test]
fn loop_over_a_mut_ref_keeps_it_borrowed_until_the_loop_ends() {
    let rv = run_with_local_backend("iter_on_mut_ref_1059");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    // Fixture order: bump's loop `}` is the second `}` (after the struct's),
    // total's the fourth, read_only's the seventh, through_local_ref's the
    // ninth.
    let rows = [
        ("self", code_row_y(&code, "for e in self.items.iter_mut() {"),
            "self.items is mutably borrowed by the `for` loop's iterator; self.items can't be used until the loop ends"),
        ("self", code_row_y(&code, "*e += 1;"), "the resource self points to is modified through e"),
        ("self", closes[1], "the `for` loop's iterator no longer borrows self.items"),
        ("self", code_row_y(&code, "for x in self.items.iter() {"),
            "self.items is immutably borrowed by the `for` loop's iterator until the loop ends"),
        ("self", closes[3], "the `for` loop's iterator no longer borrows self.items"),
        ("v", code_row_y(&code, "for x in v.iter() {"),
            "the resource v points to is immutably borrowed by the `for` loop's iterator through v until the loop ends"),
        ("v", closes[6], "the `for` loop's iterator no longer borrows the resource v points to"),
        ("r", code_row_y(&code, "for x in r.iter() {"),
            "the resource r points to is immutably borrowed by the `for` loop's iterator through r until the loop ends"),
        ("r", closes[8], "the `for` loop's iterator no longer borrows the resource r points to"),
    ];
    for (column, y, text) in rows {
        let at = (label_x(&tl, column), y);
        let dots = dots_where(&tl, |lines| lines.iter().any(|l| l == text));
        assert!(dots.contains(&at), "expected {:?} on {}'s column at {:?}, found {:?}", text, column, at, dots);
    }
    // The `for` lines no longer end the borrow.
    for (column, src, end) in [
        ("self", "for e in self.items.iter_mut() {", "self.items's resource is no longer mutably borrowed"),
        ("self", "for x in self.items.iter() {", "self.items's resource is no longer immutably borrowed"),
        ("v", "for x in v.iter() {", "iter no longer borrows the resource v points to"),
        ("r", "for x in r.iter() {", "iter no longer borrows the resource r points to"),
    ] {
        let at = (label_x(&tl, column), code_row_y(&code, src));
        let ends_there = dots_where(&tl, |lines| lines.iter().any(|l| l == end));
        assert!(!ends_there.contains(&at), "{:?} still on the `for` line `{}`: {:?}", end, src, ends_there);
    }
}

/// #1066 / #1067 (`adapter_loops_on_mut_1066`): where each text sits. A
/// `for` loop over `a.iter_mut().zip(b.iter())` keeps b (a `&mut`, or
/// `self.b` through `&mut self`) borrowed until the loop's `}`, not just
/// the `for` line; writes through a destructured element (`(i, e)` of
/// `.enumerate()`, `(x, y)` of `.zip(..)`) are drawn on the column they
/// write into.
#[test]
fn adapter_loops_over_a_mut_ref_keep_it_borrowed_and_draw_writes() {
    let rv = run_with_local_backend("adapter_loops_on_mut_1066");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    let add_writes = code_rows_y(&code, "*x += *y;");
    let enum_writes = code_rows_y(&code, "*e += i as i32;");
    // Fixture order: Two::add's loop `}` is the second `}` (after the
    // struct's), add's the seventh, both's the ninth.
    let rows = [
        ("self", code_row_y(&code, "for (x, y) in self.a.iter_mut().zip(self.b.iter()) {"),
            "self.b is immutably borrowed by the `for` loop's iterator until the loop ends"),
        ("self", add_writes[0], "the resource self points to is modified through x"),
        ("self", closes[1], "the `for` loop's iterator no longer borrows self.b"),
        ("self", closes[1], "the `for` loop's iterator no longer borrows self.a"),
        ("self", enum_writes[0], "the resource self points to is modified through e"),
        ("b", code_row_y(&code, "for (x, y) in a.iter_mut().zip(b.iter()) {"),
            "the resource b points to is immutably borrowed by the `for` loop's iterator through b until the loop ends"),
        ("a", add_writes[1], "the resource a points to is modified through x"),
        ("b", closes[6], "the `for` loop's iterator no longer borrows the resource b points to"),
        ("b", code_row_y(&code, "for (x, y) in a.iter_mut().zip(b.iter_mut()) {"),
            "the resource b points to is mutably borrowed by the `for` loop's iterator through b; b can't be used until the loop ends"),
        ("a", code_row_y(&code, "*x += 1;"), "the resource a points to is modified through x"),
        ("b", code_row_y(&code, "*y += 2;"), "the resource b points to is modified through y"),
        ("b", closes[8], "the `for` loop's iterator no longer borrows the resource b points to"),
        ("v", enum_writes[1], "the resource v points to is modified through e"),
    ];
    for (column, y, text) in rows {
        let at = (label_x(&tl, column), y);
        let dots = dots_where(&tl, |lines| lines.iter().any(|l| l == text));
        assert!(dots.contains(&at), "expected {:?} on {}'s column at {:?}, found {:?}", text, column, at, dots);
    }
    // The `for` lines no longer end b's borrow.
    for (src, end) in [
        ("for (x, y) in self.a.iter_mut().zip(self.b.iter()) {", "self.b's resource is no longer immutably borrowed"),
        ("for (x, y) in a.iter_mut().zip(b.iter()) {", "iter no longer borrows the resource b points to"),
        ("for (x, y) in a.iter_mut().zip(b.iter_mut()) {", "iter_mut no longer borrows the resource b points to"),
    ] {
        let column = if src.contains("self") { "self" } else { "b" };
        let at = (label_x(&tl, column), code_row_y(&code, src));
        let ends_there = dots_where(&tl, |lines| lines.iter().any(|l| l == end));
        assert!(!ends_there.contains(&at), "{:?} still on the `for` line `{}`: {:?}", end, src, ends_there);
    }
}

/// #603: `r = &s` in a let-chain part (or a match guard) before a part
/// that fails. Each borrow ends where rustc ends it on each path, checked
/// with conflicting uses (E0502 before the row, accepted after it):
/// * the path into the body: t's loan ends at the write (the condition's
///   row), s's at r's last use in the body;
/// * the else branch / each later arm: r points to s or to t, so both
///   are borrowed from where it starts to r's last use there;
/// * r read after the conditional: both stay borrowed to that read.
#[test]
fn chain_reference_borrows_end_on_each_path() {
    let on = |dots: &[(f64, f64)], row: f64| dots.iter().filter(|d| (d.1 - row).abs() < 1.0).count();
    let s_end = "r's borrow ends here, so s's resource is no longer immutably borrowed (the borrow checker counted it as borrowed whether or not the condition had assigned &s to r)";
    let t_end = "r's borrow ends here, so t's resource is no longer immutably borrowed (the borrow checker counted it as borrowed whether or not the condition had assigned &s to r)";

    let rv = run_with_local_backend("edition2024/chain_assigns_ref_603");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let cond = code_row_y(&code, "if let Some(_n) = y && { r = &s; r.len() > 3 } {");
    let body = code_row_y(&code, "println!(\"long {}\", r);");
    let els = code_row_y(&code, "println!(\"short {}\", r);");
    let t_back = dots_listing_tooltip(&timeline, "t's resource is no longer immutably borrowed");
    let s_back = dots_listing_tooltip(&timeline, "s's resource is no longer immutably borrowed");
    assert_eq!((t_back.len(), on(&t_back, cond)), (1, 1), "t's loan on the body's path ends at the write: {t_back:?} (row {cond})");
    assert_eq!((s_back.len(), on(&s_back, body)), (1, 1), "s's loan on the body's path ends at its println!: {s_back:?} (row {body})");
    for end in [s_end, t_end] {
        let dots = dots_listing_tooltip(&timeline, end);
        assert_eq!((dots.len(), on(&dots, els)), (1, 1), "{end}: {dots:?}, not on the else branch's println! row ({els})");
    }

    let rv = run_with_local_backend("edition2024/chain_assigns_ref_after_603");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let cond = code_row_y(&code, "if let Some(_n) = y && { r = &s; r.len() > 3 } {");
    let read = code_row_y(&code, "println!(\"{}\", r);");
    let t_back = dots_listing_tooltip(&timeline, "t's resource is no longer immutably borrowed");
    assert_eq!((t_back.len(), on(&t_back, cond)), (1, 1), "t's loan on the body's path ends at the write: {t_back:?} (row {cond})");
    let s_back = dots_listing_tooltip(&timeline, "s's resource is no longer immutably borrowed");
    assert_eq!((s_back.len(), on(&s_back, read)), (1, 1), "s stays borrowed to the read after the if: {s_back:?} (row {read})");
    let dots = dots_listing_tooltip(&timeline, t_end);
    assert_eq!((dots.len(), on(&dots, read)), (1, 1), "t stays borrowed to the read after the if: {dots:?} (row {read})");

    let rv = run_with_local_backend("match_guard_assigns_ref_603");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let guard = code_row_y(&code, "Some(_) if { r = &s; r.len() > 3 } => {");
    let body = code_row_y(&code, "println!(\"long {}\", r);");
    let later = [code_row_y(&code, "println!(\"short {}\", r);"), code_row_y(&code, "println!(\"none {}\", r);")];
    let t_back = dots_listing_tooltip(&timeline, "t's resource is no longer immutably borrowed");
    let s_back = dots_listing_tooltip(&timeline, "s's resource is no longer immutably borrowed");
    assert_eq!((t_back.len(), on(&t_back, guard)), (1, 1), "t's loan in the guarded arm ends at the write: {t_back:?} (row {guard})");
    assert_eq!((s_back.len(), on(&s_back, body)), (1, 1), "s's loan in the guarded arm ends at its println!: {s_back:?} (row {body})");
    for who in ["s", "t"] {
        let end = format!("r's borrow ends here, so {who}'s resource is no longer immutably borrowed (the borrow checker counted it as borrowed whether or not the guard on line 7 had assigned &s to r)");
        let dots = dots_listing_tooltip(&timeline, &end);
        assert_eq!(dots.len(), 2, "{end}: {dots:?}");
        for row in later {
            assert_eq!(on(&dots, row), 1, "{end}: {dots:?}, none on the later arm's println! row ({row})");
        }
    }
}

/// #1097 / #1095: when a holder gets a new value whose borrow it now
/// holds, its dot says the old borrow ends and the old value is
/// dropped before the new borrow. #1098 listed s2.items's new borrow
/// of g first, so "s2.items's immutable borrow ends" read as the end of
/// that borrow; o and arr drew no new borrow at all.
#[test]
fn a_holder_overwrite_ends_the_old_borrow_before_the_new_one() {
    let rv = run_with_local_backend("holder_borrows_1094");
    let dots = tooltip_lines(&rv.timeline_panel_string());
    let cases: [&[&str]; 3] = [
        &[
            "s2.items's immutable borrow ends",
            "s2.items acquires ownership of a new resource; its previous resource is dropped",
            "s2.items holds a value that immutably borrows g's resource (s2.items isn't a reference itself)",
        ],
        &[
            "o acquires ownership of a new resource; its previous resource is dropped",
            "o holds a value that immutably borrows a's resource (o isn't a reference itself)",
        ],
        &[
            "arr is assigned a new value",
            "arr holds a value that immutably borrows c's resource (arr isn't a reference itself)",
        ],
    ];
    let failures: Vec<String> = cases.iter()
        .filter(|want| !dots.iter().any(|d| d.iter().map(String::as_str).eq(want.iter().copied())))
        .map(|want| format!("no dot lists exactly {want:?}"))
        .collect();
    assert!(failures.is_empty(), "{}\ndots: {dots:#?}", failures.join("\n"));
}

/// #1076 (`ref_into_adapter_1076`): where each text sits. A reference
/// passed as it is to an adapter in a `for` head (`.zip(b)`, `.chain(b)`)
/// stays borrowed by the loop's iterator until the loop's `}`: a `&T` is
/// copied in, a `&mut` moved in, and writes through y are drawn on the
/// column of what it writes into. A moved `&mut`'s column ends at the
/// move (#1365): the write and the loan's end aren't drawn on it, and its
/// lender, when it has a column, is borrowed by the iterator until then.
#[test]
fn ref_passed_into_an_adapter_stays_borrowed_until_the_loop_ends() {
    let rv = run_with_local_backend("ref_into_adapter_1076");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    let zips = code_rows_y(&code, "for (x, y) in a.iter_mut().zip(b) {");
    let writes = code_rows_y(&code, "*y += *x;");
    let chain = code_row_y(&code, "for x in a.iter().chain(b) {");
    let main_for = code_row_y(&code, "for (x, y) in p.iter().zip(r) {");
    // Fixture order: each function's loop `}` comes just before its own:
    // shared's is the first, moved's the third, chained's the fifth,
    // main's the seventh.
    let kept = "the resource b points to is immutably borrowed by the `for` loop's iterator, through a copy of b, until the loop ends";
    let rows = [
        ("b", zips[0], kept),
        ("b", closes[0], "the `for` loop's iterator no longer borrows the resource b points to"),
        ("b", zips[1], "b's mutable reference is moved (not the resource it points to)"),
        ("b", chain, kept),
        ("b", closes[4], "the `for` loop's iterator no longer borrows the resource b points to"),
        ("q", writes[1], "q's resource is modified through y"),
        ("q", closes[6], "q's resource is no longer mutably borrowed"),
    ];
    for (column, y, text) in rows {
        let at = (label_x(&tl, column), y);
        let dots = dots_where(&tl, |lines| lines.iter().any(|l| l == text));
        assert!(dots.contains(&at), "expected {:?} on {}'s column at {:?}, found {:?}", text, column, at, dots);
    }
    // The `for` lines no longer end the borrow.
    for (column, y, end) in [
        ("b", zips[0], "zip no longer borrows the resource b points to"),
        ("b", zips[0], "b's immutable borrow ends"),
        ("b", zips[1], "b's mutable borrow ends"),
        ("b", chain, "chain no longer borrows the resource b points to"),
        ("r", main_for, "r's mutable borrow ends"),
        ("q", main_for, "q's resource is no longer mutably borrowed"),
    ] {
        let at = (label_x(&tl, column), y);
        let ends_there = dots_where(&tl, |lines| lines.iter().any(|l| l == end));
        assert!(!ends_there.contains(&at), "{:?} still on {}'s `for` line: {:?}", end, column, ends_there);
    }
    // Nor anything on a moved `&mut`'s column after the move (#1365).
    for (column, y, after_move) in [
        ("b", writes[0], "the resource b points to is modified through y"),
        ("b", closes[2], "b's mutable borrow ends"),
        ("r", closes[6], "r's mutable borrow ends"),
    ] {
        let at = (label_x(&tl, column), y);
        let there = dots_where(&tl, |lines| lines.iter().any(|l| l == after_move));
        assert!(!there.contains(&at), "{:?} on {}'s column after it was moved: {:?}", after_move, column, there);
    }
}

/// #1081 (`shared_iter_loop_1081`): where each text sits. A `for` loop
/// over `v.iter()` with `v: &Vec<_>` (also `list: &[T]`, `.zip(w.iter())`,
/// `let r = &p;`, `self.items.iter()` through `&self`) keeps reading
/// through what `iter()` returned until the loop's `}`.
#[test]
fn shared_ref_iter_loop_keeps_its_borrow_until_the_loop_ends() {
    let rv = run_with_local_backend("shared_iter_loop_1081");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    let kept = |n: &str, what: &str| format!("the {what} {n} points to is immutably borrowed by the `for` loop's iterator, through a copy of {n}, until the loop ends");
    let ends = |n: &str, what: &str| format!("the `for` loop's iterator no longer borrows the {what} {n} points to");
    let show_for = code_row_y(&code, "for it in self.items.iter() {");
    let total_for = code_row_y(&code, "for e in v.iter() {");
    let pairs_for = code_row_y(&code, "for (x, y) in a.iter().zip(w.iter()) {");
    let largest_for = code_row_y(&code, "for &item in list.iter() {");
    let main_for = code_row_y(&code, "for n in r.iter() {");
    let collect_for = code_row_y(&code, "for k in q.iter().map(|k| k * 2).collect::<Vec<i32>>() {");
    // Each loop's `}` (the struct's is the first): show's is the second,
    // total's the fifth, pairs' the seventh, largest's the tenth, main's
    // the twelfth.
    let rows = [
        ("self", show_for, "self.items is immutably borrowed by the `for` loop's iterator until the loop ends".to_owned()),
        ("self", closes[1], "the `for` loop's iterator no longer borrows self.items".to_owned()),
        ("v", total_for, kept("v", "resource")),
        ("v", closes[4], ends("v", "resource")),
        ("a", pairs_for, kept("a", "resource")),
        ("a", closes[6], ends("a", "resource")),
        ("w", pairs_for, kept("w", "resource")),
        ("w", closes[6], ends("w", "resource")),
        ("list", largest_for, kept("list", "value")),
        ("list", closes[9], ends("list", "value")),
        ("r", main_for, kept("r", "resource")),
        ("r", closes[11], ends("r", "resource")),
        ("p", closes[11], "p's resource is no longer immutably borrowed".to_owned()),
    ];
    for (column, y, text) in rows {
        let at = (label_x(&tl, column), y);
        let dots = dots_where(&tl, |lines| lines.iter().any(|l| *l == text));
        assert!(dots.contains(&at), "expected {:?} on {}'s column at {:?}, found {:?}", text, column, at, dots);
    }
    // The `for` lines no longer end the borrow; a head that collects
    // into a new Vec keeps none.
    for (column, y, end) in [
        ("v", total_for, "iter no longer borrows the resource v points to"),
        ("v", total_for, "v's immutable borrow ends"),
        ("w", pairs_for, "iter no longer borrows the resource w points to"),
        ("list", largest_for, "list's immutable borrow ends"),
        ("r", main_for, "iter no longer borrows the resource r points to"),
        ("p", main_for, "p's resource is no longer immutably borrowed"),
        ("q", collect_for, "the resource q points to is immutably borrowed by the `for` loop's iterator through q until the loop ends"),
    ] {
        let at = (label_x(&tl, column), y);
        let there = dots_where(&tl, |lines| lines.iter().any(|l| l == end));
        assert!(!there.contains(&at), "{:?} still on {}'s `for` line: {:?}", end, column, there);
    }
}

/// #1082 (`chain_writes_1082`): a write through x from a `chain` is drawn
/// on each column x may point into, on the write's line; with
/// `std::iter::zip(c.iter_mut(), d.iter_mut())` one through y on d's. Not
/// on f's, moved into the loop's iterator by `chain(f)`: its column ended
/// at the move (#1365); x's own dot says the old value is dropped.
#[test]
fn chain_writes_are_drawn_on_each_column_x_may_point_into() {
    let rv = run_with_local_backend("chain_writes_1082");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let incr = code_row_y(&code, "*x += 1;");
    let zipped = code_row_y(&code, "*y += *x;");
    let assign = code_row_y(&code, "*x = String::new();");
    let double = code_row_y(&code, "*x *= 2;");
    let either = |n: &str| format!("the resource {n} points to is modified through x when x points into it (x points into the resource a or b points to)");
    let assigned = |n: &str| format!("*x acquires ownership of a new resource; its previous resource is dropped, when x points into the resource {n} points to (x points into the resource e or f points to)");
    let rows = [
        ("a", incr, either("a")),
        ("b", incr, either("b")),
        ("d", zipped, "the resource d points to is modified through y".to_owned()),
        ("e", assign, assigned("e")),
        ("p", double, "p's resource is modified through x when x points into it (x points into p's resource or q's value)".to_owned()),
        ("q", double, "q's value is modified through x when x points into it (x points into p's resource or q's value)".to_owned()),
    ];
    for (column, y, text) in rows {
        let at = (label_x(&tl, column), y);
        let dots = dots_where(&tl, |lines| lines.iter().any(|l| *l == text));
        assert!(dots.contains(&at), "expected {:?} on {}'s column at {:?}, found {:?}", text, column, at, dots);
    }
    // Nothing claims x always points into a, and `*y += *x` writes nothing
    // through x.
    for (column, y, wrong) in [
        ("a", incr, "the resource a points to is modified through x"),
        ("c", zipped, "the resource c points to is modified through x"),
        ("f", assign, &assigned("f")),
    ] {
        let at = (label_x(&tl, column), y);
        let there = dots_where(&tl, |lines| lines.iter().any(|l| l == wrong));
        assert!(!there.contains(&at), "{:?} on {}'s column: {:?}", wrong, column, there);
    }
    // x's own dot says the old value is dropped, wherever x points.
    let x_drop = dots_where(&tl, |lines| lines.iter().any(|l| l == "*x acquires ownership of a new resource; its previous resource is dropped"));
    assert!(x_drop.iter().any(|&(_, y)| y == assign), "no dot on the `*x = String::new();` row says the old value is dropped: {:?}", x_drop);
}

/// #1068: a let-chain part (or a match guard) that assigns a reference
/// that isn't `&x` of a variable, or whose old or new reference has
/// several lenders, before a part that fails. Each borrow ends where
/// rustc ends it on each path, checked with conflicting uses (E0502
/// before the row, accepted after it).
#[test]
fn chain_call_reference_borrows_end_on_each_path() {
    let on = |dots: &[(f64, f64)], row: f64| dots.iter().filter(|d| (d.1 - row).abs() < 1.0).count();
    let rv = run_with_local_backend("edition2024/chain_assigns_call_ref_1068");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let cond = code_row_y(&code, "if let Some(_n) = y && { r = first(&v); r.len() > 3 } {");
    let body = code_row_y(&code, "println!(\"long {}\", r);");
    let els = code_row_y(&code, "println!(\"short {}\", r);");
    // The path into the body: t's loan ends at the write, v's at the
    // body's println!.
    let t_back = dots_listing_tooltip(&timeline, "t's resource is no longer immutably borrowed");
    let v_back = dots_listing_tooltip(&timeline, "v's resource is no longer immutably borrowed");
    assert_eq!((t_back.len(), on(&t_back, cond)), (1, 1), "t's loan on the body's path ends at the write: {t_back:?} (row {cond})");
    assert_eq!((v_back.len(), on(&v_back, body)), (1, 1), "v's loan on the body's path ends at its println!: {v_back:?} (row {body})");
    // The else branch: both to its println!.
    for who in ["v", "t"] {
        let end = format!("r's borrow ends here, so {who}'s resource is no longer immutably borrowed (the borrow checker counted it as borrowed whether or not the condition had assigned first(&v) to r)");
        let dots = dots_listing_tooltip(&timeline, &end);
        assert_eq!((dots.len(), on(&dots, els)), (1, 1), "{end}: {dots:?}, not on the else branch's println! row ({els})");
    }

    // A new reference tied to two arguments, read after the `if`: both
    // lenders, and the old one, stay borrowed to that read.
    let rv = run_with_local_backend("edition2024/chain_assigns_ref_lenders_1068");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let cond = code_row_y(&code, "if let Some(_n) = y && { q = longest(&c, &d); q.len() > 3 } {");
    let read = code_row_y(&code, "println!(\"{}\", q);");
    let t_back = dots_listing_tooltip(&timeline, "t's resource is no longer immutably borrowed");
    assert_eq!((t_back.len(), on(&t_back, cond)), (1, 1), "t's loan on the body's path ends at the write: {t_back:?} (row {cond})");
    for who in ["c", "d"] {
        let dots = dots_listing_tooltip(&timeline, &format!("{who}'s resource is no longer immutably borrowed"));
        assert_eq!((dots.len(), on(&dots, read)), (1, 1), "{who} stays borrowed to the read after the if: {dots:?} (row {read})");
    }
    // (Its row has a second line for the read's return arrows.)
    let end = "q's borrow ends here, so t's resource is no longer immutably borrowed (the borrow checker counted it as borrowed whether or not the condition had assigned longest(&c, &d) to q)";
    let dots = dots_listing_tooltip(&timeline, end);
    assert!(dots.len() == 1 && dots[0].1 > read - 1.0 && dots[0].1 < read + 31.0, "t stays borrowed to the read after the if: {dots:?} (row {read})");
}

/// #1069: a `let r;` reference given a loan in each arm of an `if` /
/// `match` and read after it. Each arm's lender stays borrowed to that
/// read (rustc: a conflicting use of any of them between the conditional
/// and the read is E0502 / E0499, after it compiles), so each one's borrow
/// ends on the read's row, not just the last arm's.
#[test]
fn let_reference_assigned_in_arms_gives_back_every_lender() {
    let on = |dots: &[(f64, f64)], row: f64| dots.iter().filter(|d| (d.1 - row).abs() < 1.0).count();
    let rv = run_with_local_backend("let_ref_arms_1069");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let reads = code_rows_y(&code, "println!(\"{}\", r);");
    assert_eq!(reads.len(), 4, "{reads:?}");
    let (read, last) = (reads[0], reads[1]);
    let push = code_row_y(&code, "m.push('x');");
    for (end, row) in [
        ("t's resource is no longer immutably borrowed", read),
        ("b's resource is no longer mutably borrowed", push),
        ("a's resource is no longer mutably borrowed", push),
    ] {
        let dots = dots_listing_tooltip(&timeline, end);
        assert_eq!((dots.len(), on(&dots, row)), (1, 1), "{end}: {dots:?}, not on row {row}");
    }
    // (s's text is also a bullet of each `s.len()` row.)
    let dots = dots_listing_tooltip(&timeline, "s's resource is no longer immutably borrowed");
    assert_eq!(on(&dots, read), 1, "s: {dots:?}, not on row {read}");
    for who in ["x", "y", "z"] {
        let end = format!("{who}'s resource is no longer immutably borrowed");
        let dots = dots_listing_tooltip(&timeline, &end);
        assert_eq!((dots.len(), on(&dots, last)), (1, 1), "{end}: {dots:?}, not on the match's read row ({last})");
    }
    // Read in each arm and not after: each borrow ends in its own arm.
    for (who, row) in [("p", reads[2]), ("q", reads[3])] {
        let end = format!("{who}'s resource is no longer immutably borrowed");
        let dots = dots_listing_tooltip(&timeline, &end);
        assert_eq!((dots.len(), on(&dots, row)), (1, 1), "{end}: {dots:?}, not on its arm's read row ({row})");
    }
}

/// #1073 (`field_borrow_through_ref_1073`): while only a field of what a
/// `&mut` reference points to is borrowed, the reference's own line is
/// drawn, in the style it has before the borrow, with a text naming the
/// field; the restriction isn't shown on all of it. (Main drew no line
/// there, and after the write to `self.n` none for the rest of the
/// function.) `s` in `bump_local`, whose `s.items` is lent the same way,
/// keeps its line too.
#[test]
fn a_field_borrow_through_a_reference_keeps_its_line() {
    let rv = run_with_local_backend("field_borrow_through_ref_1073");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    let label_xs = |label: &str| -> Vec<f64> {
        tl.split("<text ").skip(1).filter_map(|t| {
            let (tag, rest) = t.split_once('>')?;
            (tag.contains("class=\"label") && rest.split('<').next() == Some(label)).then(|| num_attr(tag, "x"))
        }).collect()
    };
    let selfs = label_xs("self");
    assert_eq!(selfs.len(), 5, "self columns: {:?}", selfs);
    // The column's state lines (a hollow strip's two rails, or one solid
    // line) as (top, bottom, class).
    let column = |x: f64| -> Vec<(f64, f64, String)> {
        start_tags(&tl, "line").into_iter()
            .filter(|t| attr(t, "class").is_some_and(|c| c.starts_with("hollow") || c.starts_with("solid") || c == "lent"))
            .filter(|t| (num_attr(t, "x1") - x).abs() <= 2.0 && num_attr(t, "x1") == num_attr(t, "x2"))
            .map(|t| {
                let (a, b) = (num_attr(t, "y1"), num_attr(t, "y2"));
                (a.min(b), a.max(b), attr(t, "class").unwrap_or_default().to_string())
            })
            .collect()
    };
    // Fixture order: bump's loop `}` is the second `}` (after the
    // struct's), total's the fourth, bump_ref's the eleventh, bump_local's
    // the thirteenth.
    let spans = [
        (selfs[0], code_row_y(&code, "for e in self.items.iter_mut() {"), closes[1],
            "self holds a mutable reference, but self.items is mutably borrowed by the `for` loop's iterator, so self.items can't be used until the loop ends"),
        (selfs[1], code_row_y(&code, "for x in self.items.iter() {"), closes[3],
            "self holds a mutable reference, but self.items is immutably borrowed by the `for` loop's iterator until the loop ends"),
        (selfs[2], code_row_y(&code, "let first = self.items.first_mut().unwrap();"), code_row_y(&code, "*first += 1;"),
            "self holds a mutable reference, but self.items is mutably borrowed by first, so self.items can't be used while the borrow is live"),
        (selfs[3], code_row_y(&code, "if let Some(x) = self.items.last_mut() {"), code_row_y(&code, "*x += 1;"),
            "self holds a mutable reference, but self.items is mutably borrowed by x, so self.items can't be used while the borrow is live"),
        (selfs[4], code_row_y(&code, "let m = self.items.iter().max().unwrap();"), code_row_y(&code, "*m"),
            "self holds a mutable reference, but self.items is immutably borrowed by m while the borrow is live"),
        (label_x(&tl, "r"), code_row_y(&code, "for e in r.items.iter_mut() {"), closes[10],
            "r holds a mutable reference, but r.items is mutably borrowed by the `for` loop's iterator, so r.items can't be used until the loop ends"),
    ];
    for (x, from, to, text) in spans {
        let lines = column(x);
        // The style the column has on the row above the borrow.
        let before = lines.iter().find(|(a, b, _)| *a < from && *b >= from)
            .unwrap_or_else(|| panic!("no line above row {} on column x={}: {:?}", from, x, lines)).2.clone();
        let mut reached = from;
        let mut spans: Vec<&(f64, f64, String)> = lines.iter().filter(|(a, b, _)| *b > from && *a < to).collect();
        spans.sort_by(|p, q| p.0.partial_cmp(&q.0).unwrap());
        for (a, b, class) in spans {
            assert_eq!(*class, before, "column x={} changes style from {:?} to {:?} at y={} while only a field is borrowed", x, before, class, a);
            if *a <= reached {
                reached = reached.max(*b);
            }
        }
        assert!(reached >= to, "column x={} isn't drawn from y={} to y={} (reaches {}): {:?}", x, from, to, reached, lines);
        let texts = state_lines_with_tooltip(&tl, text);
        assert!(texts.iter().any(|&(a, b)| a <= from && b >= to), "no line {:?} from y={} to y={}: {:?}", text, from, to, texts);
    }
    // The call that lends the field to `first` / `x` / `m` doesn't give it
    // back (main said it did).
    for (x, src, back_text) in [
        (selfs[2], "let first = self.items.first_mut().unwrap();", "self.items's resource is no longer mutably borrowed"),
        (selfs[3], "if let Some(x) = self.items.last_mut() {", "self.items's resource is no longer mutably borrowed"),
        (selfs[4], "let m = self.items.iter().max().unwrap();", "self.items's resource is no longer immutably borrowed"),
    ] {
        let at = (x, code_row_y(&code, src));
        let back = dots_where(&tl, |lines| lines.iter().any(|l| l == back_text));
        assert!(!back.contains(&at), "{:?} on `{}`: {:?}", back_text, src, back);
    }
    // The local owner keeps a dotted line across the loop. Borrowing
    // all of s in the body is E0502, even though writing s.n compiles.
    let (from, to) = (code_row_y(&code, "for e in s.items.iter_mut() {"), closes[12]);
    let mut reached = from;
    let mut owner = column(label_x(&tl, "s"));
    owner.sort_by(|a, b| a.0.total_cmp(&b.0));
    for (top, bottom, class) in owner {
        if class == "lent" && top <= reached {
            reached = reached.max(bottom);
        }
    }
    assert!(reached >= to, "s's mutable part loan stops at {reached}, before the loop ends at {to}");
}

/// #1080 (`two_field_borrow_through_ref_1080`): while a value or reference
/// borrows several fields of what a `&mut` reference points to (or a value
/// holds one field: `let it = self.items.iter();`), the reference keeps its
/// line, in the style it had just before, with the text naming the fields;
/// main lent all of self ("…currently shared through it, so self can only
/// read it") and the line was gone after `self.n += 1`, which compiles
/// (using `self.items` / `self.other` while the borrow is live doesn't).
/// The call lines don't give the fields back.
#[test]
fn a_borrow_of_several_fields_through_a_reference_keeps_its_line() {
    let rv = run_with_local_backend("two_field_borrow_through_ref_1080");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    // The `}` closing the block that `row` is the last line of.
    let close_after = |row: f64| *closes.iter().find(|&&y| y > row).unwrap_or_else(|| panic!("no `}}` after y={}", row));
    let label_xs = |label: &str| -> Vec<f64> {
        tl.split("<text ").skip(1).filter_map(|t| {
            let (tag, rest) = t.split_once('>')?;
            (tag.contains("class=\"label") && rest.split('<').next() == Some(label)).then(|| num_attr(tag, "x"))
        }).collect()
    };
    let selfs = label_xs("self");
    assert_eq!(selfs.len(), 6, "self columns: {:?}", selfs);
    let r = label_x(&tl, "r");
    let column = |x: f64| -> Vec<(f64, f64, String)> {
        start_tags(&tl, "line").into_iter()
            .filter(|t| attr(t, "class").is_some_and(|c| c.starts_with("hollow") || c.starts_with("solid")))
            .filter(|t| (num_attr(t, "x1") - x).abs() <= 2.0 && num_attr(t, "x1") == num_attr(t, "x2"))
            .map(|t| {
                let (a, b) = (num_attr(t, "y1"), num_attr(t, "y2"));
                (a.min(b), a.max(b), attr(t, "class").unwrap_or_default().to_string())
            })
            .collect()
    };
    let counts = code_rows_y(&code, "it.count()");
    let row = |src: &str| code_row_y(&code, src);
    let both = "let it = self.items.iter().chain(self.other.iter());";
    let longer = "let l = pick(&self.items, &self.other);";
    let skip = "let it = self.items.iter().skip(self.n).take(self.other.len());";
    let looped = "for (a, b) in self.items.iter().zip(self.other.iter_mut()) {";
    let peek = "if let Some(x) = first_of(&mut self.items, &mut self.other) {";
    let pairs = "let pairs = r.other.iter_mut().zip(r.items.iter());";
    let spans = [
        (selfs[0], row(both), counts[0],
            "self holds a mutable reference, but self.items and self.other are immutably borrowed by it while the borrow is live"),
        (selfs[1], row("let it = self.items.iter();"), counts[1],
            "self holds a mutable reference, but self.items is immutably borrowed by it while the borrow is live"),
        (selfs[2], row(longer), row("l.len()"),
            "self holds a mutable reference, but self.items and self.other are immutably borrowed by l while the borrow is live"),
        (selfs[3], row(skip), row("it.sum()"),
            "self holds a mutable reference, but self.items is immutably borrowed by it while the borrow is live"),
        (selfs[4], row(looped), close_after(row("*b += *a;")),
            "self holds a mutable reference, but self.other is mutably borrowed and self.items immutably borrowed by the `for` loop's iterator until the loop ends, so self.other can't be used during that borrow"),
        (selfs[5], row(peek), row("*x += 1;"),
            "self holds a mutable reference, but self.items and self.other are mutably borrowed by x, so they can't be used while the borrow is live"),
        (r, row(pairs), row("for (o, i) in pairs {"),
            "r holds a mutable reference, but r.other is mutably borrowed and r.items immutably borrowed by pairs while the borrow is live, so r.other can't be used during that borrow"),
        (r, row("for (o, i) in pairs {"), close_after(row("*o += *i;")),
            "r holds a mutable reference, but r.other is mutably borrowed and r.items immutably borrowed by the `for` loop's iterator until the loop ends, so r.other can't be used during that borrow"),
    ];
    for (x, from, to, text) in spans {
        let lines = column(x);
        let before = lines.iter().find(|(a, b, _)| *a < from && *b >= from)
            .unwrap_or_else(|| panic!("no line above row {} on column x={}: {:?}", from, x, lines)).2.clone();
        let mut reached = from;
        let mut parts: Vec<&(f64, f64, String)> = lines.iter().filter(|(a, b, _)| *b > from && *a < to).collect();
        parts.sort_by(|p, q| p.0.partial_cmp(&q.0).unwrap());
        for (a, b, class) in parts {
            assert_eq!(*class, before, "column x={} changes style from {:?} to {:?} at y={} while only fields are borrowed", x, before, class, a);
            if *a <= reached {
                reached = reached.max(*b);
            }
        }
        assert!(reached >= to, "column x={} isn't drawn from y={} to y={} (reaches {}): {:?}", x, from, to, reached, lines);
        let texts = state_lines_with_tooltip(&tl, text);
        assert!(texts.iter().any(|&(a, b)| a <= from && b >= to), "no line {:?} from y={} to y={}: {:?}", text, from, to, texts);
    }
    // The line that makes the borrow doesn't give the fields back (main
    // said it did, though the result keeps them). A line's events can
    // take several rows: up to the next statement's.
    let rows_of = |src: &str, next: &str| -> (f64, f64) {
        let at = row(src);
        let to = code_rows_y(&code, next).into_iter().find(|&y| y > at).unwrap_or_else(|| panic!("no {:?} after {:?}", next, src));
        (at, to)
    };
    let given_back = |x: f64, (at, to): (f64, f64), text: &str| -> bool {
        dots_where(&tl, |lines| lines.iter().any(|l| l == text)).iter().any(|&(dx, dy)| (dx - x).abs() < 1.0 && dy >= at && dy < to)
    };
    for (x, src, next, back_text) in [
        (selfs[0], both, "self.n += 1;", "self.items's resource is no longer immutably borrowed"),
        (selfs[0], both, "self.n += 1;", "self.other's resource is no longer immutably borrowed"),
        (selfs[1], "let it = self.items.iter();", "self.n += 1;", "self.items's resource is no longer immutably borrowed"),
        (selfs[2], longer, "self.n += 1;", "self.items's resource is no longer immutably borrowed"),
        (selfs[2], longer, "self.n += 1;", "self.other's resource is no longer immutably borrowed"),
        (selfs[3], skip, "self.n += 1;", "self.items's resource is no longer immutably borrowed"),
        (selfs[4], looped, "*b += *a;", "self.other's resource is no longer mutably borrowed"),
        (selfs[5], peek, "self.n += 1;", "self.items's resource is no longer mutably borrowed"),
        (selfs[5], peek, "self.n += 1;", "self.other's resource is no longer mutably borrowed"),
        (r, pairs, "r.n += 1;", "r.other's resource is no longer mutably borrowed"),
        (r, pairs, "r.n += 1;", "r.items's resource is no longer immutably borrowed"),
    ] {
        assert!(!given_back(x, rows_of(src, next), back_text), "{:?} on `{}`", back_text, src);
    }
    // `self.other.len()` in `skip_n` borrows it only for the call.
    assert!(given_back(selfs[3], rows_of(skip, "self.n += 1;"), "self.other's resource is no longer immutably borrowed"),
        "self.other isn't given back on `{}`", skip);
}

/// #1093 (`closure_field_capture_through_ref_1093`): while a value (or a
/// `for` loop's iterator) holds a closure that captures fields of what a
/// `&mut` reference points to, the reference keeps its line, in the style
/// it had just before, with the text naming the captured fields; #1080's
/// plugin lent all of self ("…currently shared through it, so self can
/// only read it"), though `self.other.push(0)` compiles there. The `let`
/// / `for` lines don't give the captured field back; the loop's end does.
#[test]
fn a_closure_capturing_a_field_through_a_reference_keeps_its_line() {
    let rv = run_with_local_backend("closure_field_capture_through_ref_1093");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let closes = code_rows_y(&code, "}");
    let close_after = |row: f64| *closes.iter().find(|&&y| y > row).unwrap_or_else(|| panic!("no `}}` after y={}", row));
    let label_xs = |label: &str| -> Vec<f64> {
        tl.split("<text ").skip(1).filter_map(|t| {
            let (tag, rest) = t.split_once('>')?;
            (tag.contains("class=\"label") && rest.split('<').next() == Some(label)).then(|| num_attr(tag, "x"))
        }).collect()
    };
    let selfs = label_xs("self");
    assert_eq!(selfs.len(), 4, "self columns: {:?}", selfs);
    let column = |x: f64| -> Vec<(f64, f64, String)> {
        start_tags(&tl, "line").into_iter()
            .filter(|t| attr(t, "class").is_some_and(|c| c.starts_with("hollow") || c.starts_with("solid")))
            .filter(|t| (num_attr(t, "x1") - x).abs() <= 2.0 && num_attr(t, "x1") == num_attr(t, "x2"))
            .map(|t| {
                let (a, b) = (num_attr(t, "y1"), num_attr(t, "y2"));
                (a.min(b), a.max(b), attr(t, "class").unwrap_or_default().to_string())
            })
            .collect()
    };
    let counts = code_rows_y(&code, "it.count()");
    let row = |src: &str| code_row_y(&code, src);
    let read = "let it = self.items.iter().map(|x| *x as usize + self.n);";
    let bump = "let it = self.items.iter().map(|x| {";
    let looped = "for x in self.items.iter().map(|x| *x as usize + self.n) {";
    let count = "let it = (0..3).map(|i| i + self.n);";
    let loop_end = close_after(row("self.other.push(x as i32);"));
    let spans = [
        (selfs[0], row(read), counts[0],
            "self holds a mutable reference, but self.items and self.n are immutably borrowed by it while the borrow is live"),
        (selfs[1], row(bump), counts[1],
            "self holds a mutable reference, but self.n is mutably borrowed and self.items immutably borrowed by it while the borrow is live, so self.n can't be used during that borrow"),
        (selfs[2], row(looped), loop_end,
            "self holds a mutable reference, but self.items and self.n are immutably borrowed by the `for` loop's iterator until the loop ends"),
        (selfs[3], row(count), row("it.sum()"),
            "self holds a mutable reference, but self.n is immutably borrowed by it while the borrow is live"),
    ];
    for (x, from, to, text) in spans {
        let lines = column(x);
        let before = lines.iter().find(|(a, b, _)| *a < from && *b >= from)
            .unwrap_or_else(|| panic!("no line above row {} on column x={}: {:?}", from, x, lines)).2.clone();
        let mut reached = from;
        let mut parts: Vec<&(f64, f64, String)> = lines.iter().filter(|(a, b, _)| *b > from && *a < to).collect();
        parts.sort_by(|p, q| p.0.partial_cmp(&q.0).unwrap());
        for (a, b, class) in parts {
            assert_eq!(*class, before, "column x={} changes style from {:?} to {:?} at y={} while only fields are borrowed", x, before, class, a);
            if *a <= reached {
                reached = reached.max(*b);
            }
        }
        assert!(reached >= to, "column x={} isn't drawn from y={} to y={} (reaches {}): {:?}", x, from, to, reached, lines);
        let texts = state_lines_with_tooltip(&tl, text);
        assert!(texts.iter().any(|&(a, b)| a <= from && b >= to), "no line {:?} from y={} to y={}: {:?}", text, from, to, texts);
    }
    // A dot on column x in rows at..to with a bullet `want` accepts.
    let given_back = |x: f64, at: f64, to: f64, want: &dyn Fn(&str) -> bool| -> bool {
        dots_where(&tl, |lines| lines.iter().any(|l| want(l))).iter().any(|&(dx, dy)| (dx - x).abs() < 1.0 && dy >= at && dy < to)
    };
    let next_row = |at: f64, next: &str| code_rows_y(&code, next).into_iter().find(|&y| y > at).unwrap_or_else(|| panic!("no {:?} after y={}", next, at));
    // The captured field is given back where the borrow ends, not where
    // it starts. self.n is a usize: its value is borrowed (#1100).
    for (x, src, end, back) in [
        (selfs[0], read, counts[0], "self.n's value is no longer immutably borrowed"),
        (selfs[1], bump, counts[1], "self.n's value is no longer mutably borrowed"),
        (selfs[3], count, row("it.sum()"), "self.n's value is no longer immutably borrowed"),
    ] {
        let want = |l: &str| l == back;
        assert!(!given_back(x, row(src), next_row(row(src), "self.other.push(0);"), &want), "self.n given back on `{}`", src);
        assert!(given_back(x, end, next_row(end, "}"), &want), "self.n isn't given back on the row of `{}`'s last use", src);
    }
    let back = |l: &str| l == "the `for` loop's iterator no longer borrows self.n";
    assert!(!given_back(selfs[2], row(looped), loop_end, &back), "self.n given back before the loop ends");
    assert!(given_back(selfs[2], loop_end, next_row(loop_end, "self.n += 1;"), &back), "self.n isn't given back where the loop ends");
}

/// #1101 (`field_value_borrow_find_closure_1100`): `find` is passed a
/// closure capturing `self.n` but doesn't keep it, so while `f` is live
/// only self.items is borrowed (`self.n += 1` compiles there). self's
/// column keeps the style it had just before the `let f` line, with the
/// text naming self.items, until f's last use; #1102's plugin lent all of
/// self there ("…currently shared through it, so self can only read it").
#[test]
fn a_closure_find_does_not_keep_borrows_only_the_receiver_field() {
    let rv = run_with_local_backend("field_value_borrow_find_closure_1100");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let label_xs = |label: &str| -> Vec<f64> {
        tl.split("<text ").skip(1).filter_map(|t| {
            let (tag, rest) = t.split_once('>')?;
            (tag.contains("class=\"label") && rest.split('<').next() == Some(label)).then(|| num_attr(tag, "x"))
        }).collect()
    };
    let selfs = label_xs("self");
    assert_eq!(selfs.len(), 4, "self columns: {:?}", selfs);
    let column = |x: f64| -> Vec<(f64, f64, String)> {
        start_tags(&tl, "line").into_iter()
            .filter(|t| attr(t, "class").is_some_and(|c| c.starts_with("hollow") || c.starts_with("solid")))
            .filter(|t| (num_attr(t, "x1") - x).abs() <= 2.0 && num_attr(t, "x1") == num_attr(t, "x2"))
            .map(|t| {
                let (a, b) = (num_attr(t, "y1"), num_attr(t, "y2"));
                (a.min(b), a.max(b), attr(t, "class").unwrap_or_default().to_string())
            })
            .collect()
    };
    let lets = [code_row_y(&code, "let f = self.items.iter().find(|x| **x as usize == self.n);"), code_row_y(&code, "let f = self.items.iter().find(|x| {")];
    let ends = code_rows_y(&code, "*f.unwrap_or(&0)");
    assert_eq!(ends.len(), 2, "rows: {:?}", ends);
    let text = "self holds a mutable reference, but self.items is immutably borrowed by f while the borrow is live";
    for (x, from, to) in [(selfs[2], lets[0], ends[0]), (selfs[3], lets[1], ends[1])] {
        let lines = column(x);
        let before = lines.iter().find(|(a, b, _)| *a < from && *b >= from)
            .unwrap_or_else(|| panic!("no line above row {} on column x={}: {:?}", from, x, lines)).2.clone();
        for (a, _, class) in lines.iter().filter(|(a, b, _)| *b > from && *a < to) {
            assert_eq!(*class, before, "column x={} changes style from {:?} to {:?} at y={} while only self.items is borrowed", x, before, class, a);
        }
        let texts = state_lines_with_tooltip(&tl, text);
        assert!(texts.iter().any(|&(a, b)| a <= from && b >= to), "no line {:?} from y={} to y={}: {:?}", text, from, to, texts);
    }
}

/// #1104 (`boxed_closure_borrow_1104`): a closure returned as `Box<dyn Fn
/// + 'a>` keeps its captures' borrows in g until g is dropped (it has drop
/// glue). #1105's plugin drew no borrow into g: self's mutable borrow
/// ended on the `self.other.push(0);` row, before `g(&1)` reads self.n,
/// and s's borrow ended on the `println!` row of `local`. With `drop(h)`
/// the borrow ends there, not at the end of the scope (the unwind path out
/// of `h(&1)` still drops h, but no code runs there).
#[test]
fn a_boxed_closure_keeps_its_borrows_until_dropped() {
    let rv = run_with_local_backend("boxed_closure_borrow_1104");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    let next_row = |at: f64, next: &str| code_rows_y(&code, next).into_iter().find(|&y| y > at).unwrap_or_else(|| panic!("no {:?} after y={}", next, at));
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    // kept: self's borrow ends where g is dropped, at the closing brace.
    let kept_end = next_row(row("g(&1)"), "}");
    assert_eq!(ys("self's mutable borrow ends"), vec![kept_end], "self's borrow must end where g is dropped");
    assert_eq!(ys("self.n's value is no longer immutably borrowed"), vec![kept_end]);
    // local: s stays borrowed past `println!` until g is dropped.
    let local_end = next_row(row("let ok = g(&1);"), "}");
    let s_back = ys("s's resource is no longer immutably borrowed");
    assert_eq!(s_back, vec![local_end], "s given back before g is dropped");
    // dropped: t is given back on the `drop(h);` row, before `t.push('c');`.
    assert_eq!(ys("t's resource is no longer immutably borrowed"), vec![row("drop(h);")]);
    assert_eq!(ys("h's immutable borrow ends"), vec![row("drop(h);")]);
    // through_ref: m's borrow of what r points to lasts until m is
    // dropped at the closing brace (#1107).
    let m_end = next_row(row("let hit = m(&1);"), "}");
    assert_eq!(ys("m's immutable borrow ends"), vec![m_end], "m's borrow must last until m is dropped");
}

/// #1107 (`boxed_closure_drop_1107`): a boxed closure that reads through a
/// shared reference (`boxed(|x| r.len() …)`, `Box::new(|| q.len())`) holds
/// a reborrow of `*r`, which rustc records as no loan. A `Box<dyn Fn +
/// '_>` has drop glue that may use it, so rustc keeps the borrow until the
/// box is dropped. #1106's plugin ended it on the row of the last call.
#[test]
fn a_boxed_closure_borrowing_through_a_reference_keeps_it_until_dropped() {
    let rv = run_with_local_backend("boxed_closure_drop_1107");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    let next_row = |at: f64, next: &str| code_rows_y(&code, next).into_iter().find(|&y| y > at).unwrap_or_else(|| panic!("no {:?} after y={}", next, at));
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    // through_ref: m is dropped at the closing brace, after `hit`.
    let m_end = next_row(row("let hit = m(&1);"), "}");
    assert_eq!(ys("m's immutable borrow ends"), vec![m_end], "m's borrow must last until m is dropped");
    assert_eq!(ys("m no longer borrows the resource r points to"), vec![m_end]);
    // through_ref_plain: the same for `Box::new(|| q.len())`.
    let n_end = next_row(row("let len = n();"), "}");
    assert_eq!(ys("n's immutable borrow ends"), vec![n_end], "n's borrow must last until n is dropped");
    assert_eq!(ys("n no longer borrows the resource q points to"), vec![n_end]);
    // through_ref_dropped: `drop(d)` gives it back, before `w.push('g')`.
    assert_eq!(ys("d's immutable borrow ends"), vec![row("drop(d);")]);
    assert_eq!(ys("d no longer borrows the resource p points to"), vec![row("drop(d);")]);
    assert_eq!(ys("w's resource is no longer immutably borrowed"), vec![row("drop(d);")]);
}

/// #853 (`approx_loop_one_pass_853`, `approx_loop_nested_853`): each
/// loop gets one note, on its first dot drawn for a pass (in source
/// order, then leftmost), and there is no other note: not on `total`'s
/// binding before the loops, not on the `for` line where `words` is lent
/// to the iterator once, not on the closing line where it's given back,
/// not on `n`, bound once by the `break`, not in the `if` block, not
/// on the other variables' first dots in a loop, and not in the `loop`
/// that breaks on its first pass (#1467). An outer loop whose
/// dots are all in a loop nested in it (`loop { while let … }`) gets no
/// note: only the `while let`'s is there (the first version also put the
/// `loop`'s on s's dot, on the same row).
#[test]
fn loop_notes_sit_on_each_loops_first_dot() {
    let plain = "(RustViz draws one pass through this loop, which may run many times.)";
    let declares = "(RustViz draws one pass through this loop, which may run many times; the variables declared inside it are new on each pass.)";
    let cases: &[(&str, &[(&str, &[&str])])] = &[
        ("approx_loop_one_pass_853", &[
            // (Not the `loop`: it breaks on its first pass, #1467.)
            (declares, &["for w in words.iter() {", "while let Some(top) = stack.pop() {"]),
        ]),
        ("approx_loop_nested_853", &[
            (plain, &["while total < 100 {", "total += 1;"]),
            (declares, &["for row in grid.iter() {", "for cell in row.iter() {", "while let Some(s) = stack.pop() {"]),
        ]),
    ];
    for (fixture, notes) in cases {
        let rv = run_with_local_backend(fixture);
        let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        let listed: Vec<&str> = notes.iter().map(|(n, _)| *n).collect();
        for line in timeline_tooltips(&tl) {
            if is_approx_note(&line) {
                assert!(listed.contains(&line.as_str()), "{}: unexpected note {:?}", fixture, line);
            }
        }
        for (note, rows) in notes.iter() {
            let mut got: Vec<f64> = dots_listing_tooltip(&tl, note).into_iter().map(|(_, y)| y).collect();
            got.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let mut want: Vec<f64> = rows.iter().map(|r| code_row_y(&code, r)).collect();
            want.sort_by(|a, b| a.partial_cmp(b).unwrap());
            assert_eq!(got, want, "{}: rows of {:?}", fixture, note);
        }
    }
}

/// Approximation notes for constructs RustViz simplifies (#685, #194,
/// #689, #133/#278/#347, #135): each goes on the dot drawn for the
/// construct, on its row, and on no other dot: not on `Borrow::borrow` or
/// `Cell::set` (no run-time borrow), a write through a reference, a
/// method chain (#687: no note), an element write not through a
/// reference, a closure with no captures, or a plain fn's parameter.
#[test]
fn approximation_notes_sit_on_their_constructs() {
    let cases: &[(&str, &[(&str, &[&str])])] = &[
        ("approx_runtime_borrow_685", &[
            ("(RefCell also tracks this borrow at run time, until the RefMut that borrow_mut returns is dropped; RustViz doesn't draw run-time borrows.)", &["*cell.borrow_mut() += 1;"]),
            ("(RefCell also tracks this borrow at run time, until the Ref that borrow returns is dropped; RustViz doesn't draw run-time borrows.)", &["let seen = *cell.borrow();"]),
            ("(The Mutex stays locked until the guard that lock returns is dropped; RustViz doesn't draw the lock.)", &["*m.lock().unwrap() += 1;"]),
            ("(The RwLock stays locked for reading until the guard that read returns is dropped; RustViz doesn't draw the lock.)", &["let r = *l.read().unwrap();"]),
            ("(The RwLock stays locked for writing until the guard that write returns is dropped; RustViz doesn't draw the lock.)", &["*l.write().unwrap() += r;"]),
        ]),
        ("approx_raw_pointer_194", &[
            ("(p is a raw pointer to x; RustViz doesn't draw raw pointers as borrows, so x's column shows nothing here.)", &["let p = &mut x as *mut i32;"]),
            ("(p is a raw pointer; RustViz doesn't show this on what p points to.)", &["*p = 2;"]),
            ("(q is a raw pointer to x; RustViz doesn't draw raw pointers as borrows, so x's column shows nothing here.)", &["let q = &x as *const i32;"]),
            ("(q is a raw pointer; RustViz doesn't show this on what q points to.)", &["let y = unsafe { *q };"]),
        ]),
        ("approx_method_chain_687", &[
            // Method chains get no note; the Ref is RefCell's.
            ("(RefCell also tracks this borrow at run time, until the Ref that borrow returns is dropped; RustViz doesn't draw run-time borrows.)", &["let k = cell.borrow().len();"]),
        ]),
        ("approx_element_ref_689", &[
            ("(RustViz doesn't follow slots[0] to what it points to, so this isn't drawn on the variable it borrows from.)", &["*slots[0] += 10;", "let n = *slots[0];"]),
        ]),
        ("approx_closure_body_133", &[
            ("(RustViz draws f's captures here; the uses in f's body aren't drawn where f is called.)", &["let f = || show(&s);"]),
            ("(RustViz draws g's captures here; the uses in g's body aren't drawn where g is called.)", &["let g = || f();"]),
        ]),
        ("approx_async_135", &[
            ("(get is an async fn; RustViz doesn't draw its body, which runs when the future it returns is awaited.)", &["async fn get(s: String) -> usize {"]),
            ("(get is an async fn; RustViz doesn't draw its body, which runs when fut is awaited.)", &["let fut = get(a);"]),
            ("(RustViz doesn't draw the async block's body, which runs when block is awaited.)", &["let block = async { 1 };"]),
        ]),
    ];
    for (fixture, notes) in cases {
        let rv = run_with_local_backend(fixture);
        let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
        // Every note line of the figure is one of the listed ones.
        let listed: Vec<&str> = notes.iter().map(|(n, _)| *n).collect();
        for line in timeline_tooltips(&tl) {
            if is_approx_note(&line) {
                assert!(listed.contains(&line.as_str()), "{}: unexpected note {:?}", fixture, line);
            }
        }
        for (note, rows) in notes.iter() {
            let mut got: Vec<f64> = dots_listing_tooltip(&tl, note).into_iter().map(|(_, y)| y).collect();
            got.sort_by(|a, b| a.partial_cmp(b).unwrap());
            let mut want: Vec<f64> = rows.iter().map(|r| code_row_y(&code, r)).collect();
            want.sort_by(|a, b| a.partial_cmp(b).unwrap());
            assert_eq!(got, want, "{}: rows of {:?}", fixture, note);
        }
    }
}

/// The horizontal runs `(y, x_lo, x_hi)` of every gray arrow shaft, with
/// the shaft's tooltip. A hop (`A`) over a dot ends one run and starts the
/// next past the dot.
fn arrow_horizontal_runs(svg: &str) -> Vec<(String, f64, f64, f64)> {
    arrow_runs_keyed(svg, |open, _| timeline_tooltips(open).join(" / "))
}

/// `arrow_horizontal_runs`, keyed by each arrow's `data-rv-id`
/// (`f>a@L9:arrow:move`) instead of its tooltip.
fn arrow_horizontal_runs_by_id(svg: &str) -> Vec<(String, f64, f64, f64)> {
    arrow_runs_keyed(svg, |_, group| {
        let at = group.find("data-rv-id=\"").map_or(group.len(), |i| i + "data-rv-id=\"".len());
        group[at..].split('"').next().unwrap_or("").to_string()
    })
}

fn arrow_runs_keyed(svg: &str, key: impl Fn(&str, &str) -> String) -> Vec<(String, f64, f64, f64)> {
    let mut out = Vec::new();
    for (i, _) in svg.match_indices("<g class=\"tooltip-trigger\" data-tooltip-text=\"") {
        let group = &svg[i..i + svg[i..].find("</g>").unwrap_or(svg.len() - i)];
        let open = &group[..group.find('>').unwrap_or(group.len()) + 1];
        let text = key(open, group);
        for t in start_tags(group, "polyline").into_iter().chain(start_tags(group, "path")) {
            if !is_arrow_shaft(t) {
                continue;
            }
            // Points of each unbroken stretch: a polyline's, or a path's
            // M / L points, broken at each hop.
            let mut stretches: Vec<Vec<(f64, f64)>> = vec![Vec::new()];
            if let Some(pts) = attr(t, "points") {
                let v: Vec<f64> = pts.split(|c: char| c == ' ' || c == ',').filter_map(|s| s.parse().ok()).collect();
                stretches[0] = v.chunks(2).filter(|c| c.len() == 2).map(|c| (c[0], c[1])).collect();
            } else if let Some(d) = attr(t, "d") {
                let tok: Vec<&str> = d.split_whitespace().collect();
                let num = |i: usize| tok[i].parse::<f64>().unwrap();
                let mut k = 0;
                while k < tok.len() {
                    match tok[k] {
                        "M" | "L" => { stretches.last_mut().unwrap().push((num(k + 1), num(k + 2))); k += 3; }
                        "A" => { stretches.push(vec![(num(k + 6), num(k + 7))]); k += 8; }
                        other => panic!("unexpected path command {:?} in {}", other, d),
                    }
                }
            }
            for s in stretches {
                for w in s.windows(2) {
                    let ((x1, y1), (x2, y2)) = (w[0], w[1]);
                    if y1 == y2 && x1 != x2 {
                        out.push((text.clone(), y1, x1.min(x2), x1.max(x2)));
                    }
                }
            }
        }
    }
    out
}

/// #1187 (`one_line_arm_rows_1187`): in a conditional written on one line
/// whose arms each move two values (`let (a, b) = if c { (f, g) } else {
/// (h, k) };`), an arm's second arrow ran along the next arm's row and
/// the last arm's along the join's: through their dots, and along the
/// other arm's arrows, so only one of them could be hovered. No arrow may
/// now run through a dot, nor along another arrow.
#[test]
fn one_line_arms_that_stack_arrows_get_rows_of_their_own() {
    let rv = run_with_local_backend("one_line_arm_rows_1187");
    let tl = rv.timeline_panel_string();
    let runs = arrow_horizontal_runs(&tl);
    assert!(runs.len() >= 10, "expected the arms' arrows: {:?}", runs);
    assert_eq!(arrow_row_problems(&tl), Vec::<String>::new());
}

/// Arrows whose horizontal runs cross a dot (other than at a hop) or
/// share a stretch of a row with another arrow: only one of the two can
/// be hovered there. Arrows are told apart by `data-rv-id`, so two with
/// one text (each arm's `ra -> a` return) count too.
fn arrow_row_problems(tl: &str) -> Vec<String> {
    let runs = arrow_horizontal_runs_by_id(tl);
    let dots = dot_centres(tl);
    let mut problems = Vec::new();
    for (text, y, lo, hi) in &runs {
        for &(cx, cy) in &dots {
            if cy == *y && *lo < cx - 0.5 && cx + 0.5 < *hi {
                problems.push(format!("{:?} at y={} runs through the dot at x={}", text, y, cx));
            }
        }
    }
    for (i, (t1, y1, lo1, hi1)) in runs.iter().enumerate() {
        for (t2, y2, lo2, hi2) in &runs[i + 1..] {
            if t1 != t2 && y1 == y2 && lo1.max(*lo2) + 1.0 < hi1.min(*hi2) {
                problems.push(format!("{:?} and {:?} share the row y={} from x={} to x={}", t1, t2, y1, lo1.max(*lo2), hi1.min(*hi2)));
            }
        }
    }
    problems
}

/// #1200 and #1223 (`one_line_arm_events_1200_1223`): what happens on a
/// one-line arm whose arrows are stacked is drawn in order on the arm's
/// row. pr.0 is bound before it is moved (its binding was on the row
/// below its move), and a's println! borrow and drop share the dot of
/// its binding (they were on a row inserted below, with no code on it).
#[test]
fn a_one_line_arms_events_stay_on_its_row_in_order() {
    let rv = run_with_local_backend("one_line_arm_events_1200_1223");
    let tl = rv.timeline_panel_string();
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    for part in ["pr.0", "pr.1"] {
        let bound = ys(&format!("{} acquires ownership of a resource", part));
        let moved = ys(&format!("{}'s resource is moved", part));
        let ended = ys(&format!("{} goes out of scope. No resource is dropped.", part));
        assert_eq!(bound.len(), 2, "{}: one binding per function: {:?}", part, bound);
        assert_eq!(bound, moved, "{}: bound and moved on one dot, on the arm's row", part);
        for (b, e) in bound.iter().zip(&ended) {
            assert!(b < e, "{}: bound at y={} must be above its scope end at y={}", part, b, e);
        }
    }
    for v in ["a", "b"] {
        let bound = ys(&format!("{} acquires ownership of a resource", v));
        assert_eq!(bound.len(), 3, "{}: one binding per function: {:?}", v, bound);
        assert_eq!(ys(&format!("{} goes out of scope. Its resource is dropped.", v)), bound,
            "{}: dropped on the dot it is bound on", v);
        assert_eq!(ys(&format!("{}'s resource is immutably borrowed by println!; {} is read-only while the borrow is live", v, v)), bound,
            "{}: lent to println! on the dot it is bound on", v);
    }
}

/// #1260: the column headers of a fn after a conditional whose arms insert
/// rows (stacked arrows; #1187's rows of their own) sit one row above its
/// signature, like every other fn's. They sat a row higher per inserted
/// row, over the previous fn's code.
#[test]
fn headers_after_arms_that_insert_rows_sit_above_their_fn() {
    for (name, fns) in [
        ("one_line_arm_rows_1187", &[
            "fn two_and_one(c: bool, f: String, g: String, h: String) {",
            "fn one_and_two(c: bool, f: String, h: String, k: String) {",
            "fn three_arms(n: u8, f: String, g: String, h: String, k: String, x: String, y: String) {",
            "fn swap(s: String, t: String) {",
        ][..]),
        ("return_in_match_arm", &["fn main() {"]),
    ] {
        let rv = run_with_local_backend(name);
        let (code, tl) = (rv.code_panel_string(), rv.timeline_panel_string());
        let header_ys: Vec<f64> = start_tags(&tl, "text").into_iter()
            .filter(|t| t.contains("data-rv-id=\"hdr:"))
            .filter_map(|t| attr(t, "y")?.parse().ok())
            .collect();
        for f in fns {
            let sig = code_row_y(&code, f);
            assert!(header_ys.iter().any(|&y| (sig - 30.0 - y).abs() < 0.5),
                "{}: no header one row above `{}` (y={}): {:?}", name, f, sig, header_ys);
        }
    }
}


/// #1182 (`reborrow_outlives_repoint_1182`): a reborrow made through a
/// reference keeps what the reference pointed to borrowed until the
/// reborrow's last use, even after the reference is given another one.
#[test]
fn a_reborrow_keeps_its_lender_past_a_repoint() {
    let rv = run_with_local_backend("reborrow_outlives_repoint_1182");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    assert_eq!(ys("a's resource is no longer mutably borrowed"), vec![row(r#"println!("{} {}", first, r);"#)]);
    assert_eq!(ys("c's resource is no longer immutably borrowed"), vec![row(r#"println!("{} {}", part, q);"#)]);
    assert_eq!(ys("p's resource is no longer immutably borrowed"), vec![row(r#"println!("{} {}", n, t.name);"#)]);
    assert_eq!(ys("e's resource is no longer immutably borrowed"), vec![row(r#"println!("{} {}", one, u);"#)]);
    assert_eq!(ys("other's immutable borrow ends"), vec![row(r#"println!("{}", other);"#)]);
    assert_eq!(ys("g's resource is no longer mutably borrowed"), vec![row(r#"println!("{} {}", kept, w);"#)]);
    // Control: the reborrow is dead before the write: g2's loan ends at
    // its last use, as before.
    assert_eq!(ys("g2's resource is no longer mutably borrowed"), vec![row(r#"println!("{}", early);"#)]);
}

/// #1188 (`oneline_if_repoint_1188`): a reference re-pointed in a
/// conditional written on one line keeps its old lender borrowed until the
/// read after it, as the same conditional over several lines does.
#[test]
fn a_one_line_conditional_repoint_keeps_the_old_lender() {
    let rv = run_with_local_backend("oneline_if_repoint_1188");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    assert_eq!(ys("a's resource is no longer immutably borrowed"), vec![row(r#"println!("{}", r);"#)]);
    assert_eq!(ys("d's resource is no longer immutably borrowed"), vec![row(r#"println!("{}", q);"#)]);
    assert_eq!(ys("f's resource is no longer mutably borrowed"), vec![row("m.push('!');")]);
    assert_eq!(ys("h's resource is no longer immutably borrowed"), vec![row(r#"println!("{}", t);"#)]);
    assert_eq!(ys("k's resource is no longer immutably borrowed"), vec![row(r#"println!("{}", u);"#)]);
}

/// #1192 (`move_into_deref_one_dot_1192`): `*r = t;` draws one dot on p's
/// column, on the write's row, for the end of r's borrow and the drop of
/// p's old value (and the drop of p.name's on that row too).
#[test]
fn a_move_into_deref_gives_the_lender_one_dot() {
    let rv = run_with_local_backend("move_into_deref_one_dot_1192");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    let write = row("*r = t;");
    assert_eq!(ys("p's resource is no longer mutably borrowed"), vec![write]);
    assert_eq!(ys("p acquires ownership of a new resource; its previous resource is dropped"), vec![write]);
    assert_eq!(ys("p.name acquires ownership of a new resource; its previous resource is dropped"), vec![write]);
    let write = row("*q = u;");
    assert_eq!(ys("s's resource is no longer mutably borrowed"), vec![write]);
    assert_eq!(ys("s acquires ownership of a new resource; its previous resource is dropped"), vec![write]);
}

/// #1283 (`field_moves_with_struct_1283`): a struct moved as a whole
/// moves its fields on the same row, also when the line has a second
/// arrow (`r`'s borrow ending at `*r = t;`). main drew `t.name`'s move a
/// row below `t`'s, so t.name was drawn owned after t had moved.
#[test]
fn a_struct_s_fields_move_on_its_row() {
    let name = "field_moves_with_struct_1283";
    let rv = run_with_local_backend(name);
    let tl = rv.timeline_panel_string();
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    for (whole, parts, n) in [
        ("t", &["t.name", "t.inner", "t.inner.name"][..], 4),
        ("q", &["q.name"][..], 1),
    ] {
        let rows = ys(&format!("{whole}'s resource is moved"));
        assert_eq!(rows.len(), n, "{name}: {whole}'s moves at {rows:?}");
        for part in parts {
            let part_rows = ys(&format!("{part}'s resource is moved"));
            assert!(!part_rows.is_empty(), "{name}: no move of {part}");
            for y in part_rows {
                assert!(rows.iter().any(|r| (r - y).abs() < 1.0), "{name}: {part} moved at y={y}, not on a row where {whole} moves ({rows:?})");
            }
        }
    }
}

/// #1215: `match &mut t { (a, b) => { a.push('!'); b.push('?'); } }`
/// gives t back once, at b's last use (the loan the scrutinee makes lives
/// as long as either binding). It was given back at a's last use too,
/// drawing t as owner while b still borrowed it.
#[test]
fn a_match_on_a_borrow_of_a_whole_gives_it_back_once() {
    let name = "match_whole_borrow_parts_1215";
    let rv = run_with_local_backend(name);
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    for (end, last_use) in [
        ("t's resource is no longer mutably borrowed", "b.push('?');"),
        ("u's resource is no longer immutably borrowed", "println!(\"{}\", d);"),
        ("s's resource is no longer mutably borrowed", "y.push('2');"),
    ] {
        let row = code_row_y(&code, last_use);
        let ends = dots_listing_tooltip(&timeline, end);
        assert_eq!(ends.len(), 1, "{name}: {end:?} at {ends:?}, expected once");
        assert!((ends[0].1 - row).abs() < 1.0, "{name}: {end:?} at y={}, expected the row of `{last_use}` (y={row})", ends[0].1);
    }
}

/// #1203 (`closure_static_write_1203`): calling a closure that assigns a
/// `static mut` writes the static on the call's row (main drew nothing
/// there).
#[test]
fn a_closure_call_writes_the_static_it_names() {
    let rv = run_with_local_backend("closure_static_write_1203");
    let ids: Vec<String> = common::svg::rv_elements(&rv.timeline_panel_string()).into_iter().map(|e| e.id).collect();
    for id in ["COUNT@L6:dot:acquire", "COUNT@L8:dot:acquire"] {
        assert!(ids.iter().any(|i| i == id), "no {:?} in {:#?}", id, ids);
    }
}

/// #1195 (`call_arg_before_try_1195`): a call's arguments are all
/// evaluated before the call takes any, so in `take(s, bar()?)`,
/// `q.put(w, bar()?)` and `q.eat(bar()?)` (by-value `self`) the `?` can
/// return early while s / w / q's value sits in an evaluated argument: it
/// is dropped then. That's said on the dot of the line the value is moved
/// on, next to the move. Main drew only the move.
#[test]
fn a_try_after_an_argument_drops_what_the_argument_holds() {
    let rv = run_with_local_backend("call_arg_before_try_1195");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    for (name, line) in [("s", "take(s, bar()?);"), ("w", "q.put(w, bar()?);"), ("q", "q.eat(bar()?);")] {
        let drop = format!("If the `?` here returns early, {name}'s resource is dropped.");
        let ys: Vec<f64> = dots_where(&tl, |lines| lines.iter().any(|l| l.starts_with(&drop))
            && lines.iter().any(|l| *l == format!("{name}'s resource is moved")))
            .into_iter().map(|(_, y)| y).collect();
        assert_eq!(ys, vec![row(line)], "{name}: the `?` drop and the move belong on one dot on {line:?}");
    }
}

/// #1127 (`struct_ref_field_moved_1127`): a struct moved into `drop` takes
/// its reference field with it, so the field's borrow ends on the `drop`
/// row, not at the last use of a copy of the reference.
#[test]
fn a_ref_field_ends_where_its_struct_is_moved_into_a_call() {
    let rv = run_with_local_backend("struct_ref_field_moved_1127");
    let (tl, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let row = |src: &str| code_row_y(&code, src);
    let ys = |text: &str| -> Vec<f64> { dots_listing_tooltip(&tl, text).into_iter().map(|(_, y)| y).collect() };
    assert_eq!(ys("e.part's immutable borrow ends"), vec![row("drop(e);")]);
    assert_eq!(ys("f.part's immutable borrow ends"), vec![row("drop(f);")]);
    assert_eq!(ys("o.ex.part's immutable borrow ends"), vec![row("drop(o);")]);
}

/// #1198: a value holding a borrow (`o: Option<Part>`), moved by a
/// pattern into a binding whose reference field takes the borrow on
/// (`if let Some(x) = o`, `Some(y) =>` on `p`), draws no end of the borrow
/// in that arm: x.part / q / y.part end it. Only the other arm, where o /
