/// Centres of the `<circle>`s (event dots) and anchors of the function
/// logos (`f`) of a timeline panel, and its column headers' anchors.
fn marks_and_headers(timeline: &str) -> (Vec<(f64, f64, String)>, Vec<(f64, f64)>, Vec<(f64, f64, String)>) {
    let doc = roxmltree::Document::parse(timeline).expect("timeline svg parses");
    let xy = |n: roxmltree::Node, x: &str, y: &str| -> Option<(f64, f64)> {
        Some((n.attribute(x)?.parse().ok()?, n.attribute(y)?.parse().ok()?))
    };
    let id = |n: roxmltree::Node| n.ancestors().find_map(|a| a.attribute("data-rv-id")).unwrap_or("").to_owned();
    let dots = doc.descendants().filter(|n| n.has_tag_name("circle"))
        .filter_map(|n| xy(n, "cx", "cy").map(|(x, y)| (x, y, id(n)))).collect();
    let class_has = |n: &roxmltree::Node, c: &str| n.attribute("class").is_some_and(|k| k.split(' ').any(|w| w == c));
    let logos = doc.descendants().filter(|n| n.has_tag_name("text") && class_has(n, "functionLogo"))
        .filter_map(|n| xy(n, "x", "y")).collect();
    let headers = doc.descendants().filter(|n| n.has_tag_name("text") && class_has(n, "label"))
        .filter_map(|n| xy(n, "x", "y").map(|(x, y)| (x, y, id(n)))).collect();
    (dots, logos, headers)
}

/// #1342: a one-line conditional on its fn's signature line forks a row
/// above the signature, where the fn's column headers were drawn: the
/// fork dots and the condition's call logo sat on the headers (`fn pick(x,
/// y) -> &str { if x.len() > 3 { x } else { y } }`; also a one-line
/// `match`, `if` without `else`, `if let`, `let x = if …`, a struct's
/// fields, and the join of one one-line fn on the next one's headers).
/// The headers go a row higher, so no dot or logo is drawn on a header.
#[test]
fn one_line_conditionals_keep_off_the_column_headers() {
    let mut bad = Vec::new();
    for name in ["one_line_if_on_header_row_1342", "outlives_bound_1125", "one_line_diamond_1306_1308_1309"] {
        let (dots, logos, headers) = marks_and_headers(&run_with_local_backend(name).timeline_panel_string());
        // A header's text runs about a row's half-height above its
        // baseline and some 20px either side of its anchor.
        let on = |(hx, hy): (f64, f64), (x, y): (f64, f64)| (x - hx).abs() < 20.0 && y > hy - 18.0 && y < hy + 8.0;
        for (hx, hy, h) in &headers {
            for (x, y, d) in &dots {
                if on((*hx, *hy), (*x, *y)) {
                    bad.push(format!("{name}: dot {d} at ({x}, {y}) on header {h} at ({hx}, {hy})"));
                }
            }
            for (x, y) in &logos {
                if on((*hx, *hy), (*x, *y)) {
                    bad.push(format!("{name}: a call's logo at ({x}, {y}) on header {h} at ({hx}, {hy})"));
                }
            }
        }
    }
    assert_eq!(bad, Vec::<String>::new());
}

/// #1374: an arm written on the conditional's last line (`} else {
/// take(s); }`, a `match`'s last arm before its `}`, `} else if d {
/// take(s); }`, the `else` of a `let n = if …`) has its dots on that
/// line's row. The join used to sit there too, beside the arm's dot,
/// with the arm's arrow to `take`'s logo running through it and the logo
/// on top of it (and a lender's join beside the dot a borrow's end
/// returns to, the arrow hopping over it). The join is now a row below.
#[test]
fn joins_sit_below_their_arms_dots() {
    let mut bad = Vec::new();
    for name in [
        "join_below_arm_on_closing_row_1374", "else_on_join_line", "fmt_macro_args_824",
        "reborrow_through_local_mut_ref_1152", "if_let_holder_end_row_712", "mut_ref_moved_into_result_1128",
        "one_line_join_below_1392",
    ] {
        let (dots, logos, _) = marks_and_headers(&run_with_local_backend(name).timeline_panel_string());
        for (jx, jy, j) in dots.iter().filter(|(_, _, id)| id.contains(":dot:branch_join")) {
            let var = j.split('@').next().unwrap_or("");
            for (x, y, d) in &dots {
                if d != j && d.starts_with(&format!("{var}@")) && (y - jy).abs() < 1.0 && (x - jx).abs() < 30.0 {
                    bad.push(format!("{name}: {j} at ({jx}, {jy}) level with {d} at ({x}, {y})"));
                }
            }
            for (x, y) in &logos {
                if (x - jx).abs() < 14.0 && (y - jy).abs() < 14.0 {
                    bad.push(format!("{name}: a call's logo at ({x}, {y}) on {j} at ({jx}, {jy})"));
                }
            }
        }
    }
    // #1392: a one-line conditional whose arm stacks arrows on rows below
    // its line (`if let Some(x) = k2 { x.push('!'); }`, also a one-line
    // `match`, `} else { }`, in a loop, nested in an arm, two in a row)
    // joins a row below the arm's last dot; it sat level with s's "no
    // longer mutably borrowed" dot.
    assert_eq!(bad, Vec::<String>::new());
}

/// #1380: an `else if` arm given a row of its own below its `} else if
/// look(r) {` line (that row's arrows overlapped the end of the arm
/// before) still starts on that line: the leg beside it is the arm's own
/// (r holds its reference there), not dashed "This segment is for the
/// else branch. The underlined code is not part of that branch." (also
/// `else if let`, a third arm, a conditional nested in an arm).
#[test]
fn else_if_arm_starts_on_its_condition_row() {
    let tl = run_with_local_backend("else_if_condition_row_1380").timeline_panel_string();
    for line in [11, 20, 30, 40] {
        for v in ["e", "r"] {
            let id = format!("{v}@L{line}:branch_line:partial_privilege");
            assert!(tl.contains(&format!("data-rv-id=\"{id}\"")), "no {id}");
            assert!(!tl.contains(&format!("data-rv-id=\"{id}_gray\"")), "{id}_gray beside the arm's own condition");
        }
    }
}

/// #1375: a diverging arm's stop bar ("This branch stops here") was
/// drawn centred on the arm's last dot when that dot was on the arm's
/// last row (`return take(q);`, `return q + "!";`), so the dot covered
/// it but for a 1px nub. Where the dot ends the column (a move, a drop,
/// a borrow's end) the column ends at the dot, with no bar, as a one-row
/// arm's does (#1295); where the column is still live there (`s.push(..);
/// break;`, a panic with a value that isn't dropped) the bar goes a
/// little below the dot. No stop bar in the corpus is under a dot.
#[test]
fn stop_bars_are_not_under_dots() {
    let mut names = all_fixtures();
    let skipped: Vec<&str> = SKIP_WELL_FORMED.iter().map(|(n, _)| *n).collect();
    names.retain(|n| !skipped.contains(&n.as_str()));
    prerender(names.iter().map(|n| n.as_str()));
    let mut bad = Vec::new();
    for name in &names {
        let Ok(rv) = render_cell(name) else { continue };
        let tl = rv.timeline_panel_string();
        let doc = roxmltree::Document::parse(&tl).expect("timeline svg parses");
        let dots: Vec<(f64, f64)> = doc.descendants().filter(|n| n.has_tag_name("circle"))
            .filter_map(|c| Some((c.attribute("cx")?.parse().ok()?, c.attribute("cy")?.parse().ok()?)))
            .collect();
        for bar in doc.descendants().filter(|n| n.has_tag_name("line") && n.attribute("data-rv-id").is_some_and(|i| i.ends_with(":stop_bar"))) {
            let num = |a: &str| bar.attribute(a).and_then(|v| v.parse::<f64>().ok()).unwrap_or(f64::NAN);
            let (x, y) = ((num("x1") + num("x2")) / 2.0, num("y1"));
            if dots.iter().any(|(cx, cy)| (cx - x).abs() < 1.0 && (cy - y).abs() < 6.0) {
                bad.push(format!("{name}: {} at ({x}, {y}) is under a dot", bar.attribute("data-rv-id").unwrap_or("")));
            }
        }
    }
    assert_eq!(bad, Vec::<String>::new());
    // The live columns' bars are there, below their dots.
    let tl = run_with_local_backend("stop_bar_under_dot_1375").timeline_panel_string();
    for id in ["s@L33:stop_bar"] {
        assert!(tl.contains(&format!("data-rv-id=\"{id}\"")), "stop_bar_under_dot_1375: no {id}");
    }
    for id in ["q@L7:stop_bar", "q@L15:stop_bar", "q@L22:stop_bar"] {
        assert!(!tl.contains(&format!("data-rv-id=\"{id}\"")), "stop_bar_under_dot_1375: {id} under q's move");
    }
}

/// #1370, #1338: a reference whose borrow ends in every arm of a
/// conditional. Each arm runs on from where the borrow ended, dashed
/// ("r's borrow has ended on this path"), to the join dot that says "r's
/// borrow ended in each branch above": as many legs come into that join
/// as leave its fork. main stopped the last arm's leg at the dot where
/// its borrow ended (the arm had no rows left below it): an `if` /
/// `else`, a `match`, an `if let`, a local `&mut`, an arm that doesn't
/// use the reference, and an `else if use(r)` whose condition is r's last
/// use, where nothing left the call's dot (#1338).
#[test]
fn every_arm_that_ended_a_borrow_reaches_the_join() {
    for name in ["ended_borrow_join_legs_1370", "field_write_through_ref_branch", "outer_mut_ref_end_in_if_arm"] {
        let tl = run_with_local_backend(name).timeline_panel_string();
        let legs = branch_leg_centrelines(&tl);
        let dots: Vec<(String, String, String, f64, f64)> = start_tags(&tl, "circle").into_iter().filter_map(|t| Some((
            attr(t, "data-hash")?.to_string(),
            attr(t, "data-rv-id")?.to_string(),
            attr(t, "data-rv-event").unwrap_or("").to_string(),
            attr(t, "cx")?.parse().ok()?,
            attr(t, "cy")?.parse().ok()?,
        ))).collect();
        let near = |x: f64, y: f64, px: f64, py: f64| (x - px).abs() < 1.0 && (y - py).abs() < 1.0;
        // Legs of column `hash` with an end at (x, y) and the other end
        // below it (`down`) or above it.
        let count = |hash: &str, x: f64, y: f64, down: bool| legs.iter().filter(|(h, _, [x1, y1, x2, y2])| h == hash && (
            (near(*x1, *y1, x, y) && if down { *y2 > y + 1.0 } else { *y2 < y - 1.0 })
            || (near(*x2, *y2, x, y) && if down { *y1 > y + 1.0 } else { *y1 < y - 1.0 }))).count();
        let mut checked = 0;
        let mut bad = Vec::new();
        for (hash, id, _, x, y) in dots.iter().filter(|d| d.2 == "branch_join") {
            let tip = start_tags(&tl, "circle").into_iter().find(|t| attr(t, "data-rv-id") == Some(id.as_str()))
                .and_then(|t| attr(t, "data-tooltip-text")).unwrap_or("");
            if !tip.contains("borrow ended in each branch above") {
                continue;
            }
            // Its fork: the nearest split dot above it on its x.
            let Some(fork) = dots.iter().filter(|d| &d.0 == hash && d.2 == "branch" && (d.3 - x).abs() < 1.0 && d.4 < *y)
                .max_by(|a, b| a.4.total_cmp(&b.4)) else { continue };
            let (out, into) = (count(hash, fork.3, fork.4, true), count(hash, *x, *y, false));
            checked += 1;
            if out != into {
                bad.push(format!("{}: {} legs leave the fork {}, {} reach the join", id, out, fork.1, into));
            }
        }
        assert!(checked > 0, "{}: no join of a borrow that ended in every arm", name);
        assert_eq!(bad, Vec::<String>::new(), "{}", name);
    }
}

/// #1345: `*b = …` on a Box drawn as one column drops the old contents
/// on the write's dot (the drop mark of `owner_drop_at_reassign`), as `v
/// = w` does; a Box drawn as its payload's parts gets one dot for the
/// write, whatever the right-hand side (`*b2 = o` had a second dot for
/// the drop, a row below).
#[test]
fn box_deref_write_drop_marks() {
    let tl = run_with_local_backend("box_deref_write_1345").timeline_panel_string();
    for id in ["b@L12", "b3@L14", "b4@L21", "b2@L18"] {
        let dots: Vec<&str> = tl.match_indices(&format!("data-rv-id=\"{}:dot:", id))
            .map(|(i, _)| { let rest = &tl[i + 12..]; &rest[..rest.find('"').unwrap()] })
            .collect();
        assert_eq!(dots, vec![format!("{}:dot:acquire+owner_drop_at_reassign", id).as_str()], "{}'s dots at the write", id);
    }
}

/// #1343: a swap or rotation by destructuring assignment draws one dot
/// per target on its line; the first target had two, with a gap in its
/// column between them.
#[test]
fn destructure_cycle_one_dot_per_target() {
    let tl = run_with_local_backend("destructure_cycle_1343").timeline_panel_string();
    for (line, vars) in [(11, &["a", "b"][..]), (13, &["a", "b", "c"][..]), (16, &["p", "p.name", "q", "q.name"][..]), (21, &["m1", "m2"][..])] {
        for v in vars {
            let ids: Vec<&str> = tl.match_indices(&format!("data-rv-id=\"{}@L{}:dot:", v, line))
                .map(|(i, _)| { let rest = &tl[i + 12..]; &rest[..rest.find('"').unwrap()] })
                .collect();
            assert_eq!(ids.len(), 1, "{} has dots {:?} on line {}", v, ids, line);
            // Its value moves out, then the new one arrives.
            assert!(ids[0].ends_with("move+acquire") && !ids[0].contains("acquire+move"), "{} on line {}: {}", v, line, ids[0]);
        }
    }
}

/// #1411, #1421: the order of the events on one dot. `p.b` in `p = Pair {
/// a: .., b: p.b }` is moved out before it gets its value back (main:
/// acquire, then move, and its column ended). A holder in a nested branch
