/// #1460: the join of a conditional that may move a value (o, a, b, e:
/// a let-chain `if`; g: a `match` guard) is a dot on its own row, also
/// when the column's next event is a later conditional that may assign
/// the value. With no line reaching it, its text went on that
/// conditional's dots: the first dot of each arm and its join (o@L25 and
/// o@L26 on main), as if about that conditional. p's join was drawn
/// already (the `if` that moves p has an `else` path that keeps it).
#[test]
fn maybe_moved_join_stays_on_its_row_1460() {
    let tl = run_with_local_backend("edition2024/let_chain_join_before_if_1460").timeline_panel_string();
    let tips = tooltip_lines(&tl);
    for (v, join, kw) in [("o", 23, "if"), ("a", 34, "if"), ("g", 51, "match"), ("b", 62, "if"), ("e", 94, "if"), ("p", 79, "branches")] {
        assert!(tl.contains(&format!("data-rv-id=\"{v}@L{join}:dot:branch_join\"")), "{v}: no join dot of its own on line {join}");
        let start = if kw == "branches" {
            format!("{v} was moved in at least one branch above, so it can't be used after the branches until")
        } else {
            format!("{v} may have been moved above, so it can't be used after the {kw}")
        };
        let at: Vec<&Vec<String>> = tips.iter().filter(|t| t.iter().any(|l| l.starts_with(&start))).collect();
        assert_eq!(at.len(), 1, "{v}: the join's text is on {} dots: {:?}", at.len(), at);
        assert_eq!(at[0].len(), 1, "{v}: the join's dot says more than the join: {:?}", at[0]);
    }
}

/// #1441: in a one-line arm with several arrows on its line, the value a
/// call gives the arm's variable (`{ let y = String::from("y"); y }`) or
/// temporary (`&String::from("pos")`) arrives on the dot where it is moved
/// or lent on to the `let`, not on a row below it.
#[test]
fn one_line_arm_value_arrives_before_it_moves_1441() {
    let rv = run_with_local_backend("guard_arm_pairing_row_1441");
    let dots = tooltip_lines(&rv.timeline_panel_string());
    let on_dot = |leaves: &str, arrives: &str| {
        let found: Vec<&Vec<String>> = dots.iter().filter(|d| d.iter().any(|t| t.starts_with(leaves))).collect();
        assert!(!found.is_empty(), "no dot says {leaves:?}");
        for d in found {
            assert!(d.iter().any(|t| t.starts_with(arrives)), "the dot saying {leaves:?} doesn't say {arrives:?}: {d:?}");
        }
    };
    on_dot("y's resource is moved", "y acquires ownership of a resource");
    on_dot("(temporary)'s resource is immutably borrowed by r", "(temporary) acquires ownership of a resource");
}

/// #1436: an exit after the conditional that assigned a `let x;` local in
/// some branches only states the drop of its value if it has one, on the
/// exit's row: `return`, `break` and `continue` out of the loop it is
/// declared in, a panic (a `?` and a branch temporary's exits are pinned
/// in `EXPECTED_TOOLTIPS`). So does an exit after a conditional that
/// assigned it in every branch.
#[test]
fn exits_state_maybe_init_drops_1436() {
    let rv = run_with_local_backend("exit_maybe_init_1436");
    let (timeline, code) = (rv.timeline_panel_string(), rv.code_panel_string());
    let flag = |n: &str| format!("{n} goes out of scope. Its resource is dropped here only if {n} was assigned in the branch that ran (Rust tracks this with a runtime drop flag).");
    let at = |text: &str, src: &str, y: f64| {
        let dots = dots_listing_tooltip(&timeline, text);
        assert!(dots.iter().any(|&(_, dy)| dy == y), "no dot saying {text:?} at {src:?} (y={y}): {dots:?}");
    };
    let returns = code_rows_y(&code, "return;");
    assert_eq!(returns.len(), 4, "return; rows: {returns:?}");
    at(&flag("s"), "at_return: return;", returns[0]);
    at(&flag("s"), "after_match: return;", returns[1]);
    at(&flag("p"), "whole_struct: return;", returns[2]);
    at("s goes out of scope. Its resource is dropped.", "every_branch: return;", returns[3]);
    at(&flag("s"), "in_loop: break;", code_rows_y(&code, "break;")[0]);
    at(&flag("s"), "in_loop: continue;", code_row_y(&code, "continue;"));
    at(&flag("s"), "at_panic", code_row_y(&code, "panic!(\"no\");"));
}

/// #1391: `*b = ..` on a Box in a condition (plain `if`, match guard,
/// `while let` chain, `if let` chain) has the drop mark on the write's
/// dot, as outside a condition (#1345); it had none, or a dot of its own
/// after the condition's later events (after `let c = b;` moved b).
#[test]
fn box_write_in_condition_drop_marks() {
    let dots_of = |tl: &str, id: &str| -> Vec<String> {
        tl.match_indices(&format!("data-rv-id=\"{}:dot:", id))
            .map(|(i, _)| { let rest = &tl[i + 12..]; rest[..rest.find('"').unwrap()].to_owned() })
            .collect()
    };
    let tl = run_with_local_backend("edition2024/box_write_in_condition_1391").timeline_panel_string();
    for id in ["b@L8", "b@L13", "b@L17", "b@L21"] {
        let dots = dots_of(&tl, id);
        assert!(dots.iter().any(|d| d.starts_with(&format!("{}:dot:acquire+owner_drop_at_reassign", id))), "{}'s dots: {:?}", id, dots);
        assert!(!dots.iter().any(|d| d.contains(":dot:owner_drop_at_reassign")), "{}'s drop on a dot of its own: {:?}", id, dots);
    }
    let tl = run_with_local_backend("edition2024/chain_write_then_move_603").timeline_panel_string();
    let dots = dots_of(&tl, "b@L4");
    assert!(dots.iter().any(|d| d == "b@L4:dot:acquire+owner_drop_at_reassign+move"), "b's dots: {:?}", dots);
    let tl = run_with_local_backend("edition2024/if_let_chain_box_write").timeline_panel_string();
    let dots = dots_of(&tl, "b@L7");
    assert!(dots.iter().any(|d| d == "b@L7:dot:acquire+owner_drop_at_reassign"), "b's dots: {:?}", dots);
}

/// #1393: `r = if c { let y = &a; y } else { &b };` with r a reference
/// copies y into r in y's branch, before y goes out of scope: y's dot
/// that says its reference is copied comes before its scope end on that
/// row (it came after: the copy was drawn after the conditional).
/// #1431, #1432: where a reference given a new value by a conditional
/// gives its lenders back. `(snippet, data-rv-id prefixes that must be
/// there, prefixes that must not)`.
#[test]
fn branch_ref_borrow_ends() {
    for (snippet, present, absent) in [
        // t (else branch) and s (through w) are borrowed by m until its
        // last use, line 10; w has nothing after its scope end on line 9.
        ("assign_branch_mut_ref_arms_1393",
         &["t@L10:dot:mutable_reacquire", "s@L10:dot:mutable_reacquire"][..],
         &["t@L9:dot:branch_join+mutable_reacquire", "w@L10:"][..]),
        ("assign_branch_reborrow_arm_1431",
         &["s@L12:dot:mutable_reacquire", "t@L12:dot:mutable_reacquire", "t@L17:dot:mutable_reacquire"][..],
         &["w@L12:", "w2@L17:"][..]),
        // r's loan of line 16 ends on line 17 (v, b and a given back); y
        // has nothing after its scope end on line 16.
        ("assign_branch_ref_arms_1393",
         &["v@L17:dot:static_reacquire", "b@L17:dot:static_reacquire", "a@L17:dot:static_reacquire"][..],
         &["y@L17:"][..]),
        // b given back at r's last use (12), a at z's (13); r's old
        // borrow doesn't end at the write (14).
        ("ref_reassign_co_lenders_1432",
         &["b@L12:dot:static_reacquire", "a@L13:dot:static_reacquire"][..],
         &["r@L14:dot:static_die"][..]),
    ] {
        let tl = run_with_local_backend(snippet).timeline_panel_string();
        for id in present {
            assert!(tl.contains(&format!("data-rv-id=\"{}", id)), "{}: no {}", snippet, id);
        }
        for id in absent {
            assert!(!tl.contains(&format!("data-rv-id=\"{}", id)), "{}: unexpected {}", snippet, id);
        }
    }
}

