        assert!(!lines.iter().any(|(id, t, ..)| id.contains("-6:line:") && t.contains("may have been moved out")));
        check_review_tip(&svg, &format!("{name}@L5:dot:"), &["break", "is dropped here"], &["return", "caller"]);
